INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1845673943269249024, 'e052afd715134b49930dbd3bea7b78e2', 'https://vrast.cn/posts/65207/', 1845673867633364992, 2, '2024-10-14 12:15:14.731884', '2024-10-14 12:15:59.249523', '44.52', 2, '{"Url":"https://vrast.cn/posts/65207/","Title":"移动同步过程中载具平台旋转问题 | Keyle''s Blog","Content":"🌓var prefersDarkMode = window.matchMedia(''(prefers-color-scheme: dark)'');\nvar toggle = document.querySelector(''.darkmode-toggle'');\nvar html = document.querySelector(''html'');\ntoggle.id = ''darkmodeBtn'';\n\nhtml.dataset.dark = localStorage.dark || prefersDarkMode.matches;\n\ntoggle.addEventListener(''click'', () => {\nlocalStorage.dark = !(html.dataset.dark == ''true'');\nhtml.dataset.dark = localStorage.dark;\n});\n\ntoggle.style.opacity = 0;\nlet timer;\nwindow.addEventListener(''scroll'', function () {\n  clearTimeout(timer);\n  toggle.style.opacity = 1;\n  timer = setTimeout(() => {\n    toggle.style.opacity = 0;\n  }, 3000);\n});移动同步过程中载具平台旋转问题Keyle''s Blog在这里记录一些偶尔冒出来转眼就会忘的灵感。 首页 归档 说说 笔记 订阅 开往 虫洞 关于移动同步过程中载具平台旋转问题2024-07-22 | 开发 |  506 字 |  1 分钟 |   条评论现在有这么一个问题，玩家在游戏中乘坐上了一个会自己旋转的载具，导致玩家的坐标被动变化。\n一般情况下在游戏中我们处理玩家的移动同步参考如下，考虑玩家当前点与上一次的同步点是否出现偏移，以及其他规则检测出的差值（朝向，状态，周期等），如果检出需要同步，则立即上报当前位置信息。\n对于这种状态该如何比较好的检出玩家的位移变化呢 ?\n\n\n\n刚开始我认为这个检出的过程应该这样：需要综合 上一次同步点 与 上一次同步的载具旋转角度与当前载具的旋转角度差值，然后三角函数计算出预测下一个落点。再将这个落点与当前要同步的点进行匹配。如果是一个点就不进行同步。\n这个判定的计算非常繁琐，还需要额外记录载具的角度变化，那么有什么办法不看载具信息吗 ？\n我们再分析下这个需求，载具平台旋转，子物体跟转，相对静止。有句话是这样说的，当你不知道解题思路，你把题干抄下来，也是能得分的。没错，答案就是 相对静止。\n由于是相对静止（船心坐标O），向量 OA蓝色 与 OA红色 他们的长度是没有变化的。也就意味着，只需要计算上一次同步的相对位置与当前位置的长度差值。就可以判断玩家是否在载具平台上有位移。\n1bool isMove = Mathf.Abs( lastSyncRelPosition.magnitude - currentRelPosition.magnitude) > 0.01f\n当然也可以优化成下面这样,不开方更省一些性能：\n1bool isMove = Mathf.Abs( lastSyncRelPosition.sqrMagnitude - currentRelPosition.sqrMagnitude) > 0.01f\n\n大概如此，当然精度可以根据不同的需求进行调整。好了，今天的分享就到这，下期再会 ！\n本文标题：移动同步过程中载具平台旋转问题文章作者：Keyle发布时间：2024-07-22最后更新：2024-08-20原始链接：https://vrast.cn/posts/65207/版权声明：©Keyle''s Blog. 本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可位置同步拍照选择 4:3 还是 16:9 的画面比例谈马保国舆论回暖twikoo.init({\n  envId: ''https://twikoo.vrast.cn'',\n  el: ''#tcomment'',\n  region: '''',\n  path: '''',\n  onCommentLoaded: function () {\n    const commentCountElement = document.querySelector(''.tk-comments-count'');\n    const targetElement = document.querySelector(''.waline-comment-count'');\n    if (commentCountElement) {\n      const countSpan = commentCountElement.querySelector(''span:first-child'');\n      const commentCount = parseInt(countSpan.textContent);\n      targetElement.textContent = commentCount;\n    } else {\n      console.log(''未找到评论数量元素'');\n    }\n  }\n})window.addEventListener(''load'', function(){\nconst targetDiv = document.querySelector(''.pure-u-1-4.hidden_mid_and_down'');\nif (targetDiv) {\n  targetDiv.parentNode.removeChild(targetDiv);\n}\n\n// 修改 id 为 layout 的 div 的样式\nconst layoutDiv = document.getElementById(''layout'');\nif (layoutDiv) {\n  layoutDiv.style.flexFlow = ''row wrap'';\n  layoutDiv.style.alignContent = ''center'';\n  layoutDiv.style.flexDirection = ''row-reverse'';\n  layoutDiv.style.justifyContent = ''center'';\n  layoutDiv.style.alignItems = ''center'';\n}\n\n// 设置 id 为 header 的元素高度为 60px\nconst header = document.getElementById(''header'');\nif (header) {\n  header.style.height = ''auto'';\n}\n\n// 设置 id 为 nav-menu 的元素样式\nconst navMenu = document.getElementById(''nav-menu'');\nif (navMenu) {\n  navMenu.style.margin = ''10px 0 -1px'';\n  navMenu.style.padding = ''0'';\n  navMenu.style.position = ''unset'';\n  navMenu.style.right = ''0'';\n  navMenu.style.bottom = ''0'';\n  navMenu.style.display = ''flex'';\n  navMenu.style.flexDirection = ''row'';\n  navMenu.style.flexWrap = ''wrap'';\n  navMenu.style.alignContent = ''center'';\n  navMenu.style.alignItems = ''center'';\n  navMenu.style.justifyContent = ''center'';\n}\n\n// 删除带有 site-name 类的 div\nconst siteNameDiv = document.querySelector(''.site-name'');\nif (siteNameDiv) {\n  siteNameDiv.parentNode.removeChild(siteNameDiv);\n}\n});  沪ICP备20024028号-1 本站由 @Keyle  创建，采用 Maupassant 作为主题，您可以在 GitHub 找到本站源码 © Keyle''s Blog .  本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可 时光匆匆而过，本站已经创立距今已有0 天var s1 = ''2016-11-14'';\ns1 = new Date(s1.replace(/-/g, \"/\"));\ns2 = new Date();\nvar days = s2.getTime() - s1.getTime();\nvar number_of_days = parseInt(days / (1000 * 60 * 60 * 24));\ndocument.getElementById(''days'').innerHTML = number_of_days;var search_path = ''search.xml'';\nif (search_path.length == 0) {\n  search_path = ''search.xml'';\n}\nvar path = ''/'' + search_path;\nsearchFunc(path, ''local-search-input'', ''local-search-result'');\n\n        \n            [bg-lazy] {\n                background-image: none !important;\n                background-color: #eee !important;\n            }\n        \n        \n            window.imageLazyLoadSetting = {\n                isSPA: false,\n                preloadRatio: 1,\n                processImages: null,\n            };\n        window.addEventListener(\"load\",function(){var t=/\\.(gif|jpg|jpeg|tiff|png)$/i,r=/^data:image\\/[a-z]+;base64,/;Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")).forEach(function(a){var e=a.parentNode;\"A\"===e.tagName&&(e.href.match(t)||e.href.match(r))&&(e.href=a.dataset.original)})});(r=>{r.imageLazyLoadSetting.processImages=t;var a=r.imageLazyLoadSetting.isSPA,o=r.imageLazyLoadSetting.preloadRatio||1,d=i();function i(){var t=Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")),e=Array.prototype.slice.call(document.querySelectorAll(\"[bg-lazy]\"));return t.concat(e)}function t(t){(a||t)&&(d=i());for(var e,n=0;n<d.length;n++)0<=(e=(e=d[n]).getBoundingClientRect()).bottom&&0<=e.left&&e.top<=(r.innerHeight*o||document.documentElement.clientHeight*o)&&(()=>{var t,e,a,o,i=d[n];e=function(){d=d.filter(function(t){return i!==t}),r.imageLazyLoadSetting.onImageLoaded&&r.imageLazyLoadSetting.onImageLoaded(i)},(t=i).dataset.loaded||(t.hasAttribute(\"bg-lazy\")?(t.removeAttribute(\"bg-lazy\"),e&&e()):(a=new Image,o=t.getAttribute(\"data-original\"),a.onload=function(){t.src=o,t.removeAttribute(\"data-original\"),t.setAttribute(\"data-loaded\",!0),e&&e()},a.onerror=function(){t.removeAttribute(\"data-original\"),t.setAttribute(\"data-loaded\",!1),t.src=o},t.src!==o&&(a.src=o)))})()}function e(){clearTimeout(t.tId),t.tId=setTimeout(t,500)}t(),document.addEventListener(\"scroll\",e),r.addEventListener(\"resize\",e),r.addEventListener(\"orientationchange\",e)})(this);"}', '2024-10-14 11:52:13.696034', 'admin', '2024-10-14 12:15:59.24971', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1777983111246778368, 'da08a0e5981244afa719ca287c3495a4', '5c57b939949b4d768285da537ad572ff', 100, 2, '2024-04-10 17:06:05.035536', '2024-04-10 17:06:09.843791', '4.81', 1, '赵客缦胡缨，吴钩霜雪明。银鞍照白马，飒沓如流星。
十步杀一人，千里不留行。事了拂衣去，深藏身与名。
闲过信陵饮，脱剑膝前横。将炙啖朱亥，持觞劝侯嬴。
三杯吐然诺，五岳倒为轻。眼花耳热后，意气素霓生。
救赵挥金槌，邯郸先震惊。千秋二壮士，煊赫大梁城。
纵死侠骨香，不惭世上英。谁能书閤下，白首太玄经。', '2024-04-10 16:53:01.706855', 'admin', '2024-04-10 17:06:09.843798', 'admin');
