INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1845669235888623616, 'c2774606c16343dc88e4657ed2426c32', '给网站首页的文章标题下添加评论预览 | Keyle''s Blog', 1845669125859446784, 2, '2024-10-14 11:34:23.283086', '2024-10-14 11:40:05.028697', '341.75', 2, '{"Url":"https://vrast.cn/posts/64318/","Title":"给网站首页的文章标题下添加评论预览 | Keyle''s Blog","Content":"🌓var prefersDarkMode = window.matchMedia(''(prefers-color-scheme: dark)'');\nvar toggle = document.querySelector(''.darkmode-toggle'');\nvar html = document.querySelector(''html'');\ntoggle.id = ''darkmodeBtn'';\n\nhtml.dataset.dark = localStorage.dark || prefersDarkMode.matches;\n\ntoggle.addEventListener(''click'', () => {\nlocalStorage.dark = !(html.dataset.dark == ''true'');\nhtml.dataset.dark = localStorage.dark;\n});\n\ntoggle.style.opacity = 0;\nlet timer;\nwindow.addEventListener(''scroll'', function () {\n  clearTimeout(timer);\n  toggle.style.opacity = 1;\n  timer = setTimeout(() => {\n    toggle.style.opacity = 0;\n  }, 3000);\n});给网站首页的文章标题下添加评论预览Keyle''s Blog在这里记录一些偶尔冒出来转眼就会忘的灵感。 首页 归档 说说 笔记 订阅 开往 虫洞 关于给网站首页的文章标题下添加评论预览2024-10-13 | 分享 |  652 字 |  3 分钟 |   条评论起因是我想在博客的主页就看到水友们的评论，这样方便我一一回复，而不是每次都点进去。有时候回复多了，会忘记是在哪个页面出现的评论。正巧我看到 姜先森 的博客，是如下的样式。这不刚好能借鉴一下，随后对本博客进行了一个小范围的改造。\n去除了网页右侧的最近8条评论，添加了首页的文章前五条评论预览我这边风格是比较朴素的，所以去掉了前面的icon。\ntwikoo API 调用注意事项我发现了twikoo的getRecentComments API ，给它限定数量的话他会累积所有post url的评论总和前x条评论。很显然这不符合需要，正常我们需要的都是每条post的前几条评论，随后对这个API进行每个URL分别调用。\n老规矩放下代码,感兴趣的可以直接参考下面的代码进行调整：\n12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182838485868788899091929394!function () {  const elements = document.querySelectorAll(''.twikoo-comment-count'');  const postUrls = [];  elements.forEach(element => {    const url = element.getAttribute(''url'');    if (url) {      postUrls.push(url);    }  });  twikoo.getCommentsCount({    envId: ''https://twikoo.vrast.cn'',    urls: postUrls,    includeReply: false  }).then(function (res) {    elements.forEach((element, index) => {      const elementUrl = element.getAttribute(''url'');      const matchingRes = res.find(item => item.url === elementUrl);      if (matchingRes) {        element.textContent = `${matchingRes.count} 条评论`;      }    });  }).catch(function (err) {    console.error(err);  });  //需求2 预览部分评论  const commlistElements = document.querySelectorAll(''.commlist'');  const postUrls2 = [];  commlistElements.forEach(element => {    const url = element.getAttribute(''url'');    if (url) {      postUrls2.push(url);    }  });    postUrls2.forEach(postUrl => {      twikoo.getRecentComments({        envId: ''https://twikoo.vrast.cn'',        urls: [postUrl],        pageSize: 5,        includeReply: false      }).then(function (res) {        commlistElements.forEach(commlistElement => {          if (commlistElement.getAttribute(''url'') === postUrl) {            let commentCount = 0;            res.forEach(item => {              if (commentCount <= 5) {                const li = document.createElement(''li'');                // const divAvatar = document.createElement(''div'');                // divAvatar.classList.add(''avatar'', ''letter-fallback'');                // divAvatar.setAttribute(''data-fallback'', item.nick[0]);                // divAvatar.style.backgroundColor = `rgb(${Math.floor(Math.random() * 256)}, ${Math.floor(Math.random() * 256)}, ${Math.floor(Math.random() * 256)})`;                // divAvatar.style.transform = ''rotate(0deg)'';                // divAvatar.style.transition = ''transform 0.5s ease-in-out'';                const a = document.createElement(''a'');                a.href = item.url + ''#'' + item.id;                a.title = item.comment;                // 使用 DOMParser 解析评论内容                const parser = new DOMParser();                const commentFragment = parser.parseFromString(item.comment, ''text/html'').body;                // 将评论内容添加到昵称后面                a.textContent = item.nick + '': '' + commentFragment.textContent;                const spanContent = document.createElement(''span'');                spanContent.classList.add(''comment-content'');                spanContent.appendChild(a);                const spanRight = document.createElement(''span'');                spanRight.classList.add(''right'');                spanRight.textContent = item.relativeTime;//new Date(item.created).toLocaleDateString();                // li.appendChild(divAvatar);                li.appendChild(spanRight);                li.appendChild(spanContent);                commlistElement.appendChild(li);                commentCount++;              }            });          }        });      }).catch(function (err) {        console.error(err);      });    });}()  \n本文标题：给网站首页的文章标题下添加评论预览文章作者：Keyle发布时间：2024-10-13最后更新：2024-10-13原始链接：https://vrast.cn/posts/64318/版权声明：©Keyle''s Blog. 本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可网站米家体验报告twikoo.init({\n  envId: ''https://twikoo.vrast.cn'',\n  el: ''#tcomment'',\n  region: '''',\n  path: '''',\n  onCommentLoaded: function () {\n    const commentCountElement = document.querySelector(''.tk-comments-count'');\n    const targetElement = document.querySelector(''.waline-comment-count'');\n    if (commentCountElement) {\n      const countSpan = commentCountElement.querySelector(''span:first-child'');\n      const commentCount = parseInt(countSpan.textContent);\n      targetElement.textContent = commentCount;\n    } else {\n      console.log(''未找到评论数量元素'');\n    }\n  }\n})window.addEventListener(''load'', function(){\nconst targetDiv = document.querySelector(''.pure-u-1-4.hidden_mid_and_down'');\nif (targetDiv) {\n  targetDiv.parentNode.removeChild(targetDiv);\n}\n\n// 修改 id 为 layout 的 div 的样式\nconst layoutDiv = document.getElementById(''layout'');\nif (layoutDiv) {\n  layoutDiv.style.flexFlow = ''row wrap'';\n  layoutDiv.style.alignContent = ''center'';\n  layoutDiv.style.flexDirection = ''row-reverse'';\n  layoutDiv.style.justifyContent = ''center'';\n  layoutDiv.style.alignItems = ''center'';\n}\n\n// 设置 id 为 header 的元素高度为 60px\nconst header = document.getElementById(''header'');\nif (header) {\n  header.style.height = ''auto'';\n}\n\n// 设置 id 为 nav-menu 的元素样式\nconst navMenu = document.getElementById(''nav-menu'');\nif (navMenu) {\n  navMenu.style.margin = ''10px 0 -1px'';\n  navMenu.style.padding = ''0'';\n  navMenu.style.position = ''unset'';\n  navMenu.style.right = ''0'';\n  navMenu.style.bottom = ''0'';\n  navMenu.style.display = ''flex'';\n  navMenu.style.flexDirection = ''row'';\n  navMenu.style.flexWrap = ''wrap'';\n  navMenu.style.alignContent = ''center'';\n  navMenu.style.alignItems = ''center'';\n  navMenu.style.justifyContent = ''center'';\n}\n\n// 删除带有 site-name 类的 div\nconst siteNameDiv = document.querySelector(''.site-name'');\nif (siteNameDiv) {\n  siteNameDiv.parentNode.removeChild(siteNameDiv);\n}\n});  沪ICP备20024028号-1 本站由 @Keyle  创建，采用 Maupassant 作为主题，您可以在 GitHub 找到本站源码 © Keyle''s Blog .  本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可 时光匆匆而过，本站已经创立距今已有0 天var s1 = ''2016-11-14'';\ns1 = new Date(s1.replace(/-/g, \"/\"));\ns2 = new Date();\nvar days = s2.getTime() - s1.getTime();\nvar number_of_days = parseInt(days / (1000 * 60 * 60 * 24));\ndocument.getElementById(''days'').innerHTML = number_of_days;var search_path = ''search.xml'';\nif (search_path.length == 0) {\n  search_path = ''search.xml'';\n}\nvar path = ''/'' + search_path;\nsearchFunc(path, ''local-search-input'', ''local-search-result'');\n\n        \n            [bg-lazy] {\n                background-image: none !important;\n                background-color: #eee !important;\n            }\n        \n        \n            window.imageLazyLoadSetting = {\n                isSPA: false,\n                preloadRatio: 1,\n                pro