INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1845669236857507840, 'c2774606c16343dc88e4657ed2426c32', '米家体验报告 | Keyle''s Blog', 1845669125859446784, 2, '2024-10-14 11:34:23.283087', '2024-10-14 11:40:05.028695', '341.75', 2, '{"Url":"https://vrast.cn/posts/49270/","Title":"米家体验报告 | Keyle''s Blog","Content":"🌓var prefersDarkMode = window.matchMedia(''(prefers-color-scheme: dark)'');\nvar toggle = document.querySelector(''.darkmode-toggle'');\nvar html = document.querySelector(''html'');\ntoggle.id = ''darkmodeBtn'';\n\nhtml.dataset.dark = localStorage.dark || prefersDarkMode.matches;\n\ntoggle.addEventListener(''click'', () => {\nlocalStorage.dark = !(html.dataset.dark == ''true'');\nhtml.dataset.dark = localStorage.dark;\n});\n\ntoggle.style.opacity = 0;\nlet timer;\nwindow.addEventListener(''scroll'', function () {\n  clearTimeout(timer);\n  toggle.style.opacity = 1;\n  timer = setTimeout(() => {\n    toggle.style.opacity = 0;\n  }, 3000);\n});米家体验报告Keyle''s Blog在这里记录一些偶尔冒出来转眼就会忘的灵感。 首页 归档 说说 笔记 订阅 开往 虫洞 关于米家体验报告2024-10-10 | 生活 |  912 字 |  3 分钟 |   条评论这个主题想写很久了，今天晚上抽空写下。如果你是打算入坑的或者已经使用部分米家设备的，本篇文章可能多少对你有一些小小的帮助。\n联动才是米家的正确打开方式如果有了智能开关，可以将家里的旧灯光线路都接入，通过小爱音响 可以控制这个灯光开关的打开与否。当然这样做少不了，“小爱同学，帮我打开灯光” ，注意小爱同学是需要联网的，他的网路有时候并不是那么的好，网络不好的情况会造成小爱音响的反应卡顿，当然如果你购买的是小爱Play，这个坑货音响，那它自带耳背系统。发音不标准，或者你没有叫他的时候，他会进行延迟，或者错误的应答。\n\n如果使用其他型号的音响与较好的网络条件，固然可以加快小爱同学的指令响应，但是还是要开口下达指令。这个过程持续几次倒是还好，如果每次都要叫一句，那可太尬了，完成一来一回的指令下达，早就可以用手开灯了。\n这一流程当然可以优化，只是需要用到一些传感器。\n传感器是基础的触发单元基于上面的使用场景，使用一个人体传感器就可以做到，人来灯光打开。为什么我不说 “人走后灯光熄灭 ”，实际这是一个很难检测的情况，你大概不能一直保持在被传感器辐射的范围内。当然也有个方案，开灯后自动延迟x分钟让灯光关闭。\n再举个简单安防的案例：我在马桶边，厨下，洗手台水管下，都放置了浸水传感器，如果出现漏水的情况，可以通过家庭的音响与手机通知，提示我去处理这类紧急情况。\n通过家庭中枢驱动家庭智能的自动化前面说了几个案例，这都是一些触发式的响应，并非真正意义上的自动化。在我看来智能家居，需要有个数据处理单元，这个单元是要代替人思考，也就是执行一些行为。这个行为的执行是依据是什么呢？触发器得到的数据与其他信息（事件，时间，其他设备状态）进行一个针对当前行为的判定，是否最终要执行这个行为，或者将这个执行结果分散到不同的设备上去。\n这里需要用到小米中枢，或者homeassistant。由于我们本篇是讲小米产品，那就用小米中枢来举例。在小米中枢你可以看到所有的设备，并且可以查询每个设备的当前状态 或者 监听每个设备的状态变更。\n下面再举一个简单的例子，这里我用到一个智能按钮，每次点击按钮会向外抛出一个点击事件。通过监听这个事件的触发，就可以安排家里的其他智能硬件干不同的事情，如让监控打开，让家里的灯，空调等关闭。\n结束语智能家居融入生活的转变一部分人是无法接受的，咱们这批人先玩起来，哦，对了，如果使用home assistant可以将ai接入智能家居，然后实现一个现实版贾维斯，这也不错。\n本文标题：米家体验报告文章作者：Keyle发布时间：2024-10-10最后更新：2024-10-10原始链接：https://vrast.cn/posts/49270/版权声明：©Keyle''s Blog. 本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可分享给网站首页的文章标题下添加评论预览出去旅游总容易生病是为什么twikoo.init({\n  envId: ''https://twikoo.vrast.cn'',\n  el: ''#tcomment'',\n  region: '''',\n  path: '''',\n  onCommentLoaded: function () {\n    const commentCountElement = document.querySelector(''.tk-comments-count'');\n    const targetElement = document.querySelector(''.waline-comment-count'');\n    if (commentCountElement) {\n      const countSpan = commentCountElement.querySelector(''span:first-child'');\n      const commentCount = parseInt(countSpan.textContent);\n      targetElement.textContent = commentCount;\n    } else {\n      console.log(''未找到评论数量元素'');\n    }\n  }\n})window.addEventListener(''load'', function(){\nconst targetDiv = document.querySelector(''.pure-u-1-4.hidden_mid_and_down'');\nif (targetDiv) {\n  targetDiv.parentNode.removeChild(targetDiv);\n}\n\n// 修改 id 为 layout 的 div 的样式\nconst layoutDiv = document.getElementById(''layout'');\nif (layoutDiv) {\n  layoutDiv.style.flexFlow = ''row wrap'';\n  layoutDiv.style.alignContent = ''center'';\n  layoutDiv.style.flexDirection = ''row-reverse'';\n  layoutDiv.style.justifyContent = ''center'';\n  layoutDiv.style.alignItems = ''center'';\n}\n\n// 设置 id 为 header 的元素高度为 60px\nconst header = document.getElementById(''header'');\nif (header) {\n  header.style.height = ''auto'';\n}\n\n// 设置 id 为 nav-menu 的元素样式\nconst navMenu = document.getElementById(''nav-menu'');\nif (navMenu) {\n  navMenu.style.margin = ''10px 0 -1px'';\n  navMenu.style.padding = ''0'';\n  navMenu.style.position = ''unset'';\n  navMenu.style.right = ''0'';\n  navMenu.style.bottom = ''0'';\n  navMenu.style.display = ''flex'';\n  navMenu.style.flexDirection = ''row'';\n  navMenu.style.flexWrap = ''wrap'';\n  navMenu.style.alignContent = ''center'';\n  navMenu.style.alignItems = ''center'';\n  navMenu.style.justifyContent = ''center'';\n}\n\n// 删除带有 site-name 类的 div\nconst siteNameDiv = document.querySelector(''.site-name'');\nif (siteNameDiv) {\n  siteNameDiv.parentNode.removeChild(siteNameDiv);\n}\n});  沪ICP备20024028号-1 本站由 @Keyle  创建，采用 Maupassant 作为主题，您可以在 GitHub 找到本站源码 © Keyle''s Blog .  本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可 时光匆匆而过，本站已经创立距今已有0 天var s1 = ''2016-11-14'';\ns1 = new Date(s1.replace(/-/g, \"/\"));\ns2 = new Date();\nvar days = s2.getTime() - s1.getTime();\nvar number_of_days = parseInt(days / (1000 * 60 * 60 * 24));\ndocument.getElementById(''days'').innerHTML = number_of_days;var search_path = ''search.xml'';\nif (search_path.length == 0) {\n  search_path = ''search.xml'';\n}\nvar path = ''/'' + search_path;\nsearchFunc(path, ''local-search-input'', ''local-search-result'');\n\n        \n            [bg-lazy] {\n                background-image: none !important;\n                background-color: #eee !important;\n            }\n        \n        \n            window.imageLazyLoadSetting = {\n                isSPA: false,\n                preloadRatio: 1,\n                processImages: null,\n            };\n        window.addEventListener(\"load\",function(){var t=/\\.(gif|jpg|jpeg|tiff|png)$/i,r=/^data:image\\/[a-z]+;base64,/;Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")).forEach(function(a){var e=a.parentNode;\"A\"===e.tagName&&(e.href.match(t)||e.href.match(r))&&(e.href=a.dataset.original)})});(r=>{r.imageLazyLoadSetting.processImages=t;var a=r.imageLazyLoadSetting.isSPA,o=r.imageLazyLoadSetting.preloadRatio||1,d=i();function i(){var t=Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")),e=Array.prototype.slice.call(documen