INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788062678124728320, 'b0e7d99977504e76bb509bdb4d318000', '科技爱好者周刊（第 283 期）：[年终感想] 没有目的地，向前走 - 阮一峰的网络日志', 1787689108462768128, 2, '2024-05-08 12:25:52.050842', '2024-05-08 12:30:46.254608', '294.2', 2, '{"Url":"https://www.ruanyifeng.com/blog/2023/12/weekly-issue-283.html","Title":"科技爱好者周刊（第 283 期）：[年终感想] 没有目的地，向前走 - 阮一峰的网络日志","Content":"\n\nif (/mobile/i.test(navigator.userAgent) || /android/i.test(navigator.userAgent)) document.body.classList.add(''mobile'');\n\n/*\nwindow.addEventListener(''load'', function(event) {\n  setTimeout(function () {\n    hab(''#sup-post-2'');\n    hab(''#cre-inner'');\n  }, 1000);\n});\n*/\n\n    \n        \n\n            \n    \n        \n\n\n            阮一峰的网络日志  » 首页 » 档案\n\n\n\n\n\n  \n  \n  \n  \n  \n\n\n\n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n            \n                \n\n\n                    \n                        \n\n\n                            \n                                \n\n\n\n\n上一篇：科技爱好者周刊（第 2\n下一篇：科技爱好者周刊（第 2\n\n\n\n\n    \n                                    \n                                        分类：\n                                        \n                                            周刊\n                                        \n                                    \n    \n\n\n                                            \n\n\n⇐ \n ⇒\n\n\n\n\n\n\n                          \n\n                                    科技爱好者周刊（第 283 期）：[年终感想] 没有目的地，向前走\n\n\n\n\n                                        \n\n                                            作者： 阮一峰\n                                    日期： 2023年12月22日\n\n\n\n\n\n\n\n\n\n\n\n\n\n                                \n                                \n\n                                    \n                                        这里记录每周值得分享的科技内容，周五发布。\n\n                                    \n\n\n                                    \n                                        本杂志开源，欢迎投稿。另有《谁在招人》服务，发布程序员招聘信息。合作请邮件联系（[email protected]）。\n\n封面图\n\n\n\n河北承德的山谷音乐厅，是一个混凝土和岩石建造的洞穴空间。观众脚下是舞台，头上是天窗，可以同时听到音乐和大自然的声音。（via）\n\n[年终感想] 没有目的地，向前走\n\n又是年底，一年过去了。\n\n大家往往会回顾，这一年实现了哪些目标，下一年要设定哪些目标。\n\n\n\n今天，我想分享 BaseCamp 公司创始人 Jason Fried 的一篇短文，题目就叫《我从来没有目标》。\n\n\n\n下面就是这篇文章的主要内容。\n\n我不记得自己有什么目标，那种很具体的目标。\n\n有些事情我一直想做，但如果不做，我也能接受。有些事情值得去做，但如果没有做到，我也不觉得很遗憾。\n\n我的目标不是那样。\n\n我做事，我尝试，我建造，我想要取得进步，我想让我做的东西使得自己、使得公司、使得家庭、使得社会变得更好。但我从未设定过目标。这不是我做事的方式。\n\n目标是当你到达时就会消失的东西。一旦你到达了，它就消失了。你总是可以设置另一个，我只是不按这样的步骤行事。\n\n我只是做我正在做的事情，然后就到了现在的地方。今天我继续以同样的方式对待工作和生活。\n\n\n\n他的文章到这里就结束了。我很喜欢作者的这种态度。\n\n你可以不给自己设定目标，因为目标是你做事的副产品。只要你按照自己的信念，不断地努力去做事、去尝试，就可以了，至于能做到哪一步，顺其自然就好了。\n\n有一句成语\"功不唐捐\"，就是这个意思，付出的努力不会白费。\n\n\n\n西方人说：\"Passion never fails\"（激情不会失败），也是同样的意思。\n\n\n\n建造那些你想要建造的东西，努力做事，认真生活，人生可以没有目标。\n\n新的一年，我想我也是这样，没有目的地，就是向前走。\n\n[活动] 掘金年度技术演讲\n\n每到年末，都会有很多年度演讲，盘点过去一年。\n\n今年，掘金社区做了一个尝试，推出了 \"年度技术演讲\"，专门盘点2023年的技术大事。\n\n\n\n活动时间是明年1月20日（星期六），上午是主论坛的技术嘉宾演讲，下午是分论坛的专业领域讨论会，涉及大前端、云、AI 等热点领域。\n\n这一年很不容易，终于过完了，主办方搭了一个场子，让大家聚在一起分享技术趋势，结交朋友。\n\n活动地点是深圳的万丽酒店，点击这个链接，或扫描上方二维码，了解活动详情并免费报名。因为这次的场地是五星级酒店，座位有限，采用实名制，会有一个审核环节。\n\n2023年的冷知识\n\n一个美国设计师每年底发一个帖子，总结他在这一年发现的有趣的东西。\n\n下面是他的2023年的总结，其中有一些真的很有趣。\n\n1、\n\n美国国防部是世界最大的老虎机运营商之一。\n\n\n\n以提高\"军人的士气、福利和娱乐\"的名义，美国国防部在海外的美军基地运行着3,000多台老虎机，每年从中赚取1亿美元的收入。\n\n2、\n\n美国现在还有工厂，生产搓衣板。\n\n\n\n疫情期间，搓衣板的销量增长了57%，不过其中40%是作为打击乐器出售的。\n\n3、\n\n为了让腿显得更长，中国厂商发明了\"假肚脐\"贴纸。它贴在实际肚脐上方几厘米处，然后把真肚脐遮住，创造出双腿更长的错觉。\n\n\n\n电商网站上，4元可以买到32张。根据商品说明，它们不反光，甚至防水，还不易脱落。\n\n4、\n\n一道闪电含有大约0.25千瓦时的能量，换算成电费，只有1角多的人民币。\n\n\n\n闪电的能量虽然不是非常大，但是持续时间只有几微秒，电压高达数百万伏，所以才会如此危险。\n\n5、\n\n一家以色列公司推出了手机 App \"远程娃娃机\"，让你在手机上远程操作他们仓库里面的实体娃娃机。\n\n\n\n如果抓到了，他们就把娃娃寄给你。\n\nGoogle Gemini\n\n12月4日，谷歌公开了 AI 模型 Gemini，跟 GPT-4 相抗衡，外部开发者可以自由使用。\n\n1、Gemini Pro 免费使用站点（@lchh5 投稿）\n\n\n\n2、GeminiProChat\n\n\n\n这是网友写的一个极简 UI，调用 Gemini 的 API。你可以试用作者部署的 Demo，也可以本地运行。（@babaohuang 投稿）\n\n3、Google Gemini 的图像能力测试（英文）\n\n一个外国程序员分别对 Gemini 和 GPT-4V 进行了四项测试（图片问答、文字识别、文档识别、物体检测），然后写了这篇文章。\n\n\n\n大家可以看看测试结果，到底孰强孰弱。我们还可以学习他的测试方法，用于评估其他模型。\n\n文章\n\n1、Have I Been Pwned 的创始人（英文）\n\n\n\n\"Have I Been Pwned\"（上图）是一个著名的密码泄漏检查网站，输入邮件地址，它会显示你的密码是否泄漏。本文介绍该网站创始人的故事（下图）。\n\n\n\n2、Linux 如何安装字体（英文）\n\n\n\n本文总结了 Linux 安装字体的各种方法。\n\n3、浏览器的67个调试技巧（英文）\n\n\n\n浏览器的开发者工具怎么调试 JS 脚本，本文介绍67个高级技巧。\n\n4、ESLint 新规则：禁止常量运算式（英文）\n\n\n\n本文介绍 ESLint 的一条新规则no-constant-binary-expression，如果一个 JavaScript 运算式的运算结果为常量，就报错。\n\n5、构建 Web 应用的四种方法（英文）\n\n\n\n本文总结了目前架设网站的四种方法：静态网站、云函数、服务器、容器。\n\n工具\n\n1、snowmachine\n\n\n\n一个 Python 脚本，可以在终端窗口显示下雪和圣诞树。\n\n2、Photo to Anime\n\n\n\n这个网站可以将上传的图片动漫化，也可以通过文本生成动漫图片。（@dongan-beta 投稿）\n\n3、CBox\n\n\n\nChrome 浏览器插件，通过快捷键唤起一个弹窗，执行各种操作（搜索、浏览历史、跳转标签）。（@jokimina 投稿）\n\n4、DartBook\n\n\n\n作者重新实现的 GitBook，加快了 Markdown 的解析速度，并新增了一些功能。（@lindeer 投稿）\n\n5、pastebin-worker\n\n\n\n一个基于 Cloudflare Worker 实现的文字/代码分享网站，类似于 Pastebin。（@xiadd 投稿）\n\n6、EasyTranslator\n\n一个命令行的文件翻译工具，可以翻译.txt、.pdf、.docx、.md、.mobi、.epub 文件，需要 OpenAI key。（@artwalker 投稿）\n\n7、V2EX Polish\n\n\n\n一款浏览器插件，用来增强 V2ex 论坛的功能。（@Codennnn 投稿）\n\niPhone 应用\n\n1、嗯背单词\n\n\n\n2、成语接龙游戏\n\n\n\n小朋友跟 AI 模型玩成语接龙游戏，参见介绍文章。（@zamia 投稿）\n\n资源\n\n1、周刊的 Chat 服务\n\n\n\n网友将周刊迄今的所有内容进行了向量化索引，提交给 ChatGPT，然后就可以跟周刊问答了。（@ahaapple 投稿）\n\n2、News Minimalist\n\n\n\nChatGPT 选出的每日热点新闻。（@Y024 投稿）\n\n3、SearchEmoji\n\n\n\nEmoji 搜索引擎，支持30种语言，代码开源。（@dongnaebi 投稿）\n\n4、中文版黑客新闻\n\n\n\n作者用 Go 语言实现的黑客新闻的克隆版。（@oodzchen 投稿）\n\n5、Solo 独立开发者社区\n\n\n\n针对独立开发者的交流、合作、分享的平台。（@Baiang 投稿）\n\n新年创意礼物\n\n新年的时候，网上都有很多礼物推荐。下面是一家美国网站的推荐，有几样东西挺有创意的。\n\n1、浇花吸管。\n\n\n\n金属管里装有棉条，将水缸里的水吸到花盆里面。\n\n2、以色列 OTOTO 设计工作室的创意厨具。\n\n沥水篮\n\n\n\n汤勺\n\n\n\n搁架\n\n\n\n玻璃杯\n\n\n\n榨汁器\n\n\n\n文摘\n\n1、海水含氧量\n\n全球变暖对地球生物产生巨大威胁，其中一个较少被注意、但影响巨大的威胁就是海水含氧量。\n\n\n\n海水里面溶解了氧气，海洋生物依赖这些氧气。\n\n根据观测，海水的氧气含量正在不断下降，海洋生物越来越难生存。\n\n这有四个原因。\n\n（1）全球变暖，海水升温。根据物理学，温度上升会让溶解的气体变少。\n\n（2）海水流动变小。深层海水的含氧量，取决于表层海水的混入，但是地表的融冰增加，使得注入海洋的地表水密度变小，不利于向下混合。\n\n（3）洋流减少。南极和北极正在快速升温，与赤道的温差变小，抑制洋流和地表的风。这进一步减少了海水流动。\n\n（4）浮游生物增加。海水升温导致细菌和藻类大量繁殖，它们会吞噬海水里面的氧气，使得其他生物窒息。\n\n以上原因导致海水含氧量不断减少。\n\n\n\n它的后果十分严重，海洋鱼类种类随之减少，而且鱼类也会变得更小、发育不良。大量鱼类迁移到含氧量更高的水域，导致气温最高的热带海洋地区将没有鱼。\n\n言论\n\n1、\n\n学生不再是学生，新手变成专家，大家开始组建家庭，所有对你的时间的要求都变得非常苛刻。\n\n-- Tim Carmody，他在学生时代创办了一个网站，坚持了20年，他评论这件事到后来是多么困难。 \n\n2、\n\n如果一个行业向不擅长其工作的人支付高薪，这是一个信号，表明该行业存在泡沫。\n\n-- Bloomberg.com\n\n3、\n\n我从软件工程中学到了几个教训：\n\n（1）如果不了解系统的工作原理，就无法在系统之上构建东西。\n\n（2）尖端方法是灾难的根源。\n\n（3）那些宣传得很美好的事物都是炒作，你只能得到承诺的一小部分效果。\n\n-- Andrew Helwer\n\n4、\n\n慢就是顺利，顺利就是快。\n\n-- 《远程工作的经验教训》\n\n5、\n\n全世界各种语言的\"茶\"，只有两种读音，一种是 chai，另一种是 tea。它们都来源于中文，第一种是北方普通话读音，第二种是福建沿海的闽南话读音。\n\n显然，采用第一种读音的国家，茶叶源自中国的陆路传播。采用第二种读音的国家，茶叶源自中国的海路传播。\n\n-- 《历史地图》\n\n往年回顾\n\n中国的阳光地带（2022 #236）\n\n低纬度，高海拔，气候优势（2021 #186）\n\n利特伍德奇迹定律（2020 #136）\n\n千万不要当完美主义者（2019 #86）\n\n（完）\n\n                                    \n\n                                \n    \n                                \n\n文档信息\n\n版权声明：自由转载-非商用-非衍生-保持署名（创意共享3.0许可证）\n发表日期： 2023年12月22日\n\n\n                                \n\n                            \n\n  \n    .wwads-content .wwads-text {font-size:1.4em;} .wwads-cn img{ border : none;}\n  \n  \n\n\n\n相关文章\n\n\n2024.03.15: 科技爱好者周刊（第 293 期）：一周是一年的2%\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n2024.03.08: 科技爱好者周刊（第 292 期）：所有代码都是技术债\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n2024.03.01: 科技爱好者周刊（第 291 期）：AI 没有护城河\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n2024.02.23: 科技爱好者周刊（第 290 期）：苹果头盔的最大问题\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n\n\n\n\n                    \n\n                    \n\n\n    \n    \n        \n    留言（58条）\n\n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    d\n\n 说：\n                \n\n            \n        \n        \n            抓娃娃app我记得我四五年前就玩过\n        \n\n\n\n                   2023年12月22日 08:54\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zhang\n\n 说：\n                \n\n            \n        \n        \n            这周有点水了\n        \n\n\n\n                   2023年12月22日 09:19\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    qiba\n\n 说：\n                \n\n            \n        \n        \n            成语app配图为什么是英文的？\n        \n\n\n\n                   2023年12月22日 09:21\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kop1989\n\n 说：\n                \n\n            \n        \n        \n            以色列远程抓娃娃……\n\n中国的远程抓娃娃机运营方都已经死过一波了……\n甚至还有远程推币机。\n        \n\n\n\n                   2023年12月22日 09:26\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    码农真经\n\n 说：\n                \n\n            \n        \n        \n            那个玻璃杯确实挺有趣的，而且可以用贴纸实现。\n        \n\n\n\n                   2023年12月22日 09:31\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Mars\n\n 说：\n                \n\n            \n        \n        \n            \n引用d的发言：\n\n抓娃娃app我记得我四五年前就玩过\n\n\n\n17-18年那会儿我在前东家就是做这个的，做了一年多，然后公司没了...\n        \n\n\n\n                   2023年12月22日 09:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zhaoyss\n\n 说：\n         