INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707696336896, '4026f60857f44937872676bb05bcfde1', '辣椒炒肉', 1787695651350515712, 2, '2024-05-08 13:09:35.766587', '2024-05-08 13:09:42.666656', '6.9', 2, '{"Url":"https://gudong.site/2024/02/09/chaorou.html","Title":"辣椒炒肉","Content":"前段时间的某天下午，儿子突然问我：爸爸，你小时候的梦想是什么？当时我很惊讶他提出这个问题，然后我很认真的回答了他的问题，这一下便让我想到了小时候关于梦想的故事。还记得是小学5年级的时候，那时流行一个话题：你的理想是什么，这个话题也经常..."}', '2024-05-08 12:29:43.18922', 'admin', '2024-05-08 13:09:42.666661', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788059966612049920, 'dc7ae4f6bf834b04a3c2c322a9879f8a', '那些无用的人----《人类简史》读后感 - 阮一峰的网络日志', 1787689108462768128, 2, '2024-05-08 12:30:46.794187', '2024-05-08 13:09:18.958829', '2312.16', 2, '{"Url":"https://www.ruanyifeng.com/blog/2016/08/useless-people.html","Title":"那些无用的人----《人类简史》读后感 - 阮一峰的网络日志","Content":"\n\nif (/mobile/i.test(navigator.userAgent) || /android/i.test(navigator.userAgent)) document.body.classList.add(''mobile'');\n\n/*\nwindow.addEventListener(''load'', function(event) {\n  setTimeout(function () {\n    hab(''#sup-post-2'');\n    hab(''#cre-inner'');\n  }, 1000);\n});\n*/\n\n    \n        \n\n            \n    \n        \n\n\n            阮一峰的网络日志  » 首页 » 档案\n\n\n\n\n\n  \n  \n  \n  \n  \n\n\n\n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n            \n                \n\n\n                    \n                        \n\n\n                            \n                                \n\n\n\n\n上一篇：布尔代数入门     \n下一篇：HTTP 协议入门  \n\n\n\n\n    \n                                    \n                                        分类：\n                                        \n                                            观点与感想\n                                        \n                                    \n    \n\n\n                                            \n\n\n⇐ \n ⇒\n\n\n\n\n\n\n                          \n\n                                    那些无用的人----《人类简史》读后感\n\n\n\n\n                                        \n\n                                            作者： 阮一峰\n                                    日期： 2016年8月16日\n\n\n\n\n\n\n\n\n\n\n\n\n\n                                \n                                \n\n                                    \n                                        （说明：本文原载2016年第32期《财新周刊》。文后还会介绍一个新网站\"海棠学院\"。）\n\n                                    \n\n\n                                    \n                                        1.\n\n最近，我读完了《人类简史》（中信出版社，2014）。\n\n\n\n它是以色列学者尤瓦尔·赫拉利写的畅销书，主要讲人类这个物种（即智人）的历史。全书最大特点就是，作者完全用自己的想法解释历史，有大量的独特观点。它不是学术著作，而是表达个人的历史观。\n\n\n\n最惊人的一个观点，大概是他对人类的前途相当悲观，认为人类可能即将灭绝。\n\n2.\n\n全书最后一章的标题，叫做《智人末日》。\n\n作者感叹道，人类社会存在了七万年，真正的大发展只是最近两三百年。但是，再过一千年，人类是否还会存在，已经很可疑了。 \n\n\n\n\n  \"今天，人类正在让许多物种灭绝，甚至可能包括自己。如果今天发生核灾而让世界末日降临，人类将毁灭，而老鼠和蟑螂很可能继续生存下去。或许6500万年后，会有一群高智商的老鼠心怀感激地回顾人类造成的这场灾难。\"\n\n我们还有多久时间？没有人真正知道。如果智人的历史确实即将谢幕，我们这些最后一代的智人，或许该花点时间回答最后一个问题：我们究竟想要变成什么？\"\n\n\n3.\n\n尤瓦尔·赫拉利认为，人类可能灭绝的根本原因，在于技术的高速发展。\n\n技术带来了现代化生活，也导致了前所未有的危机。别的不说，眼下的危机就是，短期内就会有大量失业出现，许多人将变得毫无用处。\n\n\n\n\n  \"技术造成的人力精简，将在今后5年内，导致全球发达国家失去710万个工作岗位，但在科技、专业服务及媒体领域，将创造210万个工作岗位。两相抵销之下，未来五年内，将会净损失500万个工作岗位，其中以行政工作与白领阶级为主。\"\n\n---- 摘自世界经济论坛《未来的工作》，2016 \n\n\n上一次的工业革命，体力劳动被替代了，比如，水车替代了拉磨，汽车替代了马车。这一次的信息技术革命，智力劳动将被替代，计算机替代我们做计算和判断。\n\n体力岗位没了，人类可以从事智力岗位。可是，智力岗位也没了，人类去干什么呢？\n\n4.\n\n今年5月，美国达拉斯发生袭警案，一名狙击手放冷枪，打死了5个警察。最后，他被包围在一片建筑群里面，但不知道他的确切位置。\n\n\n\n警方就派出一个遥控机器人，在建筑群里巡查，一发现目标，就扔出一颗炸弹，一下子就把罪犯炸死了。整个行动高效、快速，警方没有任何流血。更重要的是，这是历史上第一次，机器人警察杀死人类。\n\n\n\n可以想象，随着犯罪行为的增加，以及罪犯装备的升级，机器人警察将会得到推广，取代人类警察打击犯罪。人类士兵也会被取代，以后的战争就是机器人战争。\n\n《人类简史》作者的公开说：\n\n\n  \"未来可能不再需要司机。我们已经有了无人驾驶的汽车。他们不喝酒，不疲惫，比人类驾驶还要安全。当所有的汽车都变成了无人驾驶，我们就可以把所有的车辆联网，形成一个车联网。这样的话，交警可能也不需要了，因为所有的车都可以通过这张网络获取道路信息。\"\n\n\n无人驾驶不仅会让司机和交警失业，而且长远来看，会消灭整个运输物流行业的工作岗位。比如，既然车辆可以自动到达目的地，那么送货的快递小哥也不需要了。\n\n5.\n\n人的价值体现在他/她的工作成果。如果有些人根本找不到工作，他们的价值体现在哪里呢？\n\n过去，工业革命吸收了农业释放的数十亿人力，将人类的劳动形态从田野和作坊，变成了工厂和办公室；现在，工厂和办公室开始释放人力，又有什么行业可以吸收他们呢？\n\n将来越来越多的人会发现，他们根本不可能找到工作。智力和体力两方面，机器都比人类能干。你要么比机器更能干，要么比机器更便宜，否则你怎么跟机器竞争工作岗位呢？\n\n6.\n\n有人说，技术会创造新工作，只要不断学习新的技能，就不用担心自己会被淘汰。这对一部人也许可以，但对大部分人这样要求是不现实的。\n\n\n  \"（世界经济论坛统计，目前的小学生长大后，65%会从事现在还不存在的工作。）孩子们在中学或者大学学到的大多数东西，等到40、50岁的时候可能都会变得无足轻重。如果他们还希望继续保住工作，那就得不断地改造自己，而且频率得越来越快才行。\"\n\n\n不是每个人都善于学习，更不是每个人都具有学习的意愿。大多数人只希望生活舒适，不愿意动脑筋，去搞懂那些抽象的公式。而且，要求40、50岁的人跟刚走上社会的年轻人一样拼搏，也不现实。如果终生学习是唯一的就业出路，那对于多数人来说，就是没有出路。\n\n7.\n\n尤瓦尔·赫拉利说，人工智能取代了那些简单技能的工作岗位以后，人类当中会出现一个庞大的、无用的无产阶级。\n\n\n  \"未来，人类可能会分化为两个主要的等级：一个全新的更先进的精英阶级，很聪明，很富有，有更好的基因和更长的寿命；还有一个全新的一无用处的无产阶级，他们将越来越穷地等待死亡，可能变成没有工作、没有目标、整日靠吸毒度日、戴着VR头盔消磨时光的乌合之众。\"\n\n\n人类社会的政治和经济结构，都会因此被颠覆。\n\n当代国家建立在人对国家有用的基础上的，大部分人的角色是工人和士兵。如果这些角色被机器取代，那么底层的人们对国家来说，也就不再重要了。国家很可能会忽视他们的需求，只是出于社会稳定的目的，提供基本的生活资料。而人们也比以往更依赖政府，因为如果政府停止救济，他们就无法养活自己。\n\n\n\n尤瓦尔·赫拉利将这种情景，列为21世纪最悲惨的威胁之一。\n\n\n  \"随着人工智能变得越来越聪明，会有更多的人被挤出就业市场。没人知道大学该学什么，因为没人知道20岁的时候学的东西到了40岁还有没有用。等你知道的时候，已经有数十亿人变得一点用都没有了。这不是偶然，而是必然。\"\n\n\n（全文完）\n\n\n\n\n\n下面是推广时间。\n\n最近，\"海棠学院\"上线了。它是一个在线学习平台，如果你希望进入互联网行业、系统学习前端技术，那么我推荐你去看一下。\n\n\n\n海棠学院目前提供600课时的前端视频课程，由浅入深、系统讲解各种知识点，每堂课都有课后练习题，保证不同水平的学员都能学会。主讲老师来自百度，有七年开发经验，主导过多个流量过亿的项目。\n\n\n\n如果你每天投入两个小时，一周五天，那么大概四个月时间，就可以从零开始，学完所有课程，掌握前端开发技术。\n\n为了保证学习效果，海棠学院采取多种措施。\n\n\n重视实战。讲课内容和课后作业，紧贴实际业务，并且还有直播课，引导大家现场完成练习。\n重视答疑。如果你遇到疑问，可以随时向线上助教求助，也可以把问题提交到QQ群和微信群。\n强调纪律。为了保证学员不会半途而废，按时完成进度，每堂课都会线上考勤，并且强制交作业，还会有期中考试。\n\n\n\n\n任何疑问或咨询，可以加创始人微信，直接提问。\n\n当然，最重要的还是课程质量，欢迎点击这里，现在就开始试听。​​\n\n（完）\n\n                                    \n\n                                \n    \n                                \n\n文档信息\n\n版权声明：自由转载-非商用-非衍生-保持署名（创意共享3.0许可证）\n发表日期： 2016年8月16日\n\n\n                                \n\n                            \n\n  \n    .wwads-content .wwads-text {font-size:1.4em;} .wwads-cn img{ border : none;}\n  \n  \n\n\n\n相关文章\n\n\n2022.07.27: 能源的极限\n\n                           \n                              一、\n\n美国能源署统计，1650年到2009年的美国能源消耗，年增长率为2.9%。\n\n                           \n\n\n\n \n2021.05.19: 中国经济的数字逻辑\n\n                           \n                              重庆市前市长黄奇帆退休以后，受聘担任复旦大学特聘教授，定期给师生做讲座，介绍他对中国经济的看法。\n\n                           \n\n\n\n \n2020.05.27: 软件吃软件，编程工作会越来越多吗？\n\n                           \n                              1、\n\n最近，国外有一篇文章，标题很有趣，叫做《软件吃掉软件》。\n\n                           \n\n\n\n \n2019.01.31: 一段音频\n\n                           \n                              去年10月，出版社打算录制《未来世界的幸存者》有声版，让我为这个节目录一段话。\n\n                           \n\n\n\n \n\n\n\n\n                    \n\n                    \n\n\n    \n    \n        \n    留言（99条）\n\n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    张\n\n 说：\n                \n\n            \n        \n        \n            好悲伤 \n        \n\n\n\n                   2016年8月16日 09:06\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    温家大宝\n\n 说：\n                \n\n            \n        \n        \n            阮兄，推荐你看无量寿经（特别是净空法师的讲义），你所有的疑问都能找到答案\n        \n\n\n\n                   2016年8月16日 09:09\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kakushang\n\n 说：\n                \n\n            \n        \n        \n            没有人是自成一体、与世隔绝的孤岛，\n每一个人都是广袤大陆的一部份。\n如果海浪冲掉了一块岩石，\n欧洲就减少。\n如同一个海岬失掉一角，\n如同你的朋友或者你自己的领地失掉一块。\n每个人的死亡都是我的哀伤，\n因为我是人类的一员。\n所以，不要问丧钟为谁而鸣，\n它就为你而鸣\n        \n\n\n\n                   2016年8月16日 09:20\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    刘辉\n\n 说：\n                \n\n            \n        \n        \n            人类要赶紧走出地球，地球太小了\n        \n\n\n\n                   2016年8月16日 09:31\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    church\n\n 说：\n                \n\n            \n        \n        \n            广告打的混然天成.. 不过我还是看完了\n        \n\n\n\n                   2016年8月16日 09:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    timothy\n\n 说：\n                \n\n            \n        \n        \n            关于人类，生命的意义等这些问题不是技术、经济、政治等这些学问可以解释的。还是看看《道德经》，《心经》，《无量寿经》呀这些东西。毕竟玄奘跋涉万里从天竺弄来也不容易:-)。\n        \n\n\n\n                   2016年8月16日 09:50\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    andyron\n\n 说：\n                \n\n            \n        \n        \n            最近也刚看完《人类的简史》！\n        \n\n\n\n                   2016年8月16日 10:04\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    ricoo\n\n 说：\n                \n\n            \n        \n        \n            这广告让我有点猝不及防啊\n        \n\n\n\n                   2016年8月16日 10:13\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    ricoo\n\n 说：\n                \n\n            \n        \n        \n            关于失业，其实我想说书的的观点是基于现在我们的社会结构来看的，但是以后如果技术真的发展到能替代人许多工作，那我们的社会结构是否还是这样是存疑的。好比封建时代，人们食不果腹的时候，社会最低保障金对当时的人来说是不可想象的，生产力和社会结构决定了不会出现。但是当社会发展了，社会最低保障金自然而然就出现了。那么到了以后了呢？假如社会生产力已经非常发达，能够支持大部分人不工作也可以生活了，那不是就不需要工作了吗？或许现在我们觉得不工作不可思议，但是这也是因为我们现在所处的社会环境让我们觉得不可思议，社会真正发展到那个地步了，想法自然也不同了，就像对封建社会的人们来说，政府会付出让人能维系最低生活水平的保障金不是也不可思议吗？\n        \n\n\n\n                   2016年8月16日 10:22\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    JIMMY\n\n 说：\n                \n\n            \n        \n        \n            问题是机器人是为人服务的，人都没了，机器人还有何意义？\n        \n\n\n\n                   2016年8月16日 10:23\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    钟钟\n\n 说：\n                \n\n            \n        \n        \n            当未来没发生，新变革来临时，人们总是恐慌的，而事实证明人类越过越好。\n        \n\n\n\n                   2016年8月16日 10:34\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    bigpigeon\n\n 说：\n                \n\n            \n        \n        \n            前半部分看的我好惆怅，最后发现竟然只是个广告，靠被骗了\n        \n\n\n\n                   2016年8月16日 10:52\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    CowryLee\n\n 说：\n                \n\n            \n        \n        \n            不工作难道不是奋斗的目标吗\n        \n\n\n\n                   2016年8月16日 11:43\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Check \n\n 说：\n                \n\n            \n        \n        \n            \n引用温家大宝的发言：\n\n阮兄，推荐你看无量寿经（特别是净空法师的讲义），你所有的疑问都能找到答案\n\n\n\n认真的思考而不是经由各种二手信息理解\n        \n\n\n\n                   2016年8月16日 12:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    allplay\n\n 说：\n                \n\n            \n        \n        \n            《一课经济学》第7章：诅咒机器\n\n在所有的经济错觉中，“机器必然导致失业”这种错误最为阴魂不散。这种错觉曾经被无数人驳倒过，但总能死灰复燃，并且和以往一样张狂。每当出现长时期失业潮的时候，机器总是被指责为造成失业的罪魁祸首。这一谬论仍然是许多工会组织开展实际运动的理论基础。而公众则普遍容忍这些做法，要么认为工会做得对，要么是稀里糊涂，搞不清工会错在哪里。\n所有那些机器导致人们失业的想法，若讲一点点逻辑上的一致性，必然都会得出荒谬的结论：不但我们今天的每一项技术进步都会带来失业，就连原始人尝试摆脱苦力劳动的时候，就已经开始造成自己的失业了。\n……\n根据柏林统计局估计，1887年在全世界投入使用的蒸汽机的动力总和，大约相当于2亿匹马的力量，相当于约10亿人的劳动力；至少是全球劳动人口的总和的三倍……\n我们可以想象，最后得出的这些数据应该会让韦尔斯陷入沉思，想不通为什么到1889年这个世界上竟然还有人有工作可做。\n……\n充分就业（full employment）——非常充分的就业，起早摸黑、全年无休、累死累活的就业状态——是工业发展最落后的国家的特色。\n        \n\n\n\n                   2016年8月16日 13:10\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Go4Tam2\n\n 说：\n                \n\n            \n        \n        \n            警方就派出一个遥控机器人，在建筑群里巡查，一发现目标，就扔出一颗炸弹，一下子就把罪犯炸死了。整个行动高效、快速，警方没有任何流血。更重要的是，这是历史上第一次，机器人警察杀死人类。\n\n// 然而，制造和维护这个遥控机器人却需要一个以上的人。\n        \n\n\n\n                   2016年8月16日 15:46\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    edision\n\n 说：\n                \n\n            \n        \n        \n            也许以后都不用工作了，人类更多的应该去追求艺术或美好事物的创造，不过也许更多的是空虚，自杀率应该会很高（活腻歪了）。人嘛，总能适应不是，近100年，中国人经历了多少苦难，也不见有什么。\n\n至于以后真的不用从事高强度无聊的工作，生存问题不再是问题了，那么人类不是还有更高的追求嘛，娱乐行业估计未来火爆啊，哈哈。写小说的，拍电影的，做内容的越来越有前途。\n\n机器人终究是机器人，即使未来黑科技出现，搞出智能生命，说难听点，那也是另一物种了，就像我们不能理解鱼的想法不是。\n\nso,人脱离了物质追求后，丰富精神世界的事还有很多可以做哈。失业啥的，不要辣么悲观。\n        \n\n\n\n                   2016年8月17日 11:04\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    wang2\n\n 说：\n                \n\n            \n        \n        \n            最后还是要依靠暴力解决问题\n        \n\n\n\n                   2016年8月17日 12:25\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    龙吻伤\n\n 说：\n                \n\n            \n        \n        \n            机器人是机器和人类的合体，未来一片和谐。\n        \n\n\n\n                   2016年8月17日 13:09\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    TheStars\n\n 说：\n                \n\n            \n        \n        \n            大部份人将从重复的工作中脱离出来，从而从事一些属于人类创造的工作，比如诗歌，比如情感……\n        \n\n\n\n                   2016年8月17日 13:23\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    饺子\n\n 说：\n                \n\n            \n        \n        \n            阮兄，请教个问题，想了解网站方面web服务方面的知识，有没有比较好的入门书籍推荐？希望不吝赐教一二\n        \n\n\n\n                   2016年8月17日 15:25\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    11111\n\n 说：\n                \n\n            \n        \n        \n            \n引用ricoo的发言：\n\n这广告让我有点猝不及防啊\n\n\n\n文章标题后面的推广看不见？\n        \n\n\n\n                   2016年8月17日 15:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Howld\n\n 说：\n                \n\n            \n        \n        \n            \n引用allplay的发言：\n\n《一课经济学》第7章：诅咒机器\n\n在所有的经济错觉中，“机器必然导致失业”这种错误最为阴魂不散。这种错觉曾经被无数人驳倒过，但总能死灰复燃，并且和以往一样张狂。每当出现长时期失业潮的时候，机器总是被指责为造成失业的罪魁祸首。这一谬论仍然是许多工会组织开展实际运动的理论基础。而公众则普遍容忍这些做法，要么认为工会做得对，要么是稀里糊涂，搞不清工会错在哪里。\n所有那些机器导致人们失业的想法，若讲一点点逻辑上的一致性，必然都会得出荒谬的结论：不但我们今天的每一项技术进步都会带来失业，就连原始人尝试摆脱苦力劳动的时候，就已经开始造成自己的失业了。\n……\n根据柏林统计局估计，1887年在全世界投入使用的蒸汽机的动力总和，大约相当于2亿匹马的力量，相当于约10亿人的劳动力；至少是全球劳动人口的总和的三倍……\n我们可以想象，最后得出的这些数据应该会让韦尔斯陷入沉思，想不通为什么到1889年这个世界上竟然还有人有工作可做。\n……\n充分就业（full employment）——非常充分的就业，起早摸黑、全年无休、累死累活的就业状态——是工业发展最落后的国家的特色。\n\n\n\n学习了，充分就业不应该是社会的追求。\n\n        \n\n\n\n                   2016年8月17日 17:46\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    峰粉\n\n 说：\n                \n\n            \n        \n        \n            我很惊讶，竟然有看道德经的人在这里看阮老师的博客\n\n佛学朋友，你们放心的吧，阮老师就是文中不断学习的人\n\n阮老师就是那些，“一个全新的更先进的精英阶级，很聪明，很富有，有更好的基因和更长的寿命”\n\n佛学朋友，难道学习那些几百年前，农业的社会的宗教创作，就可以找到未来的工作，就可以不饿肚子？\n\n我只是来支持下阮老师的\n\n阮老师，你的粉丝质量在下降啊\n        \n\n\n\n                   2016年8月18日 08:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    峰粉\n\n 说：\n                \n\n            \n        \n        \n            书中十二章，宗教的法则\n\n“我们今天常认为宗教造成的是歧视、争端、分裂。但在金钱和帝国之外，宗教正是第三种让人类统一的力量。正因为所有的社会秩序和阶级都只是想象的产品，所以他们也十分脆弱，而且社会规模越大，反而就更脆弱。而在历史上，宗教的重要性就在于让这些脆弱的架构有了超人类的合法性。有了宗教之后，就能说法律并不只是人类自己的设计和想象，而是来自一种绝对的神圣最高权柄。这样一来，至少某些基本的法则便不容动摇，从而确保社会稳定。”\n\n“在公元前100年，亚非大陆开始出现全新的宗教和信仰类型。这些新兴宗教信仰包括...佛教、中国的道教和儒教...，共同点特点就是崇拜的并非神。这些信仰也认为有种超人类秩序控制着这个世界，但他们所崇拜的这个秩序是自然法则，而不是什么神圣的意志。”\n\n“佛教并不否认有神存在，认为他们有强大的神通，能够带来降雨和胜利，然而神对于‘由欲得苦’这条法则并无能为力。如果能够无欲无求，任何神都无法让人感到痛苦。相对而言，如果让有了欲望，任何神也无法拯救他脱离痛苦”\n        \n\n\n\n                   2016年8月18日 09:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    郁程\n\n 说：\n                \n\n            \n        \n        \n            这本书值得一读吗？\n感觉并不是很有长期收获的书\n        \n\n\n\n                   2016年8月18日 10:07\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    雨停\n\n 说：\n                \n\n            \n        \n        \n            \n引用Go4Tam2的发言：\n\n警方就派出一个遥控机器人，在建筑群里巡查，一发现目标，就扔出一颗炸弹，一下子就把罪犯炸死了。整个行动高效、快速，警方没有任何流血。更重要的是，这是历史上第一次，机器人警察杀死人类。\n\n// 然而，制造和维护这个遥控机器人却需要一个以上的人。\n\n\n\n?: 想象一下微软和windows，这几个人可制造更多的警察、警犬、警车\n\n        \n\n\n\n                   2016年8月18日 12:24\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    卢达\n\n 说：\n                \n\n            \n        \n        \n            RSS 阅读器 feedly.com 中看不到贵站图片\n        \n\n\n\n                   2016年8月18日 15:54\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    波波\n\n 说：\n                \n\n            \n        \n        \n            听君这么一些话，我突然觉得我朝很多所作所为都有大大大局观啊。。。\n        \n\n\n\n                   2016年8月18日 16:20\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Peng Sir\n\n 说：\n                \n\n            \n        \n        \n            看完所有评论，我又安心了\n        \n\n\n\n                   2016年8月18日 18:27\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    silence\n\n 说：\n                \n\n            \n        \n        \n            \n引用ricoo的发言：\n\n关于失业，其实我想说书的的观点是基于现在我们的社会结构来看的，但是以后如果技术真的发展到能替代人许多工作，那我们的社会结构是否还是这样是存疑的。好比封建时代，人们食不果腹的时候，社会最低保障金对当时的人来说是不可想象的，生产力和社会结构决定了不会出现。但是当社会发展了，社会最低保障金自然而然就出现了。那么到了以后了呢？假如社会生产力已经非常发达，能够支持大部分人不工作也可以生活了，那不是就不需要工作了吗？或许现在我们觉得不工作不可思议，但是这也是因为我们现在所处的社会环境让我们觉得不可思议，社会真正发展到那个地步了，想法自然也不同了，就像对封建社会的人们来说，政府会付出让人能维系最低生活水平的保障金不是也不可思议吗？\n\n\n\n这一段不是很好的回答你所说的了嘛：\n\n\n\n当代国家建立在人对国家有用的基础上的，大部分人的角色是工人和士兵。如果这些角色被机器取代，那么底层的人们对国家来说，也就不再重要了。国家很可能会忽视他们的需求，只是出于社会稳定的目的，提供基本的生活资料。而人们也比以往更依赖政府，因为如果政府停止救济，他们就无法养活自己。\n\n\n\n这还不够悲哀吗\n        \n\n\n\n                   2016年8月19日 10:23\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    silence\n\n 说：\n                \n\n            \n        \n        \n            所以人类随着自身科技的发展，出路就是星际空间~~~不再局限于地球的时候，人还是被大量需要的\n        \n\n\n\n                   2016年8月19日 10:30\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    cccc\n\n 说：\n                \n\n            \n        \n        \n            \n引用JIMMY的发言：\n\n问题是机器人是为人服务的，人都没了，机器人还有何意义？\n\n\n\n机器人拥有自我意识，然后进入机器文明时代。\n其实可以想象一下，机器和科技本身就是生命的一种存在形式，我们人类只是把它孕育出来\n\n        \n\n\n\n                   2016年8月19日 11:47\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    cccc\n\n 说：\n                \n\n            \n        \n        \n            @allplay：\n\n《一课经济学》里面也有提到在科技升级技术转型时期有相当一部分人无法转型，不管是年龄学识还是其他原因无法适应新的工作岗位，这些人《一课经济学》给的建议也是政府需要多关心照顾，也没有其他好的办法。\n\n更新的现实是，现在的这一轮科技革命可能会创造出自我完善和自我维护、自我升级，完全不需要人工干预的新型科技物种出来，淘汰的岗位可能会比新增加的岗位要多得多\n\n        \n\n\n\n                   2016年8月19日 11:53\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    xue changliang\n\n 说：\n                \n\n            \n        \n        \n            信基督教吧,不要觉得犹太人说的有道理,弗洛伊德,马克思说的都不是真理.\n        \n\n\n\n                   2016年8月19日 12:08\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    蓝仁\n\n 说：\n                \n\n            \n        \n        \n            大可不必这么灰心，智力工作的终结不会这么快，社会的发展，除了技术的进步，还有行政的止步不前；况且，多元化的社会中，会有非常多的行业需要大家去完善，不是每个行业都可以很快被人工智能代替的。\n        \n\n\n\n                   2016年8月19日 16:08\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    allplay\n\n 说：\n                \n\n            \n        \n        \n            \n引用cccc的发言：\n@allplay：\n《一课经济学》里面也有提到在科技升级技术转型时期有相当一部分人无法转型，不管是年龄学识还是其他原因无法适应新的工作岗位，这些人《一课经济学》给的建议也是政府需要多关心照顾，也没有其他好的办法。\n更新的现实是，现在的这一轮科技革命可能会创造出自我完善和自我维护、自我升级，完全不需要人工干预的新型科技物种出来，淘汰的岗位可能会比新增加的岗位要多得多\n\n\n你说的这个情况，叫结构性失业，对待结构性失业的办法很多，《一课》不讨论是因为超出了话题范围。\n《一课》只是用简明的例子来说明问题，如果你觉得他没有说明问题，那是你还没有理解这个道理。\n如果担心技术威胁就业的话，那人类根本就不应该发展任何一种超出生物本能的技术，一根棍子，一块石头也别用。这样，每一个人类的劳动岗位肯定是保障无疑的——谁不劳动，立刻挨饿。\n自我生产的新型科技物种，这个东西是无法实证的。拿无法实证的东西来推断人类即将在这一轮科技革命中灭绝，这种内容应该存在于科幻小说或者茶余饭后的空谈中。\n这也是《人类简史》这本书的特点，太多个人观点、断言、没有实证的东西。\n        \n\n\n\n                   2016年8月19日 17:12\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    allplay\n\n 说：\n                \n\n            \n        \n        \n            就从解决失业本身来说，如果不是技术支持生产力的提高，现代失业养老保险也是断然不可能出现的，因为劳动创造的价值不够，支撑不了保险的支付。现代很多人可以工作一个月的薪水支撑一年的基本生活，这就是因为劳动效率提高、创造价值的提高。如果自己从支撑不了，保险也能支持你半年的时间。如果没有这样的生产力，那人类只能回到累死累活担心明天的食物在哪里的状态。\n\n认为机器取代人力，造成的失业。这是一种静止历史的观点，眼光非常局限。\n有了牛、马，许多出力的人失业了，有了蒸汽动力，更多的人失业了，当蒸汽动力超过了人类力量总和，人类全部下岗了么？\n人类的需求总是无止境的，失业论总是以当下的需求来讨论需要多少劳动供给。机器使人失业，那么看看200年前有多少人从事工业？今天有多少人从事工业？\n人类创造了许多当年失业危机中根本没想到的就业岗位出来。静止的需求，是失业论的重大缺陷。\n        \n\n\n\n                   2016年8月19日 17:37\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    程锦\n\n 说：\n                \n\n            \n        \n        \n            要考虑人的需求，建造的房子，生产的商品，消耗的汽车都是为人提供服务，没有庞大的人口就不会有强大的经济需求。当然随着劳动生产率的提高，很多行业在同样生产力水平下会需要更少的劳动力，特别是在产业升级的背景下。同时，这种情况会加重财富分配不均，所以调节收入分配的税收就显得尤为重要。另外，劳动生产率和劳动力需求不是一个简单的反比关系，有很多外生变量影响量者，在不同条件下既会出现劳动生产率的增速大于劳动需求，也会出现劳动需求大于劳动生产率。最后就像你说的，很多以前从未有过的劳动岗位开始出现，这是新的需求，在服务业中占了很大一部分，而服务业的劳动需求量对技术进步的敏感性低。\n        \n\n\n\n                   2016年8月19日 18:08\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    ale\n\n 说：\n                \n\n            \n        \n        \n            \n引用cccc的发言：\n\n\n机器人拥有自我意识，然后进入机器文明时代。\n其实可以想象一下，机器和科技本身就是生命的一种存在形式，我们人类只是把它孕育出来\n\n\n\n\n这个 评论像《自私的基因》结尾那点禅意！说宗教，圣经，耶稣以思维的形式衍生也可作为生命体的一部分！\n        \n\n\n\n                   2016年8月20日 00:09\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    吕权\n\n 说：\n                \n\n            \n        \n        \n            人类最终会自己灭亡吗？\n        \n\n\n\n                   2016年8月20日 08:50\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    philosophia\n\n 说：\n                \n\n            \n        \n        \n            \n引用峰粉的发言：\n\n我很惊讶，竟然有看道德经的人在这里看阮老师的博客\n\n佛学朋友，你们放心的吧，阮老师就是文中不断学习的人\n\n阮老师就是那些，“一个全新的更先进的精英阶级，很聪明，很富有，有更好的基因和更长的寿命”\n\n佛学朋友，难道学习那些几百年前，农业的社会的宗教创作，就可以找到未来的工作，就可以不饿肚子？\n\n我只是来支持下阮老师的\n\n阮老师，你的粉丝质量在下降啊\n\n\n\n为佛学朋友说句话\n自己不懂得东西不要评论,说佛学不好,至少你去看看\n\n        \n\n\n\n                   2016年8月21日 12:42\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    非道弘人\n\n 说：\n                \n\n            \n        \n        \n            @峰粉：\n\n我觉得有你这样的人自称峰粉才说明阮老师的粉丝质量在下降。\n        \n\n\n\n                   2016年8月22日 15:59\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    高少云\n\n 说：\n                \n\n            \n        \n        \n            大叔，你的博客文章底部能加个回到顶部的按钮嘛，左手吃桃，右手操控键盘，回到顶部有点费劲\n        \n\n\n\n                   2016年8月23日 09:25\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    小喜\n\n 说：\n                \n\n            \n        \n        \n            \n引用高少云的发言：\n\n大叔，你的博客文章底部能加个回到顶部的按钮嘛，左手吃桃，右手操控键盘，回到顶部有点费劲\n\n\n\n试试 HOME 键。。。\n        \n\n\n\n                   2016年8月23日 18:16\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    飞龙骑脸\n\n 说：\n                \n\n            \n        \n        \n            印象里记得 译者是王道还。能介绍一下王老先生？\n\n        \n\n\n\n                   2016年8月24日 09:28\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    飞龙骑脸\n\n 说：\n                \n\n            \n        \n        \n            -_-记错了。极简医学史是王道还翻译的。\n人类简史反倒不是他翻译的。\n        \n\n\n\n                   2016年8月24日 09:31\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    树梢的果实\n\n 说：\n                \n\n            \n        \n        \n            1、本来世界上没有这么多人，有一天，壶里的水开了……\n2、这个世界从来就是少数人的\n3、人类的欲望是无穷大的（你不会，有人会的，所以别说“我……”）\n        \n\n\n\n                   2016年8月24日 14:13\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    大J\n\n 说：\n                \n\n            \n        \n        \n            不用这么悲观，等人类有能力开阔宇宙了，多的是工作机会，你信不信\n        \n\n\n\n                   2016年8月24日 18:19\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    \bfengsong97\n\n 说：\n                \n\n            \n        \n        \n            世界经济论坛统计，目前的小学生长大后，65%会从事现在还不存在的工作。\n只怪世界发展太快，不断看清未来，看清自己，就够了\n        \n\n\n\n                   2016年8月27日 11:47\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    inspironx\n\n 说：\n                \n\n            \n        \n        \n            \"智力和体力两方面，机器都比人类能干。你要么比机器更能干，要么比机器更便宜，否则你怎么跟机器竞争工作岗位呢？\"\n\n这个说法很正确啊,比如苹果完全可以在美国建个全自动化的iPhone装配厂,但放到富士康来装配比建个厂便宜多了,因为中国的人工比机器便宜嘛.\n人工智能的应用将会是个颠覆性的革命,它使机器的投资回报率极大提高,人工连便宜的优势都将丧失殆尽.西方的工人最后手里还有张不知道管不管用的选票,中国的民工啥也没有.\n\n        \n\n\n\n                   2016年8月27日 18:16\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    童好浪\n\n 说：\n                \n\n            \n        \n        \n            看完评论我安心了\n        \n\n\n\n                   2016年8月27日 19:56\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    NULL\n\n 说：\n                \n\n            \n        \n        \n            只剩高端的人才也不行啊，谁来做低级的活？\n        \n\n\n\n                   2016年8月28日 13:10\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Paul\n\n 说：\n                \n\n            \n        \n        \n            真到这个时候，哲学必然热门\n        \n\n\n\n                   2016年8月29日 10:10\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    xiaogongjiang\n\n 说：\n                \n\n            \n        \n        \n            人们会更多的从事创造性、研究性的工作，基本的脑力工作被取代，人们从一出生会趋向研究革命性的东西，不然你就没饭吃了。技术突破会更快。虽然短期内人工智能和机器智能的冲击会大到我们社会所无法接受。\n        \n\n\n\n                   2016年9月 5日 19:13\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Philip\n\n 说：\n                \n\n            \n        \n        \n            我觉得太慢了，他们在哪呢？\n        \n\n\n\n                   2016年9月12日 18:00\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    孙远山\n\n 说：\n                \n\n            \n        \n        \n            如果未来存在那么多高科技，那么人类一定会向星辰大海进军的。\n因为科技发展就会导致人类灭绝，这样的观点 格局太小了。\n        \n\n\n\n                   2016年9月14日 17:28\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    李强\n\n 说：\n                \n\n            \n        \n        \n            任何社会问题只需要一场战争就可以重置它\n        \n\n\n\n                   2016年9月18日 19:53\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    makefool\n\n 说：\n                \n\n            \n        \n        \n            所以现在为了夺取争夺地球资源的胜利，我们开始放开生二胎。\n\n夺取大战胜利后，又会缩减生育。必定在大战中，会有弱小的文化被泯灭，不过这样吃相会比一百年前好看很多。\n        \n\n\n\n                   2016年9月26日 15:56\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    wdepeng\n\n 说：\n                \n\n            \n        \n        \n            那么在这个过渡的过程中，教师的职业将会越来越重要，知识变得越来越平民化。。。。就如你投放的广告那样，未来的教育会变成强制性。。。。。\n        \n\n\n\n                   2016年9月29日 19:35\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    上天飞云\n\n 说：\n                \n\n            \n        \n        \n            人有人的价值，现今的社会，还远远没有体现出人类独有的、富于创造性的价值。很多人还被捆绑在无数重复与琐碎当中。如果机器有一天能让人从现在的重复与琐碎的工作中抽离出来，人才能更好地发挥自己作为万物之灵的价值。每个人都是亿万年进化精进的产物，珍惜每个人，没有谁是低级的，也没有谁是高贵的。我相信每个人都有自己独有的别人不可取代的价值，所谓天生我材必有用。\n        \n\n\n\n                   2016年10月 6日 00:38\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Rancho\n\n 说：\n                \n\n            \n        \n        \n            写的好好，我很想去看这本书。\n        \n\n\n\n                   2016年10月 6日 14:36\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    cymurs\n\n 说：\n                \n\n            \n        \n        \n            \n引用Go4Tam2的发言：\n\n警方就派出一个遥控机器人，在建筑群里巡查，一发现目标，就扔出一颗炸弹，一下子就把罪犯炸死了。整个行动高效、快速，警方没有任何流血。更重要的是，这是历史上第一次，机器人警察杀死人类。\n\n// 然而，制造和维护这个遥控机器人却需要一个以上的人。\n\n\n\n当制造和维护的工作，都交给了机器人\n        \n\n\n\n                   2016年10月14日 12:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    cymurs\n\n 说：\n                \n\n            \n        \n        \n            人的思维还是只能局限于当下，未来的事都是无法预料的，就像祖先也想不到人能上天、去外太空，他们更想不到几万里的路程可以朝发夕至，相隔千山万水也能见面聊天。科技的发展虽然会带来短暂的不适感，但是按照人类历史以往的发展规律，总是会进入到一种无法想象的新境界中。\n\n        \n\n\n\n                   2016年10月14日 12:22\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    刘旭\n\n 说：\n                \n\n            \n        \n        \n            在机器不会为了更高的能量的转化率而主动消灭人类的情况下。即使机器具有绝对优势，根据比较优势理论，机器与人类进行分工合作也仍然是一种合理的策略。即便没有比较优势，交易也依然是能够存在的。\n        \n\n\n\n                   2016年10月14日 22:38\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    晚晴幽草轩\n\n 说：\n                \n\n            \n        \n        \n            \n引用高少云的发言：\n\n大叔，你的博客文章底部能加个回到顶部的按钮嘛，左手吃桃，右手操控键盘，回到顶部有点费劲\n\n\n\n那么你一定得用下 Chrome 插件 Vimium，欲回顶部，键盘上 gg 一下即可。\n        \n\n\n\n                   2016年10月21日 15:55\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    晚晴幽草轩\n\n 说：\n                \n\n            \n        \n        \n            个人觉得这并非杞人忧天的观点；\n\n支持这个观点的例子已不胜枚举，就拿取这教育而说吧：\n还在百年之前，读书人寒窗十载，便能博取些功名利禄(如果环境不那么昏暗的话)；\n\n再看二十年前，大学生还拥有吃香之宿命；再看这几年，自5岁(如今小孩儿会更早)而始，寒窗苦读20载，结果呢大片学生连\n就业都是问题（当然，不排除这其中有僧多粥少，求学不专之故），所以也不多说什么；\n\n那么再之后的十年呢？我们的子孙教育成本愈发增加，而机器人成本却日益减少，在如今大多工作岗位上较量的话，试问：如果你是老板你选谁来为你赚取钱财？故而，就逼迫人们要更加努力学习，方能有一战之力，很明显这对大多数人来说，这不显示，一如文中大部分观点所言。\n\n所以，这怎么是杞人忧天的观点呢？镜头推到个人身上：在今天台风袭击深圳的日子，我司员工也都还在工作，而我也是不得不来；即便明日不上班，如果没有学习成果，内心是焦躁的——社会竞争压力大啊。\n\n一如以上诸多留言人and众多阮粉的存在，便是例证，相比于看看剧，睡睡觉，和读技术文章，你更喜欢的是？而你不得不选择的又是什么？无他，求存向上也；此是为何？都是被逼的啊，言多惧(俱)泪！\n        \n\n\n\n                   2016年10月21日 16:14\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    bandit\n\n 说：\n                \n\n            \n        \n        \n            \n引用JIMMY的发言：\n\n问题是机器人是为人服务的，人都没了，机器人还有何意义？\n\n\n\n机器不需要思考这个问题\n        \n\n\n\n                   2016年10月25日 14:11\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zdy\n\n 说：\n                \n\n            \n        \n        \n            \n引用ricoo的发言：\n\n关于失业，其实我想说书的的观点是基于现在我们的社会结构来看的，但是以后如果技术真的发展到能替代人许多工作，那我们的社会结构是否还是这样是存疑的。好比封建时代，人们食不果腹的时候，社会最低保障金对当时的人来说是不可想象的，生产力和社会结构决定了不会出现。但是当社会发展了，社会最低保障金自然而然就出现了。那么到了以后了呢？假如社会生产力已经非常发达，能够支持大部分人不工作也可以生活了，那不是就不需要工作了吗？或许现在我们觉得不工作不可思议，但是这也是因为我们现在所处的社会环境让我们觉得不可思议，社会真正发展到那个地步了，想法自然也不同了，就像对封建社会的人们来说，政府会付出让人能维系最低生活水平的保障金不是也不可思议吗？\n\n\n是的，价值观是会变的。我们不能基于现在的社会形态来猜测200年后社会是什么样子。\n\n        \n\n\n\n                   2016年10月29日 22:07\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Can\n\n 说：\n                \n\n            \n        \n        \n            人类灭绝本来就不是什么坏事，你别以为人类不灭绝你就有下辈子继续当人啊，你下辈子可能是一只被人类屠杀的绵羊。\n        \n\n\n\n                   2016年10月30日 00:50\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Rky\n\n 说：\n                \n\n            \n        \n        \n            事物的发展都是一个缓慢的过程，我非常同意您说的机器在很多方面会取代人类的工作，但这是一个缓慢的过程，在这个状态形成的过程中，每一步都会发展成为一个可以制约的平衡，发展不会突变。\n另一方面，我觉得只要太阳第二天还照射地球，我们就会有资源产出，人，够吃，能活，有思想的人还是会追求幸福的事情。\n        \n\n\n\n                   2016年10月31日 17:55\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    JustinYi922\n\n 说：\n                \n\n            \n        \n        \n            期待上帝的存在\n        \n\n\n\n                   2016年11月 6日 18:58\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    暂时没想到\n\n 说：\n                \n\n            \n        \n        \n            我表示不同意。有一种我们部门老大吹牛逼的感觉，整天讲人类怎样自私，中国人怎样愚蠢，政府怎样腐败，每天以此为乐，实不知自己乃一“妄人”。\n        \n\n\n\n                   2016年11月 9日 21:14\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    blue_morning\n\n 说：\n                \n\n            \n        \n        \n            \n引用高少云的发言：\n\n大叔，你的博客文章底部能加个回到顶部的按钮嘛，左手吃桃，右手操控键盘，回到顶部有点费劲\n\n\n\nCtrl+Home\n        \n\n\n\n                   2016年12月13日 17:34\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    lumia\n\n 说：\n                \n\n            \n        \n        \n            \n引用温家大宝的发言：\n\n阮兄，推荐你看无量寿经（特别是净空法师的讲义），你所有的疑问都能找到答案\n\n\n\n这篇文章所忧虑的是事实，找到了答案又能怎样，大部分人活着的目的就是吃喝玩乐，没钱的话，对于一些大道理，他们一个字也听不进去\n        \n\n\n\n                   2016年12月13日 18:53\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    张泽豪\n\n 说：\n                \n\n            \n        \n        \n            人的价值体现在他/她的工作成果。如果有些人根本找不到工作，他们的价值体现在哪里呢？\n我认为不用担心这个问题，社会观念是不断的改变的，当人人都不再工作时，自然会有新的价值观念来替代\n        \n\n\n\n                   2016年12月26日 23:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Boatlet\n\n 说：\n                \n\n            \n        \n        \n            关于文中提到的机器警察杀死犯人一事，个人觉得并没有什么特别意义。\n这里的机器警察不过是一个工具，跟菜刀，枪支，并没有什么区别。\n真正觉得谁该死的还是人，如果有一天有人是被完全来自机器自己的判断杀死的，那才有意义。\n        \n\n\n\n                   2017年1月15日 20:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Tom\n\n 说：\n                \n\n            \n        \n        \n            \n引用zdy的发言：\n\n\n是的，价值观是会变的。我们不能基于现在的社会形态来猜测200年后社会是什么样子。\n\n\n\n\n其实作者的担心完全建立在目前资本主义制度下，就业第一，无就业无法生存的分配方式下的。\n\n如果10%的人劳动就能让100%的人过上舒适的生活，那么这个问题其实是劳动产品分配制度的问题，就看社会科学发展能不能跟上技术发展的步伐了。其实有几种潜在的解决方式：\n\n1.类似共产主义社会，大部分人当艺术家运动员，公益劳动者，按需领取生活必须品，少部分人从事生产劳动，其实这样制度设计的好的话应该比现在的社会要美好的多。不过必须政治制度和社会结构发生深刻变革。\n\n2.移民外星，最可能的是火星，月球，木卫6等，这也正是spacex之类的公司正在做的事，因为向宇宙扩张几乎是无限的，也是人类多余劳动力最好的出路，这是最积极的方法，不过因为技术难度大，100年内未必见效。\n\n3.最消极的方法就是发动战争，大量消灭人口，就像1984里说的，战争是统治阶级维护统治的必要手段，也是消灭“多余的人”的最原始落后的自然选择。\n        \n\n\n\n                   2017年1月17日 15:46\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    devin\n\n 说：\n                \n\n            \n        \n        \n            以后的主要产业是娱乐\n        \n\n\n\n                   2017年2月 7日 09:56\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    彭湃\n\n 说：\n                \n\n            \n        \n        \n             失业肯定存在,社会讲究效率,机器效率比人高,自然被取代,关键是被取代后他们能做什么,能否继续为社会创造价值,如果你对别人没价值,别人也不会拿自己有价值的东西和你交换了,所以这个问题不是国家的问题丶不是科技技术的问题,而是自己的问题,你自己没价值,还要去交换很多价值,这个不靠谱.\n        \n\n\n\n                   2017年2月21日 16:04\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    jiangjunzhangaa\n\n 说：\n                \n\n            \n        \n        \n            看完每一条评论，不同的观点让人悲观与乐观交加。虽然我偏向于悲观，大部分人的命运是被少部分人决定的。不过我觉得目前的环境下，人类的素质的提升程度还不及科技的发展，这就像一个孩子手持利器，很有可能伤到自身。\n        \n\n\n\n                   2017年4月21日 16:46\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    clark_zhang\n\n 说：\n                \n\n            \n        \n        \n            很赞同李飞飞老师在视频里讲的，“也许我们的担忧有点过早，就想NASA刚在火星发射了卫星，我们就要担心火星的人会不会爆满的问题”，学术界大牛对科技的进展尚且不抱这么乐观的态度，我们何须这么早的杞人忧天，也许真的到了那一天，我们自然就会先去考虑我们人类后续的发展和生存等等问题，而我们也会有不同的社会制度，毕竟对比与工业革命时代我们又进步了不是。\n不过阮神提到的技术的精简的确已经真真切切的在发生了，我这个互联网从业者已经感觉到来自于未来的压力……\n        \n\n\n\n                   2017年5月 6日 22:16\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    clark_zhang\n\n 说：\n                \n\n            \n        \n        \n            漏了李老师的视频：https://youtu.be/nwKByS-uOyM?t=4m9s\n        \n\n\n\n                   2017年5月 6日 22:27\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    蓝90\n\n 说：\n                \n\n            \n        \n        \n            就像哈桑班纳号召回归宗教本身，然后创立穆斯林兄弟会一样，可能到时候人类就要回归人类本源了，\n人类的文化以及艺术并没有随着科技的发展快速的升华，所以我觉得，当科技取代普通劳动力的时候，人类对世界以及自己的认知，便是生存之匙\n        \n\n\n\n                   2017年5月11日 19:32\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    我问问\n\n 说：\n                \n\n            \n        \n        \n            机器代替人类？！人没有用？！\n\n我就给你拉闸断电，我看谁谁干活！\n        \n\n\n\n                   2017年6月19日 09:19\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    思考的蚂蚁\n\n 说：\n                \n\n            \n        \n        \n            \n引用timothy的发言：\n\n关于人类，生命的意义等这些问题不是技术、经济、政治等这些学问可以解释的。还是看看《道德经》，《心经》，《无量寿经》呀这些东西。毕竟玄奘跋涉万里从天竺弄来也不容易:-)。\n\n\n\n玄奘现在只需一个电脑或者手机和宽带或者4G网络，就不用跋涉万里从天竺弄经文了。\n        \n\n\n\n                   2017年8月 3日 12:44\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    空手\n\n 说：\n                \n\n            \n        \n        \n            对阮一峰先生的这一篇读后感的观点我表示不赞同。\n\n您的观点是这一次信息革命的结果会是：大大降低“一些人”对于社会的价值，使得财富往少数具有可以支配新世界中有如“魔法”一般的AI、机器人、基因科技的人的手中聚集。导致大量人类失业。再继而因为人类失业引起的社会不稳定等等。从而导致人类灭绝。\n\n先说我赞同的事实或者子观点：科技会以一种比以前快的多的速度发展，这一点我赞成。同时，现在人类社会面临着很多威胁，包括短暂的因为科技发展导致的失业阵痛，以及环境污染问题等等，这我也赞同。甚至因为环境污染、疾病导致人类灭绝的可能性一直存在。\n\n但是如果说因为科技发展导致个体生产力差过于悬殊，从而导致人类灭绝，我觉得听着还是有些危言耸听了。您是学经济的，我观点可能比较市井，并不如你那么宏观，属于比较浅显的推敲。但是，几次人类的工业革命、信息革命等等解放生产力的同时，不是也催生了很多其他职业吗？最简单的，发明电脑之前有游戏设计师吗，发明空调之前有修空调的吗？发明了黄片、发明了充气娃娃、发明了洗衣机，女人就消失了？假设您（花大力气）掌握了AI、编程机器人的技术，您是筑起高墙让它变得更难用艰深，还是不断发展使其变成想洗衣机、电视一样的“普通人”可以用的“产品”？我觉得恰恰相反，科技生产力的发展必定会使其产品化易用化，没有办法普及普通人用的产品，这个科技将必然是被抛弃的，或者是不成熟的被束之高阁的。AI和机器人也是这样。如果两个自动驾驶的车，一个要你用火星语写一段代码和他对话他才能开到目的地，一个你用自然语言说就可以，你会花钱买哪一个？\n\n就算掌握这些“魔法”的“魔法师”们筑起了高墙，维护着他们的“魔法帝国”，垄断起他们的技术。我觉得基于这一点也不会发生您所说的大规模的社会阶级断层。--掌握这些“魔法”究竟需要什么成本？--如果掌握它们并不会花很多时间，我觉得这个垄断就不存在。如果掌握它们会花很多时间，那么必然你就没有时间做其他事，比如读小说、画画、写音乐、\b学习如何健身／穿的性感诱人，你就有那你赚取的换取别人有的东西的基础，为什么别人就不可能以此为职业讨好你（就是和你做交易呢？）\n\n当然我的观点基于人没有和机器融合发生异化，以及基因科技对人的影响有限这个前提。如果您认为这两点有可能导致人类毁灭我也是不太赞同的。这两种科技非常科幻，我有一个基本的观点，如果（地球）资源不够人类玩了，同时人类又因为这种技术自己闹矛盾了，我觉得最简单的就是会发生殖民火星或者其他星球的事件。并不会灭绝。人不就是被欲望驱使的动物么。\n        \n\n\n\n                   2017年8月 4日 17:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    空手\n\n 说：\n                \n\n            \n        \n        \n            最近看了 美国国家地理的 Years of Living Dangerously 2。我觉得真正的灭绝的威胁来自于人类对于自然的不尊重，无知。全球气候变化（Climate Change）已经影响生态到如此程度了，很多领域人类却还以自己的利益为重。政府的作为有限，经济个体都是以自己的经济利益为重，石油公司打击太阳能，对亚马逊森林的无节制的砍伐。个人就是想支持环保，也不知道你买的产品的生产过程中究竟对环境做了多少不可逆的破坏。真奇怪信息科技如此发达，我连扫一扫我买的东西是不是环境友好的都做不到。（或者排出了多少温室气体，或者有一个客观的指标评价）\n        \n\n\n\n                   2017年8月 4日 17:50\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    陈婷\n\n 说：\n                \n\n            \n        \n        \n            人类的进化论从来都是不能与世间的一切生物相脖的，存在的就是合理的。这种合理性不仅体现在人类的进化过程，还体现在人类社会的发展过程。从祖先猿猴进化成人类，再从人类的贫穷落后发展到温饱水平，到小康生活，再到追求更至上的繁荣与昌盛。任何社会阶段，都会出现两种极端分类――人上人与阶下囚。人类在不断追求正能量的“漩涡”下，才能把现在及未来的颠覆全球的高端经济政治文化革命风暴越刮越大，直至覆盖整个世界，让人类自己“成就”自己！那是我们整个人类共同的与时俱进之“社会根本发展论”。它不仅是这个时代必然的进化论，也是世界的唯物论的根源和力量，与社会主义核心价值紧密相联。每个朝代的兴衰灭亡，记录的也不仅是一段历史，更是人类星球空前绝后的探索之道，水到渠成地把人类经济政治文化的发展演绎到极致。人类一代又一代的繁衍，把世界的发展推向高潮，它并不意味着人类的结束，优胜劣汰可以让人类更兴旺，社会更发达。当几百亿年后，星球内外所有的生物都会消陨，我们的魂灵也像随一切消失而恢复平静！\n        \n\n\n\n                   2017年8月29日 12:17\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    wude\n\n 说：\n                \n\n            \n        \n        \n            如果终生学习是唯一的就业出路，那对于多数人来说，就是没有出路。\n\n希望那天到来\n        \n\n\n\n                   2017年10月12日 17:52\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    灰羊\n\n 说：\n                \n\n            \n        \n        \n            人不一定非要工作，大多数人努力工作就是为了有一天可以不工作。\n\n如果真有那么一天，人类要解决的也仅仅是资源分配问题，社会总产值那么多，怎么分配罢了。\n\n出现一群无所事事的乌合之众那是必然的，这类场景在当今的德国已经上演很久了。\n\n德国的游戏和游戏机专门是卖给穷人的。\n\n我是想说，缘起 性空 诸行无常 诸法无我。\n        \n\n\n\n                   2017年10月31日 16:43\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    董忠华\n\n 说：\n                \n\n            \n        \n        \n            人类社会所面临的第五次革命：哲学革命的提出\n——《董氏整体哲学》的革命性科学性介绍\n（中国天津汽车齿轮厂退休工人）董忠华\n\n人类社会所面临的第五次革命：哲学革命。\n《董氏整体哲学》的革命性科学性介绍。\n关键在于实现对马克思主义的直接的相对独立性的全面发展。\n\n序。从我对《人类简史》的点评说起。\n最近，从网上看到了国人对一部外国学者的可以称之为划时代的巨著：《人类简史：从动物到上帝》的评述。\n1.他讲述了我们人类从十万年前有生命迹象开始到21世纪资本、科技交织的人类发展史。讲述了我们从认知革命、农业革命到科学革命，发展成为了现实这个人类社会的全过程。  \n2.最后，作者对人类（智人。我称之为地球自然人）的最终命运的研究仿佛是悲观的，因为他没有能找到拯救人类的方法。实际上，不仅是这位作者，连同大科学家霍金先生以至世界各国学术界的老师们也都没有能够找到拯救人类的方法。而究其最根本的原因，首先是因为大家都没有能够做好对马克思主义的直接的相对独立性的全面发展。\n3.实际上，后者的这一不足的存在既是正常的又是不正常的。说其是正常的，就是新的思想总是要由某一个人首先研究到（提出来）的。说其是不正常的，就是说这一不足本是不应该存在的，因为这完全是由于我的研究成果长期不能得到正常的发表造成的。\n比如2010年6月10日（和7月2日）《清华大学校刊》对我的文章《新社会发展学——暨社会管理结构学的提出》的封杀、和2012年8月13日（和9月13日）《天津社会科学院出版社》对我的作为向党的十八大献礼的一本小薄书《向世界宣告：中国人在人文科学研究方面已走在世界前面——我的六篇理论创新尖子文章》的封杀就是最好的例证。可以肯定，如果我的研究成果能够得到正常的发表（出版），世界各国学术界的老师们能够看到并从而对他们的研究起到提醒的作用，那么这次哲学革命很可能就应该由他们首先提出来了，现实人类社会的发展就不会变成现实这个越来越不正常发展的样子了，而是会换成一个开始步入（一国共产主义第一阶段的门槛这一）正常发展的样子了。\n\n        \n\n\n\n                   2017年12月21日 16:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    mall\n\n 说：\n                \n\n            \n        \n        \n            人的价值都是自己强加的，例如在某些政府眼里，草民和机器本来就没啥差别。\n        \n\n\n\n                   2018年2月 2日 11:59\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    michael\n\n 说：\n                \n\n            \n        \n        \n            一点点体会。\n\n这本书和这篇解读我买帐了，和我的世界观，人生观吻合。\n\n我相信人类只是诸多进化中的母体中的一种，恐龙也曾经是，更高级的生物，或者存在正在被孕育。参考普罗米修斯和异形。\n\n进化，迭代就是究极过程，没有方向，没有终点，如星体破灭一样。\n\n其实农业革命，工业革命，信息革命看似高效，但是本质都在格杀人类自己的命运。\n\nDo you really think we are not at war? We are. 在有限的资源和无限的能量膨胀过程中，谁不在无时无刻掠夺其他人的资源和生命呢？\n\n嗜杀的本性无法改变，因为我们是动物，社会性无法根本改变我们动物性的根源。我们将要创造的新的生命体，无机体或许，或许会改变这一切。\n\n阶级斗争，和战争的根源来自我们对其他人，对未来的不信任和恐惧。看完这本书，我很恐惧。在线课堂很好的利用了这种阶级被抛弃，生命被抛弃的终极恐惧。我买帐了。我去学习人工智能和深度学习课程了。不想被抛弃。\n        \n\n\n\n                   2018年2月25日 14:49\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zhow\n\n 说：\n                \n\n            \n        \n        \n            就想问，如果哆啦A梦普及了，人类能干什么工作？\n        \n\n\n\n                   2018年6月 4日 11:18\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    tango\n\n 说：\n                \n\n            \n        \n        \n            \n引用温家大宝的发言：\n\n阮兄，推荐你看无量寿经（特别是净空法师的讲义），你所有的疑问都能找到答案\n\n\n\n能说说看您的答案吗\n        \n\n\n\n                   2018年6月14日 16:15\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    berserker\n\n 说：\n                \n\n            \n        \n        \n            \n我想说说我的观点，社会的发展不单单从历史角度去分析问题，在经济学的观点中，越高的生产效率越低的成本意味着更大的经济蛋糕，它确实会使物价变得比想象的更便宜。但失业率提高，短期从普通产业到技术产业的转型又十分困难。从短期看，失业率减少会刺激消费者减少消费，需求减少会降低市场价格，又会进一步使“没有革新技术”的企业承受不住成本亏损而倒闭。失业率上升。但幸存的新企业会用更低廉的价格进入市场，更低的市场价又会刺激消费者的需求，更多的消费，又会刺激企业投资，然而企业扩张所需的人力大不如前，多被人工智能所取缔，也就意味着企业的扩张并不意味着会减少失业率。需求的减少远远超出低成本带来的收益。\n\n   从长期看，随着时间的推移，越来越多的人失业，虽然一小部分人成功转型，随产业转型成为新型劳动者。但大批的失业者仍然进一步加剧的市场需求的萎靡。越多的人选择减少消费，使越多的企业亏损，又诞生新一批的失业者，经济开始缩紧。大多数人需要靠政府救济度日，当然，如果掌握技术和财富的小部分财富拥有者愿意放贷的话，也许会刺激一些创业者，从而产生好的经济连锁效应，但这会导致财富更加两极化，带来寡头垄断等等......不管怎么看，都不怎么能乐观起来\n\n   到时候计划经济说不定就要登场了，马克思会心一笑【滑稽】\n\n   虽然这么说，但我认为现在离这个时期还早，至少现在人工智能的成本要高于人工。技术层面也无法取代大多数传统行业，社会的转型要遍及全球也需要相当时间的。而且下一代的人也会受到偏向社会主流的教育，比上一代人更有适应新环境和新技术的优势。总不会太绝望，总不会饿死吧，我说是“围师必阙”会不会太阴暗呢。\n\n  再说，人类的历史就是战争的历史，被逼到饿的半死又没钱的时候，那就开抢吧。\n        \n\n\n\n                   2018年8月17日 10:42\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    yuhuai\n\n 说：\n                \n\n            \n        \n        \n            我觉得自然气候变化会是最快造成人类灭绝的原因\n        \n\n\n\n                   2020年12月 7日 17:43\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    学无止境\n\n 说：\n                \n\n            \n        \n        \n            \n引用zhow的发言：\n\n就想问，如果哆啦A梦普及了，人类能干什么工作？\n\n\n\n生产哆啦A梦\n        \n\n\n\n                   2022年12月 1日 14:06\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n    \n\n\n    \n    \n    \n        我要发表看法\n        \n\n        \n            \n\n            \n                \n                \n                \n                \n                \n                \n                \n                \n            \n                    您的留言\n                    （HTML标签部分可用）\n                    \n                \n                    \n                        您的大名：\n                           «-必填\n                    \n                    \n                        电子邮件：\n                           «-必填，不公开\n                    \n                    \n                        个人网址：\n                           «-我信任你，不会填写广告链接\n                    \n                    \n                        \n                        记住个人信息？\n                    \n                \n                    \n                    \n                    \n                \n                \n                \n\n正在发表您的评论，请稍候\n\n           \n\n\n\n\n                       «- 点击按钮\n                \n            \n\n\n        \n    \n\n    \n\n\n\n\n\n\n\n                        \n                    \n\n                \n            \n        \n         \n            \n\n  \n\n      \n\n\n     \n\n       \n       \n         Weibo | \n         Twitter |\n         GitHub\n       \n     \n     Email: [email protected]\n     \n  \n  \n\n\n  \n\n\n\nfunction insertLine(e,t){for(var n=0;n<t;n++)e.parentNode.insertBefore(document.createElement(\"p\"),e)}function getImg(){if(!window[\"main-content\"])return!1;for(var e,t=Array.prototype.slice.call(window[\"main-content\"].getElementsByTagName(\"img\")),n=0;n<t.length;n++){if(\"display: none !important;\"===(e=t[n]).getAttribute(\"style\"))return e;if(n===t.length-1)return!1}}function toObjectUrl(e,t){return fetch(e).then(e=>e.blob()).then(e=>{t(URL.createObjectURL(e))})}function toDataURL(e,t){var n=new XMLHttpRequest;n.open(\"get\",e),n.responseType=\"blob\",n.onload=function(){var e=new FileReader;e.onload=function(){t(this.result)},e.readAsDataURL(n.response)},n.send()}setTimeout(function(){var e=getImg();e&&(insertLine(e.parentNode,2),toObjectUrl(e.src,function(t){var n=document.createElement(\"p\"),r=document.createElement(\"img\");r.src=t,n.appendChild(r),e.parentNode.parentNode.insertBefore(n,e.parentNode)}))},3e3);\n                                                                                                                                                                                                                                                                                                                                                                                                                                                     \n\n  (function(i,s,o,g,r,a,m){i[''GoogleAnalyticsObject'']=r;i[r]=i[r]||function(){\n  (i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),\n  m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)\n  })(window,document,''script'',''//www.google-analytics.com/analytics.js'',''ga'');\n\n  ga(''create'', ''UA-46829782-1'', ''ruanyifeng.com'');\n  ga(''send'', ''pageview'');\n\n\n\n\n\nvar supportImg = document.querySelector(''#support-img'');\n\nif (supportImg && _hmt) {\n  _hmt.push([''_trackEvent'', ''banner'', ''load'']);\n  supportImg.addEventListener(''click'', function () {\n    _hmt.push([''_trackEvent'', ''banner'', ''click'']);\n  }, false);\n}\n\nvar homepageImg = document.querySelector(''#homepage_sponsor'');\nif (homepageImg && _hmt) {\n  _hmt.push([''_trackEvent'', ''homepage-banner'', ''load'']);\n  homepageImg.addEventListener(''click'', function () {\n    _hmt.push([''_trackEvent'', ''homepage-banner'', ''click'']);\n  }, false);\n}\n\n\n\n\n        \n    \n(function(){if (!document.body) return;var js = \"window[''__CF$cv$params'']={r:''8806a0011a928898'',t:''MTcxNTE0MTY4OS4zODAwMDA=''};_cpo=document.createElement(''script'');_cpo.nonce='''',_cpo.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'',document.getElementsByTagName(''head'')[0].appendChild(_cpo);\";var _0xh = document.createElement(''iframe'');_0xh.height = 1;_0xh.width = 1;_0xh.style.position = ''absolute'';_0xh.style