INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707721502720, '4026f60857f44937872676bb05bcfde1', '误操作🤦‍♂️', 1787695651350515712, 2, '2024-05-08 13:09:43.340602', '2024-05-08 13:09:46.897512', '3.56', 2, '{"Url":"https://gudong.site/2024/01/24/daily.html","Title":"误操作🤦‍♂️","Content":"昨天不小心误删除了文档项目，把之前用vuepress搭建的本地文档删除了，导致最后花了很多时间去找回，尽管最终还是找回了，但用的方式比较粗暴，如果开始把项目都托管在github，使用版本管理，就不会有这样的问题，或者即使本地误删除，找..."}', '2024-05-08 12:29:43.194751', 'admin', '2024-05-08 13:09:46.897516', 'admin');
