INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707763445760, '4026f60857f44937872676bb05bcfde1', '开发日志之合并笔记', 1787695651350515712, 2, '2024-05-08 13:14:48.913698', '2024-05-08 13:14:54.694436', '5.78', 2, '{"Url":"https://gudong.site/2023/06/11/daily.html","Title":"开发日志之合并笔记","Content":"最近inbox笔记开发了两个比较大的功能​双列回顾模式（堆叠模式被废弃）​笔记合并功能关于inbox笔记双列更紧凑，浏览效率更高，这里的模式选择交互参考了抖音里，推荐页面的模式切换。笔记合并是指多个笔记，可以合并为一篇笔记。之前也看到..."}', '2024-05-08 12:29:43.205819', 'admin', '2024-05-08 13:14:54.694441', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1845673943239888896, 'e052afd715134b49930dbd3bea7b78e2', 'https://vrast.cn/posts/f773f5f3/', 1845673867633364992, 2, '2024-10-14 12:15:14.731883', '2024-10-14 12:16:10.642181', '55.91', 2, '{"Url":"https://vrast.cn/posts/f773f5f3/","Title":"MD5withRSA In C# | Keyle''s Blog","Content":"🌓var prefersDarkMode = window.matchMedia(''(prefers-color-scheme: dark)'');\nvar toggle = document.querySelector(''.darkmode-toggle'');\nvar html = document.querySelector(''html'');\ntoggle.id = ''darkmodeBtn'';\n\nhtml.dataset.dark = localStorage.dark || prefersDarkMode.matches;\n\ntoggle.addEventListener(''click'', () => {\nlocalStorage.dark = !(html.dataset.dark == ''true'');\nhtml.dataset.dark = localStorage.dark;\n});\n\ntoggle.style.opacity = 0;\nlet timer;\nwindow.addEventListener(''scroll'', function () {\n  clearTimeout(timer);\n  toggle.style.opacity = 1;\n  timer = setTimeout(() => {\n    toggle.style.opacity = 0;\n  }, 3000);\n});MD5withRSA In C#Keyle''s Blog在这里记录一些偶尔冒出来转眼就会忘的灵感。 首页 归档 说说 笔记 订阅 开往 虫洞 关于MD5withRSA In C#2017-01-12 | 开发 |  991 字 |  5 分钟 |   条评论\n本章记录关于Java MD5withRSA加密算法的C#实现。由于C#不提供MD5withRSA的内置实现，所以必须依赖其他的第三方库。这里提供一个简单的sample来演绎[bouncycastle]的加密库。\n\n\n\nMD5withRSA是什么？\n先使用MD5加密(不可逆转) 生成密文。\n使用RSA继续加密 上一步的密文。\n\nMD5是什么？Message Digest Algorithm MD5（中文名为消息摘要算法第五版）为计算机安全领域广泛使用的一种散列函数，用以提供消息的完整性保护。该算法的文件号为RFC 1321（R.Rivest,MIT Laboratory for Computer Science and RSA Data Security Inc. April 1992）。 –来自百度百科\nRSA是什么?RSA是目前最有影响力的公钥加密算法，它能够抵抗到目前为止已知的绝大多数密码攻击，已被ISO推荐为公钥数据加密标准。 –来自百度百科\nMD5withRSA 的使用场景如果你在百度上搜索 MD5withRSA 恐怕搜到最多的就是关于建行支付的。对的，这个加密算法常用与支付阶段。主要用途是防篡改。一般来说传递明文 可能被黑客从传输阶段拦截，篡改，此时我们用私钥将MD5加密后的密文再加密与明文一起发送。服务器用公匙将密文解密此时得到md5的密文，然后将明文用md5加密得到密文，匹配这两个密文。如果一致则消息是未被篡改的。\n使用 BouncyCastle.Crypto.dll 演绎签名与验证签名加密支持列表Current feature list:\nGeneration and parsing of PKCS-12 files.X.509: Generators and parsers for V1 and V3 certificates, V2 CRLs and attribute certificates.PBE algorithms supported by PbeUtilities: PBEwithMD2andDES-CBC, PBEwithMD2andRC2-CBC, PBEwithMD5andDES-CBC, PBEwithMD5andRC2-CBC, PBEwithSHA1andDES-CBC, PBEwithSHA1andRC2-CBC, PBEwithSHA-1and128bitRC4, PBEwithSHA-1and40bitRC4, PBEwithSHA-1and3-keyDESEDE-CBC, PBEwithSHA-1and2-keyDESEDE-CBC, PBEwithSHA-1and128bitRC2-CBC, PBEwithSHA-1and40bitRC2-CBC, PBEwithHmacSHA-1, PBEwithHmacSHA-224, PBEwithHmacSHA-256, PBEwithHmacRIPEMD128, PBEwithHmacRIPEMD160, and PBEwithHmacRIPEMD256.Signature algorithms supported by SignerUtilities: MD2withRSA, MD4withRSA, MD5withRSA, RIPEMD128withRSA, RIPEMD160withECDSA, RIPEMD160withRSA, RIPEMD256withRSA, SHA-1withRSA, SHA-224withRSA, SHA-256withRSAandMGF1, SHA-384withRSAandMGF1, SHA-512withRSAandMGF1, SHA-1withDSA, and SHA-1withECDSA.Symmetric key algorithms: AES, Blowfish, Camellia, CAST5, CAST6, ChaCha, DES, DESede, GOST28147, HC-128, HC-256, IDEA, ISAAC, Noekeon, RC2, RC4, RC5-32, RC5-64, RC6, Rijndael, Salsa20, SEED, Serpent, Skipjack, TEA/XTEA, Threefish, Tnepres, Twofish, VMPC and XSalsa20.Symmetric key modes: CBC, CFB, CTS, GOFB, OFB, OpenPGPCFB, and SIC (or CTR).Symmetric key paddings: ISO10126d2, ISO7816d4, PKCS-5/7, TBC, X.923, and Zero Byte.Asymmetric key algorithms: ElGamal, DSA, ECDSA, NaccacheStern and RSA (with blinding).Asymmetric key paddings/encodings: ISO9796d1, OAEP, and PKCS-1.AEAD block cipher modes: CCM, EAX, GCM and OCB.Digests: GOST3411, Keccak, MD2, MD4, MD5, RIPEMD128, RIPEMD160, RIPEMD256, RIPEMD320, SHA-1, SHA-224, SHA-256, SHA-384, SHA-512, SHA3, Tiger, and Whirlpool.XOFs: SHAKE.Signer mechanisms: DSA, ECDSA, ECGOST3410, ECNR, GOST3410, ISO9796d2, PSS, RSA, X9.31-1998.Key Agreement: Diffie-Hellman, EC-DH, EC-MQV, J-PAKE, SRP-6a.Macs: CBCBlockCipher, CFBBlockCipher, CMAC, GMAC, GOST28147, HMac, ISO9797 Alg. 3, Poly1305, SipHash, SkeinMac, VMPCMAC.PBE generators: PKCS-12, and PKCS-5 - schemes 1 and 2.OpenPGP (RFC 4880)Cryptographic Message Syntax (CMS, RFC 3852), including streaming API.Online Certificate Status Protocol (OCSP, RFC 2560).Time Stamp Protocol (TSP, RFC 3161).TLS/DTLS client/server up to version 1.2, with support for the most common ciphersuites and extensions, and many less common ones. Non-blocking API available.Elliptic Curve Cryptography: support for generic F2m and Fp curves, high-performance custom implementations for many standardized curves.Reading/writing of PEM files, including RSA and DSA keys, with a variety of encryptions.PKIX certificate path validation\nSample12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364/// <summary>/// MD5withRSA Signing/// https://www.vrast.cn/// keyle_xiao 2017.1.12/// </summary>public  class MD5withRSASigning{\tpublic Encoding encoding = Encoding.UTF8;\tpublic string SignerSymbol = \"MD5withRSA\";\tpublic MD5withRSASigning() { }\tpublic MD5withRSASigning(Encoding e, string s)\t{\t\tencoding = e;\t\tSignerSymbol = s;\t}\tprivate AsymmetricKeyParameter CreateKEY(bool isPrivate, string key)\t{\t\tbyte[] keyInfoByte = Convert.FromBase64String(key);\t\tif (isPrivate)\t\t\treturn PrivateKeyFactory.CreateKey(keyInfoByte);\t\telse\t\t\treturn PublicKeyFactory.CreateKey(keyInfoByte);\t}\tpublic string Sign(string content, string privatekey)\t{\t\tISigner sig = SignerUtilities.GetSigner(SignerSymbol);\t\tsig.Init(true, CreateKEY(true, privatekey));\t\tvar bytes = encoding.GetBytes(content);\t\tsig.BlockUpdate(bytes, 0, bytes.Length);\t\tbyte[] signature = sig.GenerateSignature();\t\t/* Base 64 encode the sig so its 8-bit clean */\t\tvar signedString = Convert.ToBase64String(signature);\t\treturn signedString;\t}\tpublic bool Verify(string content, string signData, string publickey)\t{\t\tISigner signer = SignerUtilities.GetSigner(SignerSymbol);\t\tsigner.Init(false, CreateKEY(false, publickey));\t\tvar expectedSig = Convert.FromBase64String(signData);\t\t/* Get the bytes to be signed from the string */\t\tvar msgBytes = encoding.GetBytes(content);\t\t/* Calculate the signature and see if it matches */\t\tsigner.BlockUpdate(msgBytes, 0, msgBytes.Length);\t\treturn signer.VerifySignature(expectedSig);\t}}\n\n\n参考文档bouncycastle官网C# 与JAVA 的RSA 加密解密交互，互通，C#使用BouncyCastle来实现私钥加密，公钥解密的方法\n本文标题：MD5withRSA In C#文章作者：Keyle发布时间：2017-01-12最后更新：2024-08-20原始链接：https://vrast.cn/posts/f773f5f3/版权声明：©Keyle''s Blog. 本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可MD5withRSA在MAC平台体验DotnetCore一次加载所有Shadertwikoo.init({\n  envId: ''https://twikoo.vrast.cn'',\n  el: ''#tcomment'',\n  region: '''',\n  path: '''',\n  onCommentLoaded: function () {\n    const commentCountElement = document.querySelector(''.tk-comments-count'');\n    const targetElement = document.querySelector(''.waline-comment-count'');\n    if (commentCountElement) {\n      const countSpan = commentCountElement.querySelector(''span:first-child'');\n      const commentCount = parseInt(countSpan.textContent);\n      targetElement.textContent = commentCount;\n    } else {\n      console.log(''未找到评论数量元素'');\n    }\n  }\n})window.addEventListener(''load'', function(){\nconst targetDiv = document.querySelector(''.pure-u-1-4.hidden_mid_and_down'');\nif (targetDiv) {\n  targetDiv.parentNode.removeChild(targetDiv);\n}\n\n// 修改 id 为 layout 的 div 的样式\nconst layoutDiv = document.getElementById(''layout'');\nif (layoutDiv) {\n  layoutDiv.style.flexFlow = ''row wrap'';\n  layoutDiv.style.alignContent = ''center'';\n  layoutDiv.style.flexDirection = ''row-reverse'';\n  layoutDiv.style.justifyContent = ''center'';\n  layoutDiv.style.alignItems = ''center'';\n}\n\n// 设置 id 为 header 的元素高度为 60px\nconst header = document.getElementById(''header'');\nif (header) {\n  header.style.height = ''auto'';\n}\n\n// 设置 id 为 nav-menu 的元素样式\nconst navMenu = document.getElementById(''nav-menu'');\nif (navMenu) {\n  navMenu.style.margin = ''10px 0 -1px'';\n  navMenu.style.padding = ''0'';\n  navMenu.style.position = ''unset'';\n  navMenu.style.right = ''0'';\n  navMenu.style.bottom = ''0'';\n  navMenu.style.display = ''flex'';\n  navMenu.style.flexDirection = ''row'';\n  navMenu.style.flexWrap = ''wrap'';\n  navMenu.style.alignContent = ''center'';\n  navMenu.style.alignItems = ''center'';\n  navMenu.style.justifyContent = ''center'';\n}\n\n// 删除带有 site-name 类的 div\nconst siteNameDiv = document.querySelector(''.site-name'');\nif (siteNameDiv) {\n  siteNameDiv.parentNode.removeChild(siteNameDiv);\n}\n});  沪ICP备20024028号-1 本站由 @Keyle  创建，采用 Maupassant 作为主题，您可以在 GitHub 找到本站源码 © Keyle''s Blog .  本站采用署名-非商业性使用-相同方式共享 4.0 国际进行许可 时光匆匆而过，本站已经创立距今已有0 天var s1 = ''2016-11-14'';\ns1 = new Date(s1.replace(/-/g, \"/\"));\ns2 = new Date();\nvar days = s2.getTime() - s1.getTime();\nvar number_of_days = parseInt(days / (1000 * 60 * 60 * 24));\ndocument.getElementById(''days'').innerHTML = number_of_days;var search_path = ''search.xml'';\nif (search_path.length == 0) {\n  search_path = ''search.xml'';\n}\nvar path = ''/'' + search_path;\nsearchFunc(path, ''local-search-input'', ''local-search-result'');\n\n        \n            [bg-lazy] {\n                background-image: none !important;\n                background-color: #eee !important;\n            }\n        \n        \n            window.imageLazyLoadSetting = {\n                isSPA: false,\n                preloadRatio: 1,\n                processImages: null,\n            };\n        window.addEventListener(\"load\",function(){var t=/\\.(gif|jpg|jpeg|tiff|png)$/i,r=/^data:image\\/[a-z]+;base64,/;Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")).forEach(function(a){var e=a.parentNode;\"A\"===e.tagName&&(e.href.match(t)||e.href.match(r))&&(e.href=a.dataset.original)})});(r=>{r.imageLazyLoadSetting.processImages=t;var a=r.imageLazyLoadSetting.isSPA,o=r.imageLazyLoadSetting.preloadRatio||1,d=i();function i(){var t=Array.prototype.slice.call(document.querySelectorAll(\"img[data-original]\")),e=Array.prototype.slice.call(document.querySelectorAll(\"[bg-lazy]\"));return t.concat(e)}function t(t){(a||t)&&(d=i());for(var e,n=0;n<d.length;n++)0<=(e=(e=d[n]).getBoundingClientRect()).bottom&&0<=e.left&&e.top<=(r.innerHeight*o||document.documentElement.clientHeight*o)&&(()=>{var t,e,a,o,i=d[n];e=function(){d=d.filter(function(t){return i!==t}),r.imageLazyLoadSetting.onImageLoaded&&r.imageLazyLoadSetting.onImageLoaded(i)},(t=i).dataset.loaded||(t.hasAttribute(\"bg-lazy\")?(t.removeAttribute(\"bg-lazy\"),e&&e()):(a=new Image,o=t.getAttribute(\"data-original\"),a.onload=function(){t.src=o,t.removeAttribute(\"data-original\"),t.setAttribute(\"data-loaded\",!0),e&&e()},a.onerror=function(){t.removeAttribute(\"data-original\"),t.setAttribute(\"data-loaded\",!1),t.src=o},t.src!==o&&(a.src=o)))})()}function e(){clearTimeout(t.tId),t.tId=setTimeout(t,500)}t(),document.addEventListener(\"scroll\",e),r.addEventListener(\"resize\",e),r.addEventListener(\"orientationchange\",e)})(this);"}', '2024-10-14 11:52:13.6893', 'admin', '2024-10-14 12:16:10.642189', 'admin');
