INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707755057152, '4026f60857f44937872676bb05bcfde1', '笔记自由复制来了', 1787695651350515712, 2, '2024-05-08 13:09:43.345543', '2024-05-08 13:14:48.680606', '305.34', 2, '{"Url":"https://gudong.site/2023/06/17/daily.html","Title":"笔记自由复制来了","Content":"关于inbox笔记完成了长按笔记自由复制功能，类似微信中的消息，长按可以对消息文本进行自由选择，然后进行复制。之前，inbox中只能对笔记整体进行复制，不能手动选择指定的部分文本，用户需要去编辑页面才可以进行自由复制。这个功能的实现花..."}', '2024-05-08 12:29:43.20283', 'admin', '2024-05-08 13:14:48.68061', 'admin');
