INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707776028672, '4026f60857f44937872676bb05bcfde1', '高考后的感觉', 1787695651350515712, 2, '2024-05-08 13:14:49.093629', '2024-05-08 13:15:00.62639', '11.53', 2, '{"Url":"https://gudong.site/2023/06/10/gaokao.html","Title":"高考后的感觉","Content":"最近高考，每天上班时，都会路过附近的考场，看到一边等待一边还在看书的学生，仿佛看到了以前的自己，思绪一下就能回到2008、2009的夏天。我参加了两次高考，复读了一次，不知道现在还有没有复读的说法。第一次高考是2008年。那年是在县里..."}', '2024-05-08 12:29:43.208356', 'admin', '2024-05-08 13:15:00.626393', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1795636458988638208, 'aeaa1ea74bed4a64b89dfa05c1fb463c', '从抖音看见世界的参差 - 元培 · 元视角', 1778611670021705728, 2, '2024-05-29 10:01:46.060348', '2024-05-29 10:03:13.008693', '86.95', 2, '{"Url":"https://blog.yuanpei.me/posts/seeing-the-world-through-tiktok/","Title":"从抖音看见世界的参差 - 元培 · 元视角","Content":"(function(){const e=\"StackColorScheme\";localStorage.getItem(e)||localStorage.setItem(e,\"auto\")})()(function(){const t=\"StackColorScheme\",e=localStorage.getItem(t),n=window.matchMedia(\"(prefers-color-scheme: dark)\").matches===!0;e==\"dark\"||e===\"auto\"&&n?document.documentElement.dataset.scheme=\"dark\":document.documentElement.dataset.scheme=\"light\"})()\n返回\n\n😸元培 · 元视角起风了，唯有努力生存\n首页\n归档\n作品\n搜索\n友链\n关于\n\n夜间模式生活感悟从抖音看见世界的参差\n2024-05-16\n阅读时长: 6 分钟AI 摘要在这篇文章中，作者深入探讨了社交媒体如何影响我们对世界的理解和体验。通过抖音这一平台，作者反思了数字内容的量产化和真实体验的重要性。文章批判了社交媒体上信息的简化和平面化，提出了信息茧房的概念，并给出了避免陷入这一陷阱的建议。作者还讨论了旅行的不同阶段，强调了深入了解文化和历史的必要性。最后，文章呼吁读者主动寻找信息，避免被算法和资本驯化，保持对高密度信息的阅读能力。document.addEventListener(\"DOMContentLoaded\",function(){const e=document.querySelector(\".ai-explanation-content\").textContent;new TypeIt(\"#ai-explanation\",{strings:e,speed:10,lifeLike:!0,waitUntilVisible:!0}).go()})昨晚，洗漱完毕后，我躺在床上刷着抖音。可在连续刷了十几条短视频以后，我突然对眼前的一切感到深深的绝望。或许是高德地图在抖音购买了推广，我的耳边一直充斥着同一条文案：我可以死在去远方的路上，但不能没去过远方。我心想，五一假期刚刚过去两周，资本真的需要在这个时间点，再次点燃人们“仗剑走天涯”的梦想吗？仔细一看，原来是高德地图新上线了一个“点亮城市”的功能，可以显示用户去过那些城市。Payne 说，一切能被拿来攀比的终将被拿来攀比。于是，在马头琴那深沉而悠扬的旋律衬托下，《边境》这首歌一旦响起，甚至比许巍的《蓝莲花》更具杀伤力。看着由大数据量产而来的、模式化的文案/配乐，我不免惶恐。究竟是从什么时候开始，数字幽灵夺舍碳基生命。一眼望去，互联网上充斥着各种电子压缩饼干，它们试图将日常生活高度提纯、浓缩、收敛，并使你相信那就是真实的生活。听起来像是硅基生命要统治地球？我想说的是，在 GPT4 以及未来的 AIGC 面前，这不过是一种迷人的 tricks。相比于被一小部分人类愚弄，我宁愿被 AI 愚弄，因为它真的要比我聪明许多。对此，我心悦诚服。如何杀掉一只羊？并生活在真实之中李诞有一期播客，标题叫做《如何杀掉一只羊？并生活在真实之中》，他以一个内蒙古人的视角，讲述了真实的内蒙古是如何杀掉一只羊，以及真实的内蒙古是什么样子。你或许听说过，下面这些关于内蒙古的刻板印象，比如：住在蒙古包里、高考射箭骑马、人均摔跤能手等等。如果现在给你两个选项，一个是“虚假但快乐”，一个是“真实且复杂”，你会怎么选呢？对此，李诞给出的答案是：让迪士尼成为迪士尼，让内蒙古成为内蒙古。我有时觉得，一生都特别“关键”的中国人，或许连整个人生都是打卡式的。君不见，小红书的打卡基本等同于去过一个地方，大家使用着别人使用过的文案，站在别人站过的打卡点，做着别人做过的事情，然后拍照发图。在种种确定性的背后，全然没有自由、随机的探索，更遑论深入理解。再比如大家喜闻乐见的爬山，现在全都是统一的“登山杖十八式”造型，我实在想不明白，曾经引领过非主流文化的90后，以追求个性、与众不同为荣，何以如今变得千人一面、毫无新意呢？香港演员梁家辉曾被人称为“千面影帝”，他在电影中饰演各种类型的角色，从严肃的历史人物到喜剧角色，从黑帮老大到普通市民，他都能精准地把握角色特点。可如今的朋友圈、微博、小红书，更像是某种角色扮演游戏，批量生产着紫萱/紫霞。假使换一张脸上去，坦白讲又有什么区别呢？只要你愿意，想你的风可以吹到月球甚至火星。虽然，我不明白这个姿势是什么意思，可大家都说帅，那就是真的帅在接触 ChatGPT 这类 AI 产品以后，一个最为直观的感受是，当 AI 完全掌握了小红书这类文案的写作套路以后，它完全可以取代人类写出更加“爆款”的文案。在这种前提下，在一堆充斥着 Emoji 的文字中间，自诩为高等智慧生物的人类，其实早已处在一种非常尴尬的境地。试想一下，如果让 AI 学会那些在流传在社交网络上的打卡地、拍照姿势、服装道具，那么，在这场名为模仿、盲从、跟风的竞赛中，人类到底还有多少胜算？也许，我们都不愿意承认，我们本质上就是一群习惯于攀比和跟风的乌合之众。可你只要仔细听一听，便会发现这座以“个性化推荐”为主要卖点的信息茧房，正在极速地降低我们的表达能力。整个平台/互联网的话语空间正在一点点塌陷，我们每天面对的词库严重同质、扁平和局限，越来越多的词语正在被压缩和稀释。每一天，大家都是面对着同一套网络流行语词库，越来越习惯于接收低信息密度的内容。这看似是大大降低了理解成本，可你回想一下，我们每天摄入的信息当中，真正有用的又有多少呢？ 《年会不能停》这个电影上映以后，我的同事特别喜欢讲“对齐颗粒度”，我不知道这是好事还是坏事。“家人们”，我唯一知道的事情是，我们渐渐患上了“失语症”，回忆一下，形容某种食物特别好吃，除了“咔咔炫”、“嘎嘎香”，你还能想起什么？如果是我，我会讲“唇齿留香”、“大快朵颐”等等。正如你会更喜欢我叫你朋友，而不是“老铁”或是“亲”，扪心自问，你果真喜欢这种小红书式的表达方式吗？一个擦得锃亮的鱼缸，虽然看起来漂亮精致，可惜触摸不到真实和丰富就像每一个短视频，我现在听到的都是视频制作者的声嘶力竭和急功近利，大致的含义都是在表达：如果你不 XXX，那么你就会 YYY。这里的 XXX 和 YYY 大家可以自行代入具体场景。我想说的是，即便是为了刺激流量，其途径并非只有贩卖焦虑这一条路。人都想看到自己想看到的一切，这当然无可厚非。不过，在我心目中“真”显得更为重要，就像刘亦菲饰演的花木兰，只有在卸下伪装时、以女性真实面貌出现时，她才会意识到自己有多么强大。比如,在发朋友圈的问题上，有人觉得应该要多发朋友圈，因为朋友圈的访客是未来的自己；有人觉得应该要少发朋友圈，因为成熟的人不会有那么多情绪写在脸上。我的观点是：想发就发，不想发就不发。在这一期播客的评论区，有人将当下的互联网，比喻为“一个擦得锃亮的鱼缸”，虽然看起来漂亮精致，可惜触摸不到真实和丰富。我有个朋友，经常开着 N 倍速看 B 站，我不免怀疑这是否和打卡式旅游如出一辙。或许，现在的 AI 可以在数秒内阅读完一篇文章或者一个网页，可这些知识永远都属于 AI 而不属于你。出去旅行的时候，我总想着避开网红店的纷扰，可大众点评和小红书总是会将你带去那些地方。曾经引以为傲的推荐算法，可以做到个性化推荐、千人千面，何以如今大家的兴趣爱好、言行举止越来越趋向雷同？到底是我们在通过消费行为驯化数据，还是我们心甘情愿被资本和消费主义驯化？虽然楚门离开了，可 “楚门的世界” 一直都在某时某刻，我意识到，这个世界是立体的、复杂的，而社交媒体则试图将其平面化、简单化。我承认，信息在经过浓缩化、碎片化、符号化以后会更利于传播。但是，一个丰富、多元、复杂的世界，是不是愿意被简化、该不该被简化呢？我想，这是一个非常深刻的问题。按照小红书上的理论，旅行的第一个阶段是穿梭于各大热门城市之间，可时间久了以后便觉得哪里都一样。此时，便进入第二个阶段：徒步、雪山、潜水、无人区、极限运动等等，在将以上种种都体验过以后，突然开始怀念城市里的人来人往、花开花落。此时，便进入第三个阶段：学习文化知识、欣赏古建筑、了解城市历史/变迁等等。再往后，第四个阶段便是走出国门、看世界。虽然，这只是其中一个版本，但是这足以说明问题。那就是，我们固执地认为这个世界看一次就够了，有多少人会在旅行过后故地重游呢？以一种符号式的、标签式的方式认知这个世界是否可行呢？自然是可以的，只不过这多少有些肤浅！那么，如何摆脱信息茧房的诅咒呢？我个人认为，首先，是从被动接收转变为主动订阅，比如使用 RSS 来代替微信公众号；其次，尽可能读英文的或者第一手的资料，比如官方文档、论文，而不是经过咀嚼或者裁剪等二次加工的产物；然后，定期调整个人行为/使用习惯，避免落入推荐算法的陷阱。大模型是可以生成更多的信息，可如果我们失去了高密度信息的读取能力，这一切又有什么意义呢，难道我们一定要让自己活成 GDP 和点击率吗？\n打赏微信打赏支付宝打赏随笔\n感悟\n真实\n参差\nBY-NC-SA 4.0\n\n最后更新 2024-05-28window.addEventListener(\"DOMContentLoaded\",()=>{renderMathInElement(document.querySelector(`.article-content`),{delimiters:[{left:\"$$\",right:\"$$\",display:!0},{left:\"$\",right:\"$\",display:!1},{left:\"\\\\(\",right:\"\\\\)\",display:!1},{left:\"\\\\[\",right:\"\\\\]\",display:!0}]})})相关文章俯仰之间：五一小长假出行记似花还似非花杂感·七月寄望再见，人间四月天读《一个叫欧维的男人决定去死》.waline-container{background-color:var(--card-background);border-radius:var(--card-border-radius);box-shadow:var(--shadow-l1);padding:var(--card-padding)}.waline-container .vcount{color:var(--card-text-color-main)}var waline=new Waline({el:\"#waline\",serverURL:\"https://waline.yuanpei.me/\",lang:\"zh\",dark:\"auto\",path:window.location.href,requiredMeta:[\"nick\",\"mail\"]})©\n2014 -\n2024 元培 · 元视角Built with Hugo v0.126.1Theme Stack designed by Jimmy已创作 268 篇文章，共计 1013813 字\n\n\n\n\n搜索\n\n归档2024\n82023\n112022\n272021\n422020\n26更多分类编程语言\n114生活感悟\n49数据存储\n20游戏开发\n17读书笔记\n16更多标签云OpenTelemetry\n韩寒\nCastle\n孤独\nRedis\n命令\nWeb API\n桌面\nLinux\n回家\n日本文学\n异步\n防疫\nECharts\n贝塞尔曲线\nWechat\n回忆\n西漂\nJava\n我是猫\nIDE\n关卡系统\nZTree\nPrometheus\n.NET Core\n更多let createBadge=window.createBadge;createBadge(\"Git\",\"f6a4ca5\",\"#35495e\",\"#ffc107\"),createBadge(\"Hugo\",\"v0.126.1\",\"#35495e\",\"#41b883\")"}', '2024-05-29 10:01:07.789401', 'admin', '2024-05-29 10:03:13.008707', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788063707822166016, '4026f60857f44937872676bb05bcfde1', '高要求', 1787695651350515712, 2, '2024-05-08 13:15:43.288245', '2024-05-08 13:15:52.06926', '8.78', 2, '{"Url":"https://gudong.site/2023/04/27/daily.html","Title":"高要求","Content":"对于一个观点，如何能匹配上别人的挑战，需要自己功课做的够，就像自己要去做一个主题分享，一般都是把自己熟练研究的结果进行汇总输出，分享过程中如果有人有疑问提出，一般大都可以很容易的进行解答，因为工作做的够。相反一些事情，得出结论的过程可..."}', '2024-05-08 12:29:43.218934', 'admin', '2024-05-08 13:15:52.069264', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1795746097172451328, '41852b6379ff49bf9780621d2246c310', 'db530182a33e48a1b16ae723df86cc73', 1778611670021705728, 2, '2024-05-29 17:17:13.049723', '2024-05-29 17:17:19.878004', '6.83', 1, '听起来似乎荒诞不经，可荒诞之处又何至于此呢？在沸沸扬扬的“胖猫”事件中，不管是当事人还是旁观者，都以一种近乎癫狂的姿态参与其中。陈奕迅在《六月飞霜》中唱道：“最可笑的，喊亦正常；最悲壮的，笑亦正常”，这让我不禁思考，“哪一个可，发育正常”。广元的第二站是昭化古城，如果你对这个名字感到陌生，那么，葭萌关这个名字或许能瞬间唤起你的三国记忆，《三国演义》中著名的“张飞挑灯夜战马超”，正是发生在这里。再往前追溯五百多年，秦惠文王嬴驷派张仪、司马错伐蜀，同样在葭萌关发生过激战。现存的昭化古城是明代重建的，当我漫步在狭窄的古城街道上，我不断地将眼前的景象与心中的三国景象相比较。往事越千年，一切早已面目全非，昔日的年金戈铁马早已无处寻觅。这座在今天看来颇为逼仄的城池，何以能成为历史上兵家必争的战略要地？', '2024-05-29 17:16:47.570958', 'admin', '2024-05-29 17:17:19.87803', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1795746593195036672, 'a163a0a288d14138bb72c3cec8be89e9', '行走在消逝中.md', 1778611670021705728, 2, '2024-05-29 17:19:13.052397', '2024-05-29 17:20:24.085148', '71.03', 0, 'D:\Projects\2024\PostgreSQL.Embedding\PostgreSQL.Embedding\Upload\a163a0a288d14138bb72c3cec8be89e9\行走在消逝中.md', '2024-05-29 17:18:45.833841', 'admin', '2024-05-29 17:20:24.085152', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788100002673987584, '152f53eebb5b4ed89e232ba0ad8daafa', 'IETF：互联网精神的典范 - 阮一峰的网络日志', 1787689108462768128, 2, '2024-05-08 14:59:48.275577', '2024-05-08 15:01:51.597444', '123.32', 2, '{"Url":"https://www.ruanyifeng.com/blog/2011/03/ietf.html","Title":"IETF：互联网精神的典范 - 阮一峰的网络日志","Content":"\n\nif (/mobile/i.test(navigator.userAgent) || /android/i.test(navigator.userAgent)) document.body.classList.add(''mobile'');\n\n/*\nwindow.addEventListener(''load'', function(event) {\n  setTimeout(function () {\n    hab(''#sup-post-2'');\n    hab(''#cre-inner'');\n  }, 1000);\n});\n*/\n\n    \n        \n\n            \n    \n        \n\n\n            阮一峰的网络日志  » 首页 » 档案\n\n\n\n\n\n  \n  \n  \n  \n  \n\n\n\n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n            \n                \n\n\n                    \n                        \n\n\n                            \n                                \n\n\n\n\n上一篇：中国经济：转变和对策 \n下一篇：Firebug控制台详\n\n\n\n\n    \n                                    \n                                        分类：\n                                        \n                                            科技爱好者\n                                        \n                                    \n    \n\n\n                                            \n\n\n⇐ \n ⇒\n\n\n\n\n\n\n                          \n\n                                    IETF：互联网精神的典范\n\n\n\n\n                                        \n\n                                            作者： 阮一峰\n                                    日期： 2011年3月20日\n\n\n\n\n\n\n\n\n\n\n\n\n\n                                \n                                \n\n                                    \n                                        今年是IETF成立25周年，ars technica有一篇介绍文章，回顾了它的辉煌成就。\n                                    \n\n\n                                    \n                                        IETF的全称是\"互联网工程任务组\"（Internet Engineering Task Force），主要目标是协调制定互联网标准。\n\n几乎所有重要的网络底层协议，都是由IETF制定的，比如TCP协议、IP协议、HTTP协议、等等。可以毫不夸张地说，没有IETF就没有互联网。\n\n\n\n我一直以为，IETF与其他权力机构没有不同----一些人高高在上，另一些人服从指挥。但是，读完介绍文章以后，我震惊了，IETF居然是网友自发组织，并且自我管理的！\n\nIETF这样介绍自己：\n\n\n\n\"我们没有会员的概念，所有人都可以参与，都可以报名参加会议。只要加入邮件列表，你就可以把自己看做是一个IETF成员。\n\n----摘自The Tao of IETF（英文版，中文版）\"\n\n\n\n这就是说，任何人都可以加入IETF，提出自己的互联网标准！这与其他标准制定机构（比如ANSI、ISO、IEEE等等）截然不同，那些机构的门槛很高，有时你必须是主权国家，才有资格加入。\n\nIETF的运行原则，也完全是民主平等的。\n\n\n\n\"我们拒绝国王、主席和投票。我们相信共识和运行的代码。（We reject kings, presidents and voting.  We believe in rough consensus and running code.）\"\n\n\n\n对于IETF来说，你是谁不重要，只要得到大多数人的赞同，或者代码运行得更好，你的标准就有可能成为整个互联网的标准。之所以不搞投票，只是为了避免平均主义，只需要那些真正关心和了解这个问题的人保持一致就行了。\n\nIETF的邮件列表是不受审查的，任何意见都可以发表。虽然有志愿者担任的管理员，但那是为了保证讨论秩序，而不是为了控制讨论。\n\n\n\n\"某个领域的负责人（area director）是选出来协助大家思考，而不是接管整个思考过程。（ADs are selected to think, not to just run the process.）\"\n\n\n\nIETF进一步地明确表示，虽然自己制定标准，但并不硬性推广标准，更不谋求控制互联网。\n\n\n\n\"如果你对IETF感兴趣，只是因为你想当互联网的监督者，那么你可能会对我们极其失望。（If your interest in the IETF is because you want to be part of the overseers, you may be badly disappointed by the IETF.）\"\n\n\n\n\n\n\"我们的角色是指出方向，而不是下命令。（its role is to set directions rather than to give orders.）\"\n\n\n\nIETF每年举办三次年会，它关于年会的定位和安排，更是令人瞠目结舌，将自由合作的精神发挥到了极致。\n\n\n\n\"我们的年会与别的年会不一样。我们的主要目的，是为了让大家放松一下。\"\n\n\n\n\n\n\"任何人都可以报名参加。你不要有精神负担，完全可以为了感受一下气氛，而来参加会议。\"\n\n\n\n\n\n\"穿着的一般原则是''根据天气而定''（如果你一整天都不打算去室外，我们的建议就是怎么舒服怎么穿）。\"\n\n\n\n\n\n\"因为必须在胸口佩戴姓名标签，所以上身最好穿衬衫或短上衣。下身推荐穿普通的裤子或者裙子。许多新人穿着西装亮相会场，他们会感到很尴尬，因为其他人只穿T恤、牛仔裤（如果天气允许，不少人还会穿短裤）和拖鞋。\"\n\n\n\n\n\n\"如果你对发言者的主题不感兴趣，你可以低头阅读自己的email和上网，这是很普遍的现象。\"\n\n\n\n\n\n\"所有会议都可以随便坐，任何平整的表面、任何有电源插座的地方，都可以坐下。你可以与旁边的人，一边打开笔记本电脑，一边讨论。\"\n\n\n\n\n\n在IETF身上，充分体现了自由、开放、合作、共享的精神。这是互联网的核心价值。正是这样的机构，以及信奉这些价值的人，奠定了互联网的基础。\n\n可是，当今世界还有另一些人，他们拼命地想要管制互联网，把它变成一个封闭的、信息不能自由流动的、等级制的、存在中央管理机构的\"监狱\"。只要IETF这样的机构存在，只要IETF制定的标准构成互联网的基础，那些企图控制互联网的人就注定会可耻地失败。\n\n（完）\n\n                                    \n\n                                \n    \n                                \n\n文档信息\n\n版权声明：自由转载-非商用-非衍生-保持署名（创意共享3.0许可证）\n发表日期： 2011年3月20日\n\n\n                                \n\n                            \n\n  \n    .wwads-content .wwads-text {font-size:1.4em;} .wwads-cn img{ border : none;}\n  \n  \n\n\n\n相关文章\n\n\n2015.06.02: 能量墙与家庭电厂\n\n                           \n                              去年下半年，《财新周刊》缺一个专栏作者，问我写不写。\n\n                           \n\n\n\n \n2013.10.25: 比特币的用途\n\n                           \n                              这两周，比特币（bitcoin）的价格大幅上涨，我也凑热闹关注了一阵。\n\n                           \n\n\n\n \n2012.12.06: 为什么数码相机可以拍出彩色照片？\n\n                           \n                              上个月（11月13日），83岁的柯达公司退休工程师布赖斯·拜尔（Bryce Bayer）去世。\n                           \n\n\n\n \n2012.01.23: 现代医学200年\n\n                           \n                              今年是世界最有影响力的医学杂志《新英格兰医学杂志》（The New England Journal of Medicine, NEJM）创刊200周年。\n                           \n\n\n\n \n\n\n\n\n                    \n\n                    \n\n\n    \n    \n        \n    留言（18条）\n\n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    ufo\n\n 说：\n                \n\n            \n        \n        \n            很难相信世界有这么一个组织\n        \n\n\n\n                   2011年3月20日 18:07\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    不是方滨兴\n\n 说：\n                \n\n            \n        \n        \n            GFW的执行者会可耻的失败！\n        \n\n\n\n                   2011年3月20日 18:09\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    小骆驼商队\n\n 说：\n                \n\n            \n        \n        \n            \"某个领域的负责人（area director）是选出来协助大家思考，而不是接管整个思考过程。（ADs are selected to think, not to just run the process.）\"\n\n这里的理解有点问题吧……应该是说某个领域的负责人也要自己思考，而不是仅仅维持讨论秩序。（与此相对的是某些会议主持人只维持会场秩序，不发表自己的观点。）\n        \n\n\n\n                   2011年3月20日 18:18\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Para\n\n 说：\n                \n\n            \n        \n        \n            http://chinese.engadget.com/2011/03/18/china-tightens-grip-on-vpn-access-amid-pro-democracy-protests-g/\n\njust see ,don''t explain.\n        \n\n\n\n                   2011年3月20日 20:34\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Dianso\n\n 说：\n                \n\n            \n        \n        \n            决策权还是BOSS\n        \n\n\n\n                   2011年3月20日 21:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    陈子江\n\n 说：\n                \n\n            \n        \n        \n            向往。。。\n        \n\n\n\n                   2011年3月20日 22:06\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    TY\n\n 说：\n                \n\n            \n        \n        \n            控制互联网注定失败，但控制一个局域网却垂手可成;-(\n        \n\n\n\n                   2011年3月21日 15:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    sasiky\n\n 说：\n                \n\n            \n        \n        \n            自由、开放、合作、共享的精神。这是互联网的核心价值。\n        \n\n\n\n                   2011年3月21日 23:21\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    猫科动物\n\n 说：\n                \n\n            \n        \n        \n            这个在上研的时候接触过一点\n其实IETF开年会的时候，很多与会者背后都是有大公司存在的\n比根据他们的说法，很多具体的协议，都是已经画好地盘的——比如说，某某协议的负责人是思科的，某某协议是爱立信的。当负责该协议的工作组要进行年会时，相关的设备厂商就会很热心的参与到邮件列表的讨论，并且进行原型开发。\n还有一点就是，比如说制定某个协议的主席是思科的人，然后一个爱立信或者华为的人到这里提出意见，想发Draft并最终加入到IETF文档，鉴于双方存在利益冲突，主席一般是不乐意的，还是希望这些工作由思科的人完成。然后双方就扯皮了...\n\n当然，讨论的氛围还是很友好的。\n        \n\n\n\n                   2011年3月22日 13:58\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    fisher\n\n 说：\n                \n\n            \n        \n        \n            老猫说的也是人之常情。不过，我想IETF不会诞生在英国。英国诞生ISO。\n        \n\n\n\n                   2011年3月24日 01:48\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    bush\n\n 说：\n                \n\n            \n        \n        \n            讀完這篇文章我也很震驚，這麽重要的組織居然自己還是第一次聽說。大概是因為國人一向崇拜權威，所以對開放性的組織都不太在意～\n        \n\n\n\n                   2011年3月24日 09:11\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    fromoon\n\n 说：\n                \n\n            \n        \n        \n            IETF的公信力还可以。\n互联网大会上各国质疑比较多的是ICANN，比如它现在的主席是美国前情报官员，哪位可以找到公开的选举记录，看看有没有一点IETF的精神典范？\n\n如果把国际互联网的管理都交给IETF，应该得到美国以外大部分国家的通过。\n        \n\n\n\n                   2011年3月28日 12:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    真想\n\n 说：\n                \n\n            \n        \n        \n            一篇幼稚到不行的文章。任何组织都有自己的一套标榜性文字，你看看联合国宪章，各国的宪法，Google也说自己不做恶，比尔盖茨号称是慈善家，比这个说的好听的多。但是事实呢？\n        \n\n\n\n                   2011年5月 9日 22:33\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Ricky\n\n 说：\n                \n\n            \n        \n        \n            \n引用真想的发言：\n\n一篇幼稚到不行的文章。任何组织都有自己的一套标榜性文字，你看看联合国宪章，各国的宪法，Google也说自己不做恶，比尔盖茨号称是慈善家，比这个说的好听的多。但是事实呢？\n\n\n\n同意“任何组织都有自己的一套标榜性文字”。\n不过请列举你想说的IETF的“事实”。\n        \n\n\n\n                   2011年5月27日 09:53\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    alex\n\n 说：\n                \n\n            \n        \n        \n            cisco在里面的话语权是很强势的，也不是绝对的公平。\n        \n\n\n\n                   2011年6月 5日 11:22\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    w\n\n 说：\n                \n\n            \n        \n        \n            \n引用真想的发言：\n\n一篇幼稚到不行的文章。\n\n\n\n第一个句话就暴露了你的基因。\n        \n\n\n\n                   2011年8月31日 16:10\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    御宅暴君\n\n 说：\n                \n\n            \n        \n        \n            有个笑话叫「互联网大会」。\n        \n\n\n\n                   2015年5月25日 16:50\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kk\n\n 说：\n                \n\n            \n        \n        \n            确实是“一篇幼稚到不行了的文章”\n        \n\n\n\n                   2018年10月31日 11:33\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n    \n\n\n    \n    \n    \n        我要发表看法\n        \n\n        \n            \n\n            \n                \n                \n                \n                \n                \n                \n                \n                \n            \n                    您的留言\n                    （HTML标签部分可用）\n                    \n                \n                    \n                        您的大名：\n                           «-必填\n                    \n                    \n                        电子邮件：\n                           «-必填，不公开\n                    \n                    \n                        个人网址：\n                           «-我信任你，不会填写广告链接\n                    \n                    \n                        \n                        记住个人信息？\n                    \n                \n                    \n                    \n                    \n                \n                \n                \n\n正在发表您的评论，请稍候\n\n           \n\n\n\n\n                       «- 点击按钮\n                \n            \n\n\n        \n    \n\n    \n\n\n\n\n\n\n\n                        \n                    \n\n                \n            \n        \n         \n            \n\n  \n\n      \n\n\n     \n\n       \n       \n         Weibo | \n         Twitter |\n         GitHub\n       \n     \n     Email: [email protected]\n     \n  \n  \n\n\n  \n\n\n\nfunction insertLine(e,t){for(var n=0;n<t;n++)e.parentNode.insertBefore(document.createElement(\"p\"),e)}function getImg(){if(!window[\"main-content\"])return!1;for(var e,t=Array.prototype.slice.call(window[\"main-content\"].getElementsByTagName(\"img\")),n=0;n<t.length;n++){if(\"display: none !important;\"===(e=t[n]).getAttribute(\"style\"))return e;if(n===t.length-1)return!1}}function toObjectUrl(e,t){return fetch(e).then(e=>e.blob()).then(e=>{t(URL.createObjectURL(e))})}function toDataURL(e,t){var n=new XMLHttpRequest;n.open(\"get\",e),n.responseType=\"blob\",n.onload=function(){var e=new FileReader;e.onload=function(){t(this.result)},e.readAsDataURL(n.response)},n.send()}setTimeout(function(){var e=getImg();e&&(insertLine(e.parentNode,2),toObjectUrl(e.src,function(t){var n=document.createElement(\"p\"),r=document.createElement(\"img\");r.src=t,n.appendChild(r),e.parentNode.parentNode.insertBefore(n,e.parentNode)}))},3e3);\n                                                                                                                                                                                                                                                                                                                                                                                                                                                     \n\n  (function(i,s,o,g,r,a,m){i[''GoogleAnalyticsObject'']=r;i[r]=i[r]||function(){\n  (i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),\n  m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)\n  })(window,document,''script'',''//www.google-analytics.com/analytics.js'',''ga'');\n\n  ga(''create'', ''UA-46829782-1'', ''ruanyifeng.com'');\n  ga(''send'', ''pageview'');\n\n\n\n\n\nvar supportImg = document.querySelector(''#support-img'');\n\nif (supportImg && _hmt) {\n  _hmt.push([''_trackEvent'', ''banner'', ''load'']);\n  supportImg.addEventListener(''click'', function () {\n    _hmt.push([''_trackEvent'', ''banner'', ''click'']);\n  }, false);\n}\n\nvar homepageImg = document.querySelector(''#homepage_sponsor'');\nif (homepageImg && _hmt) {\n  _hmt.push([''_trackEvent'', ''homepage-banner'', ''load'']);\n  homepageImg.addEventListener(''click'', function () {\n    _hmt.push([''_trackEvent'', ''homepage-banner'', ''click'']);\n  }, false);\n}\n\n\n\n\n        \n    \n(function(){if (!document.body) return;var js = \"window[''__CF$cv$params'']={r:''8807890cad6a48c9'',t:''MTcxNTE1MTIzNC42NDEwMDA=''};_cpo=document.createElement(''script'');_cpo.nonce='''',_cpo.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'',document.getElementsByTagName(''head'')[0].appendChild(_cpo);\";var _0xh = document.createElement(''iframe'');_0xh.height = 1;_0xh.width = 1;_0xh.style.position = ''absolute'';_0xh.style.top = 0;_0xh.style.left = 0;_0xh.style.border = ''none'';_0xh.style.visibility = ''hidden'';docume