INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1818167881876246528, 'fb9279e103d74d439eac48b589c8c429', '《十堂沟通训练课》——陈默，沟通≠聊天，沟通方法并非公式 – 阿锋的小宇宙', 1787695651350515712, 2, '2024-07-30 14:13:33.950789', '2024-07-30 14:13:34.196062', '0.25', 2, '{"Url":"https://feng.pub/0720247155.html","Title":"《十堂沟通训练课》——陈默，沟通≠聊天，沟通方法并非公式 – 阿锋的小宇宙","Content":""}', '2024-07-30 14:12:57.5912', 'admin', '2024-07-30 14:13:34.196186', 'admin');
INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1788103630495289344, '2499eef8816b4fda8341bffb4a00c851', '科技爱好者周刊（第 293 期）：一周是一年的2% - 阮一峰的网络日志', 1787689108462768128, 2, '2024-05-08 15:08:23.588937', '2024-05-08 15:13:57.233198', '333.64', 2, '{"Url":"https://www.ruanyifeng.com/blog/2024/03/weekly-issue-293.html","Title":"科技爱好者周刊（第 293 期）：一周是一年的2% - 阮一峰的网络日志","Content":"\n\nif (/mobile/i.test(navigator.userAgent) || /android/i.test(navigator.userAgent)) document.body.classList.add(''mobile'');\n\n/*\nwindow.addEventListener(''load'', function(event) {\n  setTimeout(function () {\n    hab(''#sup-post-2'');\n    hab(''#cre-inner'');\n  }, 1000);\n});\n*/\n\n    \n        \n\n            \n    \n        \n\n\n            阮一峰的网络日志  » 首页 » 档案\n\n\n\n\n\n  \n  \n  \n  \n  \n\n\n\n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n            \n                \n\n\n                    \n                        \n\n\n                            \n                                \n\n\n\n\n上一篇：科技爱好者周刊（第 2\n下一篇：科技爱好者周刊（第 2\n\n\n\n\n    \n                                    \n                                        分类：\n                                        \n                                            周刊\n                                        \n                                    \n    \n\n\n                                            \n\n\n⇐ \n ⇒\n\n\n\n\n\n\n                          \n\n                                    科技爱好者周刊（第 293 期）：一周是一年的2%\n\n\n\n\n                                        \n\n                                            作者： 阮一峰\n                                    日期： 2024年3月15日\n\n\n\n\n\n\n\n\n\n\n\n\n\n                                \n                                \n\n                                    \n                                        这里记录每周值得分享的科技内容，周五发布。\n\n                                    \n\n\n                                    \n                                        本杂志开源，欢迎投稿。另有《谁在招人》服务，发布程序员招聘信息。合作请邮件联系（[email protected]）。\n\n封面图\n\n\n\n安徽芜湖轻轨，为了穿越人行天桥和高架，有一段设计成了波峰波谷，乘坐时会有一点过山车的感觉。（via）\n\n一周是一年的2%\n\n纳特·弗里德曼（Nat Friedman）曾经是 GitHub 的 CEO，现在是一名风险投资家。\n\n\n\n他的个人网站首页，写着一些自己的信条。其中有一条，让我很震动。\n\n\n  他写道：\"一周是一年的2%。\"\n\n\n我一直觉得，每周七天是很短的时间，尤其是发布周刊以后，更是过得飞快。\n\n但是，他的这句话让我意识到，每周其实是一年当中很重要的组成部分。虚度一周就是虚度一年的2%。\n\n你没有几周可以虚度的。只要多浪费几周，这一年很快过去。\n\n反过来，过好这一周，那么这一年的2%就有价值了。只要这样多过几周，一年就会变得很充实，有拿得出手的成果。\n\n我坚持写周刊，每周记录一点东西，整理一些思考，现在想起来，其实就是在督促自己过好这一年的2%。\n\n维苏威古卷\n\n公元79年10月24日，意大利的维苏威火山爆发，一天之内就毁灭了两万多人的庞贝古城。\n\n火山灰掩盖了整座城市，其中有一栋房子存放了各种书籍。直到18世纪，这栋房子才重新被发现，下面是考古学家的建筑复原图。\n\n\n\n房子里面的1800多卷纸莎草古书，都已经完全碳化。\n\n\n\n\n\n考古学家试图展开这些烧焦的古书，但是纸张一碰就碎。\n\n\n\n每一页的碎片就像下面这样。\n\n\n\n没有人能从这些烧焦的古书上，读出一个字。\n\n2019年，一位美国科学家提出了一种新方法，使用短红外高光谱成像技术，对这些古卷进行 3D 扫描，然后虚拟建模，在不接触古卷的情况下，就可以展开或压平每一页，从而复现上面的笔迹。\n\n\n\n\n\n下面是扫描后的页面结果。\n\n\n\n问题是上面的笔迹还是很模糊，无法确定是哪一个字母，更不要说读出句子了。\n\n2023年3月，在一些风险投资者的资助下，古卷保管单位举办了一次比赛，邀请全世界的程序员参加，要求使用机器学习，认出上面是什么字母，破解古卷的内容，奖金总额高达100万美元。\n\n主办单位原以为，一年之内成功的可能性不到30%。但是，2023年10月，21岁的内布拉斯加大学的学生卢克·法里托（Luke Farritor）就读出了第一个单词 ΠΟΡΦΥΡΑϹ（紫色）。\n\n\n\n后来，他与正在柏林读博士的纳德（Youssef Nader）、瑞士苏黎世理工学院的机器人专业的学生席里格（Julian Schilliger），组成了一个团队，致力于建立一个完整的 AI 模型识别这些古书。\n\n\n\n他们最终在比赛的截止日期前（2024年1月1日）识别出了2000个字符。\n\n下面就是采用他们的模型，识别出来的碎片，内容已经清晰还原出来了。\n\n\n\n2月5日，主办单位宣布，他们获得了本次比赛的第一名。\n\n\n\n由于比赛结果令人鼓舞，主办单位扩展了自己的目标，接下来将对90%的维苏威古卷，进行扫描和识别，彻底破解两千年前的罗马人在书里写了什么。\n\n他们所用的模型，已经全部开源，就放在 GitHub。任何人都可以安装和运行，尝试改进他们的模型，获得更好的结果。\n\n现代科技的发展，真像神话一样，烧成灰的纸都能辨认出文字。\n\n科技动态\n\n1、纸钢琴\n\n学习钢琴通常需要一个专门的琴房，如果是普通人家庭，购置和练习钢琴是非常不方便的。\n\n有人在 GitHub 上发布了一个令人耳目一新的项目，尝试零成本地解决这个问题，让你可以随时随地练习钢琴。\n\n\n\n你只要准备两张 A4 纸，水平连接在一起，两端各画两个方框，然后就可以在纸上练习钢琴了。\n\n这个软件通过摄像头，捕捉你的手指动作，转化成钢琴击键，让电脑发出对应的琴声。\n\n\n\n虽然这样不会有击键的感觉，但是不失为一种简单的解决方案。如果配一个仿真键盘，就比较完善了。\n\n2、赛博卡车的配套帐篷\n\n特斯拉的赛博卡车（Cybertruck）在2019年公布时，曾经展示了一个配套帐篷，可以装在车辆后部。\n\n当时展示的照片是这样的。\n\n\n\n现在，这个帐篷终于发货了，它实际长下面这样，与早先的设计大相径庭。\n\n\n\n而且，它的售价高达3000美元（约人民币22000元），令车主十分不满。\n\n\n\n自从赛博卡车正式发货以来，市场反响并不热烈，越来越多的人认为，它可能是特斯拉的一个失败产品。\n\n3、取消的苹果汽车\n\n上周有消息说，经过10年研发以后，苹果公司在内部宣布，取消了苹果汽车项目。\n\n\n\n现在网上有苹果汽车的原型照片泄漏。如果照片属实，苹果研发的竟然不是轿车，而是小货车。\n\n\n\n这实在难以置信，因为小货车无论造得多么好，销量肯定小于轿车。\n\n以前就有人指出，苹果不太可能真的去做汽车，因为市场规模太小。特斯拉一年销售不到200万辆，这种销量对苹果来说是不值得做的。\n\n文章\n\n1、黄仁勋斯坦福大学演讲（中文）\n\n\n\n2024年3月初，英伟达CEO黄仁勋回到母校美国斯坦福大学，进行了两次演讲，讲述了自己的经历和对 AI 的看法。这是演讲的中文翻译。\n\n2、Meta 的 H100 集群细节（中文）\n\nMeta 公司公布了他们的 AI 集群细节。大家可以看看，AI 需要投多少钱。\n\n\n\n他们现在有两个集群，每个集群包含了24576块英伟达 H100 GPU（上图）。H100 的价格是2.5万美元～4万美元/块，也就是说，每个集群就要花费数亿美元。\n\n更厉害的是，他们计划今年年底前，将 H100 扩充至35万块，远期达到60万块。\n\n3、注释可以减少技术债务（英文）\n\n\n\n作者列举了代码注释的好处，论述得很好，然后大力推荐使用 Javadoc。\n\n4、VS Code 的垂直 Tab 页（英文）\n\n\n\n本文介绍如何在 VS Code 编辑器里面，放置一个垂直的边栏，进行标签切换。\n\n5、Linux 服务器加固指南（英文）\n\n\n\n你架设了一台 Linux 虚拟主机，如何让它变得更安全，本文列出了详细的操作步骤。\n\n6、家庭电子实验室设置指南（英文）\n\n\n\n作者介绍他的家庭电子实验室的配置，喜欢玩电子装置的朋友可以参考。\n\n7、为什么去赌场是个坏主意（英文）\n\n\n\n作者写了一些简单的小程序，使用蒙特卡罗模拟，演示如果不断博彩（比如1000次）会是多少收益。\n\n工具\n\n1、Rot\n\n一个命令行工具，用来对密码进行加密/解密，这样就可以把密码保存在公开的代码库了。\n\n2、Angie\n\n\n\n一个 nginx 的分叉版本，由原始团队成员开发，增加了一些功能。类似的项目还有 free nginx。\n\n3、LaVague\n\n\n\n一个很有意思的概念产品，使用文字指令来操作网站，比如输入文字\"点击按钮\"，它就自动点击网页按钮，底层用的是浏览器自动化框架 Selenium。\n\n4、LapisCV\n\n\n\n基于 Obsidian / Typora 编辑器的 Markdown 简历模板，可以导出 PDF 文件。（@YiNNx 投稿）\n\n5、OpenAPI-UI\n\n\n\n该工具生成 Swagger 或 OpenAPI 3 格式的 API 接口文档，也可当作简洁的 Postman 使用。（@rookie-luochao 投稿）\n\n6、git-diff-view\n\n\n\n一个 React/Vue 组件，用来显示 git diff 的结果，类似于 GitHub 的样式。（@MrWangJustToDo 投稿）\n\n7、 AI 时间线\n\n\n\n一个有意思的网站，输入一个关键词，自动生成该词的时间线，上图是输入\"github\"的生成结果，它的代码仓库在 GitHub。（@zhugezifang 投稿）\n\n8、Earthworm\n\n\n\n一个开源的 Web 程序，通过连词造句的方式，经过不断重复练习英语，线上体验。（@cuixiaorui 投稿）\n\n9、Postal\n\n\n\n一个开源的电子邮件服务器，自带 Web 界面。\n\n10、briefsky\n\n\n\n一个开源的天气预报前端，可以接入各种天气数据源。\n\n11、Qaul\n\n\n\n一个可以离线通信的软件，允许一群用户在不联网的情况下，通过本机的共享 WiFi 发送消息。\n\n12、Piped\n\n\n\n一个开源的 Youtube 网页前端 UI。\n\n13、Riffusion\n\n\n\n一个免费的 AI 工具，给出一段提示，它会生成相应的歌曲，并且是带有歌词、人声演唱的。\n\n资源\n\n1、IP 信息查询合集 \n\n这个仓库收集可以查询 IP 信息的免费网站。（@ihmily 投稿）\n\n2、TypeScript 互动教程\n\n\n\n通过一个个小练习，讲授 TypeScript 语法。\n\n3、学习现代 C++\n\n\n\n一个讲解 C++ 基础知识的自学教程。\n\n4、Virustotal\n\n\n\n软件病毒检测引擎，可以上传文件进行扫描，也可以指定需要扫描的文件或网址。\n\n图片\n\n1、世界第一艘深海潜水器\n\n1925年，美国博物学家威廉·毕比（William Beebe）提出想造一种深海潜水器。当时，潜艇的最大下潜深度只有117米，而且没有窗口可以观察外部。\n\n威廉·毕比设计的潜水器为球形，因为球形最抗压，由铸铁制造，里面只能待一个人。\n\n\n\n潜水器的后端是一个透明的入舱口，采用螺栓固定，只能从外部打开，内部无法打开。\n\n\n\n前端是三个窗口，由76毫米厚的石英制成，这是当时最坚固的透明材料。\n\n\n\n潜水器内部由高压气瓶提供氧气，采用钠钙和氯化钙吸收二氧化碳和水分。\n\n1930年6月11日，它第一次下水，达到了400米深度，1934年达到了900米的深度。\n\n\n\n此后，威廉·毕比停止使用这个潜水器了，因为他觉得已经达到了观测海底生物的目的。\n\n而且，它不是很安全。每次下水，它必须系着钢缆，要靠钢缆拉上来。万一钢缆在压力下出现问题，或者钩子断了，潜水器里面的人必死无疑。\n\n\n\n现在，这个潜水器的复制品，陈列在美国华盛顿特区的国家地理博物馆。\n\n\n\n文摘\n\n1、乔布斯的遗照\n\n苹果创始人乔布斯的遗照是如何拍摄的？\n\n\n\n2011年10月5日，史蒂夫·乔布斯去世，苹果网站用苏格兰摄影师艾伯特·沃森 (Albert Watson) 在2006年拍摄的这张照片来纪念他。\n\n许多人知道，乔布斯并不太喜欢被人拍摄，这对摄影师是一种挑战。\n\n拍摄当日，摄影师被告知拍摄时间只有一小时，然而他却胸有成竹地说，只要三十分钟便能完成。\n\n艾伯特·沃森建议史蒂夫·乔布斯稍微前倾，说道：\"想象一下，桌子对面有四五个人不同意你的观点，但你知道自己是对的。\"\n\nSteve Jobs 凝视着镜头，眼神十分坚定，给人一种充满信念与智慧的感觉。这就是这幅肖像照的创作过程。\n\n离开时，史蒂夫·乔布斯看了一眼照片，问他是否可以拥有它，并说这\"也许是我拍过的最好的照片\"。\n\n\n\n五年后，艾伯特·沃森接到苹果公司的电话，问他是否仍保留那张乔布斯的照片。他当时感到十分惊讶，同时意识到事情的紧迫性，随即找到照片并发送给苹果公司。\n\n当天晚上，苹果在官网宣布乔布斯去世的消息，并附上艾伯特·沃森拍摄他的肖像，这张照片在网站上刊登了一个月，之后也成为乔布斯传记的封面，成为21世纪最广为人知的人像照片之一。\n\n言论\n\n1、\n\n以后不会存在\"程序员\"这种职业了，只要会说话，人人都具备程序员的能力。未来的编程语言只会剩下两种，一种叫做英文，一种叫做中文。\n\n-- 李彦宏，百度董事长\n\n2、\n\n你无事可做时，未来看起来就会让人灰心丧气。我早已放弃了为人生寻找某种意义之类的事情，但我确实尝试寻找一些有趣的事情来做。\n\n-- Hacker News 读者\n\n3、\n\n电影《奥本海默》之中，奥本海默在黑板上写方程式，解释核裂变。这个方程式在物理上是完全正确的。\n\n大多数观众不会意识到这一点，但这让我这个物理学家感觉很好，黑板上有正确的方程！\n\n-- 电影《奥本海默》的物理学顾问\n\n4、\n\n幸福的三大要素是：有要做的事（something to do）、有要爱的人（someone to love）、有寄予希望的东西（something to hope for）。\n\n-- 亚历山大·查默斯，19世纪美国著名医生\n\n往年回顾\n\n永不丢失的网络身份（2023 #246）\n\n掌机的未来（2022 #196）\n\n网课应该怎么上（2021 #146）\n\n在线教育不等于录制视频（2020 #96）\n\n（完）\n\n                                    \n\n                                \n    \n                                \n\n文档信息\n\n版权声明：自由转载-非商用-非衍生-保持署名（创意共享3.0许可证）\n发表日期： 2024年3月15日\n\n\n                                \n\n                            \n\n  \n    .wwads-content .wwads-text {font-size:1.4em;} .wwads-cn img{ border : none;}\n  \n  \n\n\n\n相关文章\n\n\n2024.04.26: 科技爱好者周刊（第 298 期）：轮到硬件工程师吃香了\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。（[通知] 下周五一假期，周刊暂停一次。）\n\n                           \n\n\n\n \n2024.04.19: 科技爱好者周刊（第 297 期）：饮水鸟玩具\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n2024.04.12: 科技爱好者周刊（第 296 期）：xz 后门的作者 Jia Tan 是谁？\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。\n\n                           \n\n\n\n \n2024.03.29: 科技爱好者周刊（第 295 期）：巧妙的灯泡钟\n\n                           \n                              这里记录每周值得分享的科技内容，周五发布。（[通知] 下周清明节假期，周刊暂停一次。）\n\n                           \n\n\n\n \n\n\n\n\n                    \n\n                    \n\n\n    \n    \n        \n    留言（64条）\n\n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Eric\n\n 说：\n                \n\n            \n        \n        \n            \"你无事可做时，未来看起来就会让人灰心丧气。\"\n\"幸福的三大要素是：有要做的事（something to do）、有要爱的人（someone to love）、有寄予希望的东西（something to hope for）。\"\n\n结合起来看很有意义\n        \n\n\n\n                   2024年3月15日 08:39\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kkk\n\n 说：\n                \n\n            \n        \n        \n            qaul.net 无法访问了，无论是否要梯子\n        \n\n\n\n                   2024年3月15日 08:39\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    JackeyLove\n\n 说：\n                \n\n            \n        \n        \n            “纸莎草古书”是不是“莎草纸古书”啊\n        \n\n\n\n                   2024年3月15日 08:52\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    原州铁匠\n\n 说：\n                \n\n            \n        \n        \n            为什么电脑端访问不了了\n        \n\n\n\n                   2024年3月15日 09:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    刘的娃\n\n 说：\n                \n\n            \n        \n        \n            Earthworm 这个通过手敲英语句子进行学习,效果挺不错的,大家可以体验下\n        \n\n\n\n                   2024年3月15日 09:08\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    KK\n\n 说：\n                \n\n            \n        \n        \n            王小川评价李彦宏：\n\n\n···\n\n李彦宏之前不是在讲百度更懂中文嘛，他很幻觉主义——你说他现实主义吗？理想主义吗？都不是。去年2月就喊出比OpenAI只差两个月，已经够有幻觉了。\n\n腾讯新闻《潜望》：你怎么看他最近说，在中文上，文心大模型4.0已经超过GPT-4？\n\n王小川：他举的例子你看了吗？写词写得更好。他说GPT写一个《沁园春》，都分不清楚4个字、5个字开头，他们自己也分不清楚，你可以试试。他不仅对GPT有误解，对自己的产品有误解，对国内模型也有误解，那不是活在自己幻觉中？\n\n你得问他的团队怎么汇报工作，他怎么形成这样一个输入。这个人是一个也正直，也聪明的人，更多是信息输入不太对。\n···\n        \n\n\n\n                   2024年3月15日 09:10\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    风夜岚\n\n 说：\n                \n\n            \n        \n        \n            请李彦宏董事长先开除自己旗下所有公司的程序员，滑稽????\n        \n\n\n\n                   2024年3月15日 09:14\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kedduck\n\n 说：\n                \n\n            \n        \n        \n            一周是一年的2%\n        \n\n\n\n                   2024年3月15日 09:27\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    archxm\n\n 说：\n                \n\n            \n        \n        \n            \n引用KK的发言：\n\n王小川评价李彦宏：\n\n\n···\n\n李彦宏之前不是在讲百度更懂中文嘛，他很幻觉主义——你说他现实主义吗？理想主义吗？都不是。去年2月就喊出比OpenAI只差两个月，已经够有幻觉了。\n\n腾讯新闻《潜望》：你怎么看他最近说，在中文上，文心大模型4.0已经超过GPT-4？\n\n王小川：他举的例子你看了吗？写词写得更好。他说GPT写一个《沁园春》，都分不清楚4个字、5个字开头，他们自己也分不清楚，你可以试试。他不仅对GPT有误解，对自己的产品有误解，对国内模型也有误解，那不是活在自己幻觉中？\n\n你得问他的团队怎么汇报工作，他怎么形成这样一个输入。这个人是一个也正直，也聪明的人，更多是信息输入不太对。\n···\n\n\n\n资本要求，必须拥抱AI\n        \n\n\n\n                   2024年3月15日 09:30\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Leeelics\n\n 说：\n                \n\n            \n        \n        \n            乔布斯的摄影师很会引导人，当我们面对镜头时通常是感到大脑空白，有一丝慌乱，但是当你想象你进入到某种情景时又会重回自然。这张照片也充分展现了乔布斯的笃定\n        \n\n\n\n                   2024年3月15日 09:36\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kop1989\n\n 说：\n                \n\n            \n        \n        \n            “自从赛博卡车正式发货以来，市场反响并不热烈”\n\n能不能说说这个结论的信息源和推导逻辑？毕竟目前cybertruck已经有200万个预订了，二手交易都是加价出售的。\n        \n\n\n\n                   2024年3月15日 09:39\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    刘的娃\n\n 说：\n                \n\n            \n        \n        \n            要找远程工作的,学习英语的 推荐文章中提到的 Earthworm\n        \n\n\n\n                   2024年3月15日 09:44\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kerin\n\n 说：\n                \n\n            \n        \n        \n            一年不过52周，每新的一周，看着周数的增加，比起‘日’或‘月’更有紧迫感\n        \n\n\n\n                   2024年3月15日 09:56\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    kerin\n\n 说：\n                \n\n            \n        \n        \n            \n引用kerin的发言：\n\n一年不过52周，每新的一周，看着周数的增加，比起‘日’或‘月’更有紧迫感\n\n\n\n所以相比于过于频繁或过于缓慢的日和月的变化，我更喜欢使用周来追踪我的时间\n        \n\n\n\n                   2024年3月15日 09:59\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    steel z\n\n 说：\n                \n\n            \n        \n        \n            \n引用原州铁匠的发言：\n\n为什么电脑端访问不了了\n\n\n\n可以啊。你是不是用了反广告插件，换一个浏览器就可了。我在debian12里用firefox会提示我由于反广告插件所以本网页无法显示。\n\n        \n\n\n\n                   2024年3月15日 10:08\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    卫海\n\n 说：\n                \n\n            \n        \n        \n            看到第一张图，脑海里：芜湖，起飞\n        \n\n\n\n                   2024年3月15日 10:15\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    路人\n\n 说：\n                \n\n            \n        \n        \n            纸钢琴很有创意\nAI时间线只有我打不开吗？ http://www.ai-timeline.top/\nRiffusion 可惜只支持英文歌词，25个单词\n\n        \n\n\n\n                   2024年3月15日 10:31\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    自留地天可汗\n\n 说：\n                \n\n            \n        \n        \n            先不说算力的差距。相对于英文，中文世界汉字语料的数量和质量，都极堪忧。\n        \n\n\n\n                   2024年3月15日 10:32\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    randomx\n\n 说：\n                \n\n            \n        \n        \n            极好的博客，让我这个高中生在尽量远离互联网的情况下（互联网让我浮躁，不能安于学习），也能快速获取有价值的科技信息，保持对科技的关注，帮助我节省了许多时间，感谢阮老师！\n        \n\n\n\n                   2024年3月15日 12:16\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    大模型打工仔\n\n 说：\n                \n\n            \n        \n        \n            meta令人震撼的不是集群规模和投入而是技术储备和技术创新。就像苹果造车一样，也许你会看到苹果造车失败了，但是你无法想象苹果造车给全世界自动驾驶行业培养了多少工程师，推动了多少技术创新和进步。每个中国人读书时都学过一句话站在巨人的肩膀上，其实现实世界没有巨人，都是前人一点一点的推动。\nmeta能够有雄心管理几十万台gpu，背后是大量的人才储备和技术创新，gpu的管理和cpu有着巨大的差异，这样的差异需要时间和资源的长期投入，根据我的观察，未来五年内，网络通信和集群运维会有巨大的创新和进步，在卷代码量和tcp握手和挥手八股文之前建议先考虑下几十万台gpu的通信组网和存储瓶颈如何解决。\n国内外的差异不在模型的精准度，也不在人家能出视频，我们只能做文本，而在背后的技术创新和积累。\n当你在笑话国内大模型的时候，也问问你自己你对相关行业和领域有过贡献吗？还是只会在网上匿名喷。\n        \n\n\n\n                   2024年3月15日 12:19\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    一个程序员\n\n 说：\n                \n\n            \n        \n        \n            李彦宏不要随地大小便！好吗？\n        \n\n\n\n                   2024年3月15日 13:23\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    面向未来\n\n 说：\n                \n\n            \n        \n        \n            我很喜欢周刊，每周必看！感谢阮老师的分享！\n        \n\n\n\n                   2024年3月15日 13:23\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    大虫弗雷德\n\n 说：\n                \n\n            \n        \n        \n            @大模型打工仔：\n\n非常中肯，只有实际身体力行参与过实际的事情才会有这种感受\n        \n\n\n\n                   2024年3月15日 13:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    matt\n\n 说：\n                \n\n            \n        \n        \n            李彦宏能说出任何一个用中文写出来的程序吗？这种人真令人厌烦啊\n        \n\n\n\n                   2024年3月15日 13:54\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    橙子橙\n\n 说：\n                \n\n            \n        \n        \n            百度感觉快要完蛋了，根本搜不到什么有用的信息，不是百家号就是百度知道\n        \n\n\n\n                   2024年3月15日 14:12\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zzr\n\n 说：\n                \n\n            \n        \n        \n            以后不会存在\"百度\"这种公司了，只要会说话，人人都具备百度的能力。未来的搜索引擎只会剩下两种，一种叫做谷歌，一种叫做百度。\n        \n\n\n\n                   2024年3月15日 14:29\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    qiba\n\n 说：\n                \n\n            \n        \n        \n            苹果不造车那个想起那个台湾间谍的笑话，不造啊\n        \n\n\n\n                   2024年3月15日 14:41\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    高高在下，沾沾自喜\n\n 说：\n                \n\n            \n        \n        \n            收获：\n一周是一年的2%\n要有需要做的事、要爱的人、寄予希望的事物，这样才会对未来不容易灰心丧气。\n随着ai的快速发展，新的变革和机遇也在不断出现，比如基础性的程序员行业会被替代的可能。\n这期周刊对我个人而言，比近几期周刊更感觉干货满满，感谢阮老师分享。\n        \n\n\n\n                   2024年3月15日 14:53\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    石樱灯笼\n\n 说：\n                \n\n            \n        \n        \n            以后不会存在\"XXXX\"这种XX了，只要会说话，人人都具备XX的能力。未来的XX只会剩下两种，一种叫做百度，一种叫做谷歌。\n\n        \n\n\n\n                   2024年3月15日 15:07\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    夜白\n\n 说：\n                \n\n            \n        \n        \n            本期周刊又让我看到了程序员的创造力，程序员改变世界不是在吹牛\n纸钢琴和英语学习这两个感觉是很棒的产品\n尤其是纸钢琴，如果以后可以把这种动作捕捉加入扩展到教育的各个领域（例如舞蹈学习，足球训练，等等）\n就像AlphaGo打败人类以后人类又向AlphaGo学习创造了新的围棋套路一样\n通过AI深度学习创造出垂直领域的最强的一个，然后再通过例如纸钢琴这种形式反哺给人类，那么人类的技艺也会有很大的提升\n尤其可以打破中国传统艺术中师傅带徒弟1对1人为制造稀缺的情况，也许AI可以促进人类真正迎来百花齐放，百家争鸣的新时代\n\n        \n\n\n\n                   2024年3月15日 15:15\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Ww\n\n 说：\n                \n\n            \n        \n        \n            李彦宏的话确实没必要放这里\n        \n\n\n\n                   2024年3月15日 16:13\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Kifary\n\n 说：\n                \n\n            \n        \n        \n            这一期不错，除了某度的发言。\n        \n\n\n\n                   2024年3月15日 16:25\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    大名\n\n 说：\n                \n\n            \n        \n        \n            什么时候李彦宏的话也变成焦点了？\n        \n\n\n\n                   2024年3月15日 16:28\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    帽子反戴单手炒菜\n\n 说：\n                \n\n            \n        \n        \n            推荐个谷歌插件 uBlackList, 直接把百度的一二级域名全部拉黑,你就会发现搜索回归了正常的体验.\n        \n\n\n\n                   2024年3月15日 17:00\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    zy\n\n 说：\n                \n\n            \n        \n        \n            你无事可做时，未来看起来就会让人灰心丧气。我早已放弃了为人生寻找某种意义之类的事情，但我确实尝试寻找一些有趣的事情来做。 \n\n这句话说的挺有意思的，有趣的事远比有意义的事更能让人付诸行动。\n        \n\n\n\n                   2024年3月15日 17:36\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    xiaolong\n\n 说：\n                \n\n            \n        \n        \n            纸钢琴，真是扯淡，荒唐！！！\n        \n\n\n\n                   2024年3月15日 20:45\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Aidi\n\n 说：\n                \n\n            \n        \n        \n            这期没有在 RSS 上，反馈一下~\n        \n\n\n\n                   2024年3月16日 09:32\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Donne\n\n 说：\n                \n\n            \n        \n        \n            很有启发意义的一期\n- 一周是一年的2%\n- 幸福的三大要素是：有要做的事（something to do）、有要爱的人（someone to love）、有寄予希望的东西（something to hope for\n        \n\n\n\n                   2024年3月16日 16:49\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    半亩方塘\n\n 说：\n                \n\n            \n        \n        \n            芜湖轻轨，挺有意思。\n        \n\n\n\n                   2024年3月16日 16:55\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    cartesian\n\n 说：\n                \n\n            \n        \n        \n            \n引用帽子反戴单手炒菜的发言：\n\n推荐个谷歌插件 uBlackList, 直接把百度的一二级域名全部拉黑,你就会发现搜索回归了正常的体验.\n\n\n\n哈哈哈哈哈，我愿称之为最佳评论！最佳插件！\n百度这种荼毒玩意儿，至少让中国的科技倒退10年！\n别急着反驳，在其位不谋其职，难道不是一种发展的阻塞吗？\n\n        \n\n\n\n                   2024年3月16日 17:40\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Nash\n\n 说：\n                \n\n            \n        \n        \n            能纯粹的献身于技术研究是一件幸福的事啊\n        \n\n\n\n                   2024年3月16日 21:55\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    sevenlg\n\n 说：\n                \n\n            \n        \n        \n            李彦宏真是大言不残\n        \n\n\n\n                   2024年3月17日 09:43\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    CHOCOLAT\n\n 说：\n                \n\n            \n        \n        \n            这个李彦宏怎么老是在发表暴论？\n        \n\n\n\n                   2024年3月17日 11:06\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    星空\n\n 说：\n                \n\n            \n        \n        \n            \n引用大模型打工仔的发言：\n\nmeta令人震撼的不是集群规模和投入而是技术储备和技术创新。就像苹果造车一样，也许你会看到苹果造车失败了，但是你无法想象苹果造车给全世界自动驾驶行业培养了多少工程师，推动了多少技术创新和进步。每个中国人读书时都学过一句话站在巨人的肩膀上，其实现实世界没有巨人，都是前人一点一点的推动。\nmeta能够有雄心管理几十万台gpu，背后是大量的人才储备和技术创新，gpu的管理和cpu有着巨大的差异，这样的差异需要时间和资源的长期投入，根据我的观察，未来五年内，网络通信和集群运维会有巨大的创新和进步，在卷代码量和tcp握手和挥手八股文之前建议先考虑下几十万台gpu的通信组网和存储瓶颈如何解决。\n国内外的差异不在模型的精准度，也不在人家能出视频，我们只能做文本，而在背后的技术创新和积累。\n当你在笑话国内大模型的时候，也问问你自己你对相关行业和领域有过贡献吗？还是只会在网上匿名喷。\n\n\n\n苹果的工程师很多都是挖特斯拉的，而且搞了十年一个demo都没发布，失败就是失败，不要瞎吹苹果了\n        \n\n\n\n                   2024年3月17日 13:05\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    Spike\n\n 说：\n                \n\n            \n        \n        \n            \n引用kop1989的发言：\n\n“自从赛博卡车正式发货以来，市场反响并不热烈”\n\n能不能说说这个结论的信息源和推导逻辑？毕竟目前cybertruck已经有200万个预订了，二手交易都是加价出售的。\n\n\n\n这种无根据的论点周刊里出现很多次了，所以看看就好\n\n        \n\n\n\n                   2024年3月17日 15:19\n | #\n | 引用\n\n\n\n    \n\n        \n    \n        \n        \n    \n        \n            \n\n                \n                    \n\n                    solitas\n\n 说：\n                \n\n            \n        \n        \n            有事去做，有人去爱，有所寄托。\n        \n\n\n\n               