INSERT INTO "document_import_records" ("id", "task_id", "file_name", "knowledge_base_id", "queue_status", "process_start_time", "process_end_time", "process_duration_time", "document_type", "content", "created_at", "created_by", "updated_at", "updated_by") VALUES (1796074011646627840, '8a8e332e08b84bb699ef402bfd2ead8a', '介绍新的必应。用于搜索的 AI 驱动的助手。', 1778611670021705728, 2, '2024-05-30 15:06:46.126895', '2024-05-30 15:14:59.943815', '493.82', 2, '{"Url":"https://www.microsoft.com/zh-cn/edge/features/the-new-bing?form=MA13FJ","Title":"介绍新的必应。用于搜索的 AI 驱动的助手。","Content":"\n    \n        跳至主要内容\n     \n        \n                   功能和技巧      \n                更多\n                Search      \n                下载 Edge\n                           您可能尚无法使用此功能。功能可用性和功能可能因设备类型、市场和浏览器版本而异。   介绍新的必应。用于搜索的 AI 驱动的助手。 在一个地方聊天、搜索和寻找灵感。了解如何使用新的必应来获取摘要答案、创建草稿、图像等。 \n                立即试用\n                    \n    特征\n\n    AI 支持\n 介绍新的必应。用于搜索的 AI 驱动的助手。 在一个地方聊天、搜索和寻找灵感。了解如何使用新的必应来获取摘要答案、创建草稿、图像等。 \n                立即试用\n                             tips 提示和技巧   faq \n        常见问题\n       \n            *\n            功能可用性和功能特性可能因设备类型、市场和浏览器版本的不同而有所差异。        \n            \n                \n\n    \n        \n\n\n\n\n        \n            \n                \n                    \n                        新增内容\n                        \n                            \n                                Surface Pro 9\n                            \n                            \n                                Surface Laptop 5\n                            \n                            \n                                Surface Laptop Go 2\n                            \n                            \n                                Surface Go 3\n                            \n                            \n                                Microsoft Copilot\n                            \n                            \n                                Microsoft 365\n                            \n            