                     Azure\n                            \n                            \n                                Dynamics 365\n                            \n                            \n                                Microsoft 365\n                            \n                            \n                                Microsoft Advertising\n                            \n                            \n                                Copilot for Microsoft 365\n                            \n                            \n                                Microsoft Teams\n                            \n\n                        \n                        \n                    \n                    \n                        开发人员与 IT\n                        \n                            \n                                开发人员中心\n                            \n                            \n                                文档\n                            \n                            \n                                Microsoft Learn\n                            \n                            \n                                Microsoft 技术社区\n                            \n                            \n                                Azure 市场\n                            \n                            \n                                AppSource\n                            \n                            \n                                Microsoft Power Platform\n                            \n                            \n                                Visual Studio\n                            \n\n                        \n                        \n                    \n                    \n                        公司\n                        \n                            \n                                招贤纳士\n                            \n                            \n                                关于 Microsoft\n                            \n                            \n                                公司新闻\n                            \n                            \n                                Microsoft 隐私\n                            \n                            \n                                投资人\n                            \n                            \n                                可持续发展 \n                            \n\n                        \n                        \n                    \n                \n        \n    \n                中文(中国)\n\n            \n        \n            你的隐私选择选择退出图标\n            \n            \n            \n            \n        \n        你的隐私选择\n    \n\n        \n                \n        \n            你的隐私选择选择退出图标\n            \n            \n            \n            \n        \n        你的隐私选择\n    \n\n        \n            \n        消费者健康隐私\n    \n\n        \n            \n                                \n                    与 Microsoft 联系\n                \n                \n                    隐私\n                \n                \n                    管理 Cookie\n                \n                \n                    使用条款\n                \n                \n                    商标\n                \n                \n                    关于我们的广告\n                \n                \n                    京ICP备09042378号-6\n                \n\n                © Microsoft 2024\n                \n            \n        \n    \n    \n\n\n\n    const globalPrivacyControlEnabled = navigator.globalPrivacyControl;\n\n    const GPC_DataSharingOptIn = (globalPrivacyControlEnabled) ? false : checkThirdPartyAdsOptOutCookie();\n\n    function checkThirdPartyAdsOptOutCookie() {\n        try {\n            const ThirdPartyAdsOptOutCookieName = ''3PAdsOptOut'';\n            var cookieValue = getCookie(ThirdPartyAdsOptOutCookieName);\n            return cookieValue != 1;\n        } catch {\n            return true;\n        }\n    }\n\n    function getCookie(cookieName) {\n        var cookieValue = document.cookie.match(''(^|;)\\\\s*'' + cookieName + ''\\\\s*=\\\\s*([^;]+)'');\n        return (cookieValue) ? cookieValue[2] : '''';\n    }\n\n\n\n\n\n\n\n    \n        \n\n    \n\n     window.__NUXT__=(function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N){i.title=a;i.titleTemplate=a;i.description=a;i.favicon=b;i.noindex=c;k[0]={label:D,variant:\"yellow\",url:a,newTab:c};k[1]={label:\"AI 支持\",variant:\"green\",url:a,newTab:c};l[0]={type:\"browserfeature\",label:\"立即试用\",buttonVariant:f,ecidAction:\"cta\",icon:b,iconSize:a,knownCustomActionId:a,customActionId:a,accessibleLabel:a,inProgressLabel:a,completedLabel:a,disableWhenComplete:c,errorLabel:a,disableActionCompletion:c,nonEdgeMessageHtml:\"\\u003Cp\\u003E若要试用必应聊天，请登录到 Microsoft Edge，然后选择浏览器工具栏中的必应聊天图标。功能可用性和功能可能因设备类型、市场和浏览器版本而异。\\u003C\\u002Fp\\u003E\",prompt:a,lookupFeatureId:a,featureId:\"hub_apps_cd4688a9-e888-48ea-ad81-76193d56b1be\",dryRunFeatureId:a,postFeatureLaunchUrl:f,disableAfterClick:a,delaySeconds:a,id:\"try-now\"};m.type=\"image\";m.id=a;m.image={libraryPublicUrl:\"https:\\u002F\\u002Fedgestatic.azureedge.net\\u002Fshared\\u002Fcms\\u002Flrs1c69a1j\\u002Fsection-images\\u002F\",libraryId:\"section-images\",extension:E,fileId:\"cf76c5a846e74fd48e09b2926291ce1c\",publicUrl:\"https:\\u002F\\u002Fedgestatic.azureedge.net\\u002Fshared\\u002Fcms\\u002Flrs1c69a1j\\u002Fsection-images\\u002Fcf76c5a846e74fd48e09b2926291ce1c.png\",width:1920,height:1080};m.frame=\"border\";m.alt=a;m.fit=\"contain\";m.position=t;m.maxWidth=a;m.alignX=a;m.alignY=a;m.stretchToFill=a;m.layers=[];m.mediaAction={mediaActionUrl:f,mediaActionMessageStyle:a,mediaActionMessage:a,mediaActionUrlNewTab:a};m.mediaActions=[];p[0]={schema:e,id:\"write-something-new\",path:a,title:\"写一些新的东西\",description:\"\\u003Cp\\u003E你有一个绝妙的想法，你想与世界分享。但是你不知道如何用语言表达它。别担心，只要告诉必应你想写什么以及你想怎么写。无论是一首诗、一个故事、一个膳食计划还是其他东西，必应都可以帮助你将想法转化为引人入胜的创意内容。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[1]={schema:e,id:\"comparison-made-easy\",path:a,title:\"比较变得简单\",description:\"\\u003Cp\\u003E您不必浪费时间浏览不同的网站或输入多个问题。只需说出您想要比较的内容以及您希望比较的详细程度。必应将完成剩下的工作。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[2]={schema:e,id:\"get-summaries\",path:a,title:\"获取摘要\",description:\"\\u003Cp\\u003E无需阅读所有内容即可了解某些内容的要点。只需告诉必应你想知道的摘要，它就会给你一个要点的简明摘要——无论是一本书、一部电视剧、一份研究文件还是其他东西。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[3]={schema:e,id:\"search-the-way-you-talk-and-text\",path:a,title:\"搜索您的说话方式和短信方式\",description:\"\\u003Cp\\u003E无论您是使用文字和表情符号，还是保持简短甜蜜或冗长而详细，必应都能满足您的需求。只要问一问，必应就会明白你的意思。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[4]={schema:e,id:\"create-an-image-directly-in-bing-chat\",path:a,title:\"直接在必应聊天中创建图像\",description:\"\\u003Cp\\u003E直接从您的文字创建图像。您只需键入要查看的内容，必应聊天就会为您生成它。您还可以要求 \\u003Ca href=\\\"https:\\u002F\\u002Fmicrosoft.sharepoint.com\\u002Fsites\\u002Fknowledgecenter\\u002F_layouts\\u002F15\\u002FTopicPagePreview.aspx?topicId=AL_yy-dKYjRFixrwjIi6q2IOQ&amp;amp;topicName=Bing%20Chat&amp;amp;lang=en\\\" rel=\\\"noopener noreferrer\\\" target=\\\"_blank\\\"\\u003E必应聊天\\u003C\\u002Fa\\u003E&nbsp;根据需要修改或改进图像。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[5]={schema:e,id:\"ask-follow-up-questions\",path:a,title:\"提出后续问题\",description:\"\\u003Cp\\u003E必应聊天中的每个对话都会保留初始问题的上下文。这使您可以澄清过去的问题并获得更多信息，而无需重新开始。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[6]={schema:e,id:\"where-do-i-find-the-ai-powered-answer-select-the-chat-tab\",path:a,title:\"我在哪里可以找到 AI 驱动的答案？选择聊天标签页\",description:\"\\u003Cp\\u003E新的必应可以直接在搜索结果页面上提供 AI 驱动的答案。如果未看到 AI 生成的预期答案，请选择“聊天”选项卡以查看必应聊天响应。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[7]={schema:e,id:\"tell-bing-how-to-frame-its-answer\",path:a,title:\"告诉必应如何构建其答案\",description:\"\\u003Cp\\u003E你问必应一个问题。必应给你一个很好的答案。但是，如果您想以另一种方式描述答案怎么办？没关系！只需使用提示告诉必应你想要什么。你可以让必应向你展示答案，包括要点、表格、简单的孩子单词等。这既简单又有趣！\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[8]={schema:e,id:\"ask-complex-questions-and-get-relevant-answers\",path:a,title:\"提出复杂的问题并获得相关答案\",description:\"\\u003Cp\\u003E不要在细节上退缩！您的问题越具体，您的答案就越相关。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[9]={schema:e,id:\"get-near-real-time-results\",path:a,title:\"获得近乎实时的结果\",description:\"\\u003Cp\\u003E必应的人工智能答案不仅限于遥远过去的信息。无论你是在寻找最近的事件还是突发新闻，必应都会帮助你从最新的搜索结果中提取所需的内容。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[10]={schema:e,id:\"improve-something-you''ve-already-written\",path:a,title:\"改进你已经写过的东西\",description:\"\\u003Cp\\u003E想改善你现有的写作吗？只需粘贴您的文本并告诉必应您要更改的内容。您可以添加幽默，简洁，正式等。例如，你可以要求Bing为你老板的老板润色你的电子邮件，或者用一些创造力来充实你的推文。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[11]={schema:e,id:\"change-the-tone-or-style-of-what-you-write\",path:a,title:\"改变你写的语气或风格\",description:\"\\u003Cp\\u003E必应不仅可以帮助您写作，还可以用不同的语气和风格为您的写作增添趣味。只需告诉必应你想要什么，然后看着奇迹发生。例如，你可以要求必应：&nbsp;\\u003C\\u002Fp\\u003E\\u003Cul\\u003E\\u003Cli\\u003E为您的文本&nbsp;添加一些幽默、专业或讽刺\\u003C\\u002Fli\\u003E\\u003Cli\\u003E将您的文本组织成项目符号、段落甚至俳句&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E让你的文字听起来像是你最喜欢的角色&nbsp;写的\\u003C\\u002Fli\\u003E\\u003C\\u002Ful\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[12]={schema:e,id:\"improve-the-images-you-create-in-bing-chat\",path:a,title:\"改进在必应聊天中创建的图像\",description:\"\\u003Cp\\u003E不要满足于不完美的图像！您可以随时通过要求更改后续消息来根据自己的喜好调整它们。例如，您可以要求必应更改图像的配色方案、样式或背景详细信息。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[13]={schema:e,id:\"change-the-style-of-an-image-you-create\",path:a,title:\"更改您创建的图像的样式\",description:\"\\u003Cp\\u003E必应可以帮助您探索不同风格的艺术，并为您生成令人惊叹的图像！只需告诉Bing你喜欢什么风格，然后看着魔术发生。您可以从许多选项中进行选择，例如：&nbsp;\\u003C\\u002Fp\\u003E\\u003Cul\\u003E\\u003Cli\\u003E波普艺术&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E超现实主义&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E印象派&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E立体主义&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E素描&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E数字艺术&nbsp;\\u003C\\u002Fli\\u003E\\u003Cli\\u003E水彩&nbsp;\\u003C\\u002Fli\\u003E\\u003C\\u002Ful\\u003E\\u003Cp\\u003E这还不是全部！如果您提出要求，必应会以更多样式让您大吃一惊。\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[14]={schema:e,id:\"find-your-previously-created-images\",path:a,title:\"查找以前创建的映像\",description:\"\\u003Cp\\u003E您可以随时通过访问 bing.com\\u002Fcreate 并选择创建来查看之前创建的图像。不要错过这个欣赏杰作的机会！\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};p[15]={schema:e,id:\"press-the-windows-key-to-start-your-search–only-on-your-windows-pc\",path:a,title:\"按 Windows 键开始搜索 - 仅在您的 Windows PC 上\",description:\"\\u003Cp\\u003E您只需按几下键即可找到所需的内容。无论您是在 Windows 10 还是 Windows 11 上，只需按 Windows 键，键入并按回车键。开始搜索就是这么简单！&nbsp;\\u003C\\u002Fp\\u003E\\u003Cp\\u003E还可以单击 Windows 搜索框中的“必应聊天”图标，直接跳转到必应聊天体验。&nbsp;\\u003C\\u002Fp\\u003E\",disclaimer:a,actions:[],actionsVisibleOnCard:c,thumb:b,tags:b};return {layout:\"fluent\",data:[{}],fetch:{},error:b,state:{uhf:{cssIncludes:\"\\r\\n        \\u003Clink rel=\\\"stylesheet\\\" href=\\\"https:\\u002F\\u002Fwww.microsoft.com\\u002Fonerfstatics\\u002Fmarketingsites-wcus-prod\\u002Fchinese-simplified\\u002Fshell\\u002F_scrf\\u002Fcss\\u002Fthemes=default.device=uplevel_web_pc\\u002F1b-9d8ed9\\u002Fc9-be0100\\u002Fa6-e969ef\\u002F43-9f2e7c\\u002F82-8b5456\\u002Fa0-5d3913\\u002F43-5a5ab8\\u002Fca-ae3ce4?ver=2.0&amp;_cf=02242021_3231\\\" type=\\\"text\\u002Fcss\\\" media=\\\"all\\\" \\u002F\\u003E\\r\\n    \",footerHtml:\"\\r\\n            \\u003Cdiv id=\\\"footerArea\\\" class=\\\"uhf\\\"  data-m=''{\\\"cN\\\":\\\"footerArea\\\",\\\"cT\\\":\\\"Area_coreuiArea\\\",\\\"id\\\":\\\"a2Body\\\",\\\"sN\\\":2,\\\"aN\\\":\\\"Body